insert into public.verses (scripture_id, chapter, verse, speaker_sa, speaker_iast, sanskrit, transliteration, meaning_en, meaning_hi) values
  ('gita', 1, 1, 'धृतराष्ट्र उवाच', 'dhṛtarāṣṭra uvāca', 'धर्मक्षेत्रे कुरुक्षेत्रे समवेता युयुत्सवः ।
मामकाः पाण्डवाश्चैव किमकुर्वत संजय ॥', 'dharmakṣetre kurukṣetre samavetā yuyutsavaḥ |
māmakāḥ pāṇḍavāś caiva kim akurvata saṃjaya ||', null, null),
  ('gita', 1, 2, 'संजय उवाच', 'saṃjaya uvāca', 'दृष्ट्वा तु पाण्डवानीकं व्यूढं दुर्योधनस्तदा ।
आचार्यमुपसंगम्य राजा वचनमब्रवीत् ॥', 'dṛṣṭvā tu pāṇḍavānīkaṃ vyūḍhaṃ duryodhanas tadā |
ācāryam upasaṃgamya rājā vacanam abravīt ||', null, null),
  ('gita', 1, 3, null, null, 'पश्यैतां पाण्डुपुत्राणामाचार्य महतीं चमूम् ।
व्यूढां द्रुपदपुत्रेण तव शिष्येण धीमता ॥', 'paśyaitāṃ pāṇḍuputrāṇām ācārya mahatīṃ camūm |
vyūḍhāṃ drupadaputreṇa tava śiṣyeṇa dhīmatā ||', null, null),
  ('gita', 1, 4, null, null, 'अत्र शूरा महेष्वासा भीमार्जुनसमा युधि ।
युयुधानो विराटश्च द्रुपदश्च महारथः ॥', 'atra śūrā maheṣvāsā bhīmārjunasamā yudhi |
yuyudhāno virāṭaś ca drupadaś ca mahārathaḥ ||', null, null),
  ('gita', 1, 5, null, null, 'धृष्टकेतुश्चेकितानः काशिराजश्च वीर्यवान् ।
पुरुजित्कुन्तिभोजश्च शैब्यश्च नरपुंगवः ॥', 'dhṛṣṭaketuś cekitānaḥ kāśirājaś ca vīryavān |
purujit kuntibhojaś ca śaibyaś ca narapuṃgavaḥ ||', null, null),
  ('gita', 1, 6, null, null, 'युधामन्युश्च विक्रान्त उत्तमौजाश्च वीर्यवान् ।
सौभद्रो द्रौपदेयाश्च सर्व एव महारथाः ॥', 'yudhāmanyuś ca vikrānta uttamaujāś ca vīryavān |
saubhadro draupadeyāś ca sarva eva mahārathāḥ ||', null, null),
  ('gita', 1, 7, null, null, 'अस्माकं तु विशिष्टा ये तान्निबोध द्विजोत्तम ।
नायका मम सैन्यस्य संज्ञार्थं तान्ब्रवीमि ते ॥', 'asmākaṃ tu viśiṣṭā ye tān nibodha dvijottama |
nāyakā mama sainyasya saṃjñārthaṃ tān bravīmi te ||', null, null),
  ('gita', 1, 8, null, null, 'भवान्भीष्मश्च कर्णश्च कृपश्च समितिंजयः ।
अश्वत्थामा विकर्णश्च सौमदत्तिर्जयद्रथः ॥', 'bhavān bhīṣmaś ca karṇaś ca kṛpaś ca samitiṃjayaḥ |
aśvatthāmā vikarṇaś ca saumadattir jayadrathaḥ ||', null, null),
  ('gita', 1, 9, null, null, 'अन्ये च बहवः शूरा मदर्थे त्यक्तजीविताः ।
नानाशस्त्रप्रहरणाः सर्वे युद्धविशारदाः ॥', 'anye ca bahavaḥ śūrā madarthe tyaktajīvitāḥ |
nānāśastrapraharaṇāḥ sarve yuddhaviśāradāḥ ||', null, null),
  ('gita', 1, 10, null, null, 'अपर्याप्तं तदस्माकं बलं भीष्माभिरक्षितम् ।
पर्याप्तं त्विदमेतेषां बलं भीमाभिरक्षितम् ॥', 'aparyāptaṃ tad asmākaṃ balaṃ bhīṣmābhirakṣitam |
paryāptaṃ tv idam eteṣāṃ balaṃ bhīmābhirakṣitam ||', null, null),
  ('gita', 1, 11, null, null, 'अयनेषु च सर्वेषु यथाभागमवस्थिताः ।
भीष्ममेवाभिरक्षन्तु भवन्तः सर्व एव हि ॥', 'ayaneṣu ca sarveṣu yathābhāgam avasthitāḥ |
bhīṣmam evābhirakṣantu bhavantaḥ sarva eva hi ||', null, null),
  ('gita', 1, 12, null, null, 'तस्य संजनयन्हर्षं कुरुवृद्धः पितामहः ।
सिंहनादं विनद्योच्चैः शङ्खं दध्मौ प्रतापवान् ॥', 'tasya saṃjanayan harṣaṃ kuruvṛddhaḥ pitāmahaḥ |
siṃhanādaṃ vinadyoccaiḥ śaṅkhaṃ dadhmau pratāpavān ||', null, null),
  ('gita', 1, 13, null, null, 'ततः शङ्खाश्च भेर्यश्च पणवानकगोमुखाः ।
सहसैवाभ्यहन्यन्त स शब्दस्तुमुलोऽभवत् ॥', 'tataḥ śaṅkhāś ca bheryaś ca paṇavānakagomukhāḥ |
sahasaivābhyahanyanta sa śabdas tumulo ''bhavat ||', null, null),
  ('gita', 1, 14, null, null, 'ततः श्वेतैर्हयैर्युक्ते महति स्यन्दने स्थितौ ।
माधवः पाण्डवश्चैव दिव्यौ शङ्खौ प्रदध्मतुः ॥', 'tataḥ śvetair hayair yukte mahati syandane sthitau |
mādhavaḥ pāṇḍavaś caiva divyau śaṅkhau pradadhmatuḥ ||', null, null),
  ('gita', 1, 15, null, null, 'पाञ्चजन्यं हृषीकेशो देवदत्तं धनंजयः ।
पौण्ड्रं दध्मौ महाशङ्खं भीमकर्मा वृकोदरः ॥', 'pāñcajanyaṃ hṛṣīkeśo devadattaṃ dhanaṃjayaḥ |
pauṇḍraṃ dadhmau mahāśaṅkhaṃ bhīmakarmā vṛkodaraḥ ||', null, null),
  ('gita', 1, 16, null, null, 'अनन्तविजयं राजा कुन्तीपुत्रो युधिष्ठिरः ।
नकुलः सहदेवश्च सुघोषमणिपुष्पकौ ॥', 'anantavijayaṃ rājā kuntīputro yudhiṣṭhiraḥ |
nakulaḥ sahadevaś ca sughoṣamaṇipuṣpakau ||', null, null),
  ('gita', 1, 17, null, null, 'काश्यश्च परमेष्वासः शिखण्डी च महारथः ।
धृष्टद्युम्नो विराटश्च सात्यकिश्चापराजितः ॥', 'kāśyaś ca parameṣvāsaḥ śikhaṇḍī ca mahārathaḥ |
dhṛṣṭadyumno virāṭaś ca sātyakiś cāparājitaḥ ||', null, null),
  ('gita', 1, 18, null, null, 'द्रुपदो द्रौपदेयाश्च सर्वशः पृथिवीपते ।
सौभद्रश्च महाबाहुः शङ्खान्दध्मुः पृथक्पृथक् ॥', 'drupado draupadeyāś ca sarvaśaḥ pṛthivīpate |
saubhadraś ca mahābāhuḥ śaṅkhān dadhmuḥ pṛthak pṛthak ||', null, null),
  ('gita', 1, 19, null, null, 'स घोषो धार्तराष्ट्राणां हृदयानि व्यदारयत् ।
नभश्च पृथिवीं चैव तुमुलो व्यनुनादयन् ॥', 'sa ghoṣo dhārtarāṣṭrāṇāṃ hṛdayāni vyadārayat |
nabhaś ca pṛthivīṃ caiva tumulo vyanunādayan ||', null, null),
  ('gita', 1, 20, null, null, 'अथ व्यवस्थितान्दृष्ट्वा धार्तराष्ट्रान्कपिध्वजः ।
प्रवृत्ते शस्त्रसंपाते धनुरुद्यम्य पाण्डवः ॥', 'atha vyavasthitān dṛṣṭvā dhārtarāṣṭrān kapidhvajaḥ |
pravṛtte śastrasaṃpāte dhanur udyamya pāṇḍavaḥ ||', null, null),
  ('gita', 1, 21, null, null, 'हृषीकेशं तदा वाक्यमिदमाह महीपते ।
सेनयोरुभयोर्मध्ये रथं स्थापय मेऽच्युत ॥', 'hṛṣīkeśaṃ tadā vākyam idam āha mahīpate |
senayor ubhayor madhye rathaṃ sthāpaya me ''cyuta ||', null, null),
  ('gita', 1, 22, null, null, 'यावदेतान्निरीक्षेऽहं योद्धुकामानवस्थितान् ।
कैर्मया सह योद्धव्यमस्मिन्रणसमुद्यमे ॥', 'yāvad etān nirīkṣe ''haṃ yoddhukāmān avasthitān |
kair mayā saha yoddhavyam asmin raṇasamudyame ||', null, null),
  ('gita', 1, 23, null, null, 'योत्स्यमानानवेक्षेऽहं य एतेऽत्र समागताः ।
धार्तराष्ट्रस्य दुर्बुद्धेर्युद्धे प्रियचिकीर्षवः ॥', 'yotsyamānān avekṣe ''haṃ ya ete ''tra samāgatāḥ |
dhārtarāṣṭrasya durbuddher yuddhe priyacikīrṣavaḥ ||', null, null),
  ('gita', 1, 24, null, null, 'एवमुक्तो हृषीकेशो गुडाकेशेन भारत ।
सेनयोरुभयोर्मध्ये स्थापयित्वा रथोत्तमम् ॥', 'evam ukto hṛṣīkeśo guḍākeśena bhārata |
senayor ubhayor madhye sthāpayitvā rathottamam ||', null, null),
  ('gita', 1, 25, null, null, 'भीष्मद्रोणप्रमुखतः सर्वेषां च महीक्षिताम् ।
उवाच पार्थ पश्यैतान्समवेतान्कुरूनिति ॥', 'bhīṣmadroṇapramukhataḥ sarveṣāṃ ca mahīkṣitām |
uvāca pārtha paśyaitān samavetān kurūn iti ||', null, null),
  ('gita', 1, 26, null, null, 'तत्रापश्यत्स्थितान्पार्थः पितॄनथ पितामहान् ।
आचार्यान्मातुलान्भ्रातॄन्पुत्रान्पौत्रान्सखींस्तथा ॥', 'tatrāpaśyat sthitān pārthaḥ pitṝn atha pitāmahān |
ācāryān mātulān bhrātṝn putrān pautrān sakhīṃs tathā ||', null, null),
  ('gita', 1, 27, null, null, 'श्वशुरान्सुहृदश्चैव सेनयोरुभयोरपि ।
तान्समीक्ष्य स कौन्तेयः सर्वान्बन्धूनवस्थितान् ॥', 'śvaśurān suhṛdaś caiva senayor ubhayor api |
tān samīkṣya sa kaunteyaḥ sarvān bandhūn avasthitān ||', null, null),
  ('gita', 1, 28, null, null, 'कृपया परयाविष्टो विषीदन्निदमब्रवीत् ।
दृष्ट्वेमं स्वजनं कृष्ण युयुत्सुं समुपस्थितम् ॥', 'kṛpayā parayāviṣṭo viṣīdann idam abravīt |
dṛṣṭvemaṃ svajanaṃ kṛṣṇa yuyutsuṃ samupasthitam ||', null, null),
  ('gita', 1, 29, null, null, 'सीदन्ति मम गात्राणि मुखं च परिशुष्यति ।
वेपथुश्च शरीरे मे रोमहर्षश्च जायते ॥', 'sīdanti mama gātrāṇi mukhaṃ ca pariśuṣyati |
vepathuś ca śarīre me romaharṣaś ca jāyate ||', null, null),
  ('gita', 1, 30, null, null, 'गाण्डीवं स्रंसते हस्तात्त्वक्चैव परिदह्यते ।
न च शक्नोम्यवस्थातुं भ्रमतीव च मे मनः ॥', 'gāṇḍīvaṃ sraṃsate hastāt tvak caiva paridahyate |
na ca śaknomy avasthātuṃ bhramatīva ca me manaḥ ||', null, null),
  ('gita', 1, 31, null, null, 'निमित्तानि च पश्यामि विपरीतानि केशव ।
न च श्रेयोऽनुपश्यामि हत्वा स्वजनमाहवे ॥', 'nimittāni ca paśyāmi viparītāni keśava |
na ca śreyo ''nupaśyāmi hatvā svajanam āhave ||', null, null),
  ('gita', 1, 32, null, null, 'न काङ्क्षे विजयं कृष्ण न च राज्यं सुखानि च ।
किं नो राज्येन गोविन्द किं भोगैर्जीवितेन वा ॥', 'na kāṅkṣe vijayaṃ kṛṣṇa na ca rājyaṃ sukhāni ca |
kiṃ no rājyena govinda kiṃ bhogair jīvitena vā ||', null, null),
  ('gita', 1, 33, null, null, 'येषामर्थे काङ्क्षितं नो राज्यं भोगाः सुखानि च ।
त इमेऽवस्थिता युद्धे प्राणांस्त्यक्त्वा धनानि च ॥', 'yeṣām arthe kāṅkṣitaṃ no rājyaṃ bhogāḥ sukhāni ca |
ta ime ''vasthitā yuddhe prāṇāṃs tyaktvā dhanāni ca ||', null, null),
  ('gita', 1, 34, null, null, 'आचार्याः पितरः पुत्रास्तथैव च पितामहाः ।
मातुलाः श्वशुराः पौत्राः श्यालाः संबन्धिनस्तथा ॥', 'ācāryāḥ pitaraḥ putrās tathaiva ca pitāmahāḥ |
mātulāḥ śvaśurāḥ pautrāḥ śyālāḥ saṃbandhinas tathā ||', null, null),
  ('gita', 1, 35, null, null, 'एतान्न हन्तुमिच्छामि घ्नतोऽपि मधुसूदन ।
अपि त्रैलोक्यराज्यस्य हेतोः किं नु महीकृते ॥', 'etān na hantum icchāmi ghnato ''pi madhusūdana |
api trailokyarājyasya hetoḥ kiṃ nu mahīkṛte ||', null, null),
  ('gita', 1, 36, null, null, 'निहत्य धार्तराष्ट्रान्नः का प्रीतिः स्याज्जनार्दन ।
पापमेवाश्रयेदस्मान्हत्वैतानाततायिनः ॥', 'nihatya dhārtarāṣṭrān naḥ kā prītiḥ syāj janārdana |
pāpam evāśrayed asmān hatvaitān ātatāyinaḥ ||', null, null),
  ('gita', 1, 37, null, null, 'तस्मान्नार्हा वयं हन्तुं धार्तराष्ट्रान्स्वबान्धवान् ।
स्वजनं हि कथं हत्वा सुखिनः स्याम माधव ॥', 'tasmān nārhā vayaṃ hantuṃ dhārtarāṣṭrān svabāndhavān |
svajanaṃ hi kathaṃ hatvā sukhinaḥ syāma mādhava ||', null, null),
  ('gita', 1, 38, null, null, 'यद्यप्येते न पश्यन्ति लोभोपहतचेतसः ।
कुलक्षयकृतं दोषं मित्रद्रोहे च पातकम् ॥', 'yady apy ete na paśyanti lobhopahatacetasaḥ |
kulakṣayakṛtaṃ doṣaṃ mitradrohe ca pātakam ||', null, null),
  ('gita', 1, 39, null, null, 'कथं न ज्ञेयमस्माभिः पापादस्मान्निवर्तितुम् ।
कुलक्षयकृतं दोषं प्रपश्यद्भिर्जनार्दन ॥', 'kathaṃ na jñeyam asmābhiḥ pāpād asmān nivartitum |
kulakṣayakṛtaṃ doṣaṃ prapaśyadbhir janārdana ||', null, null),
  ('gita', 1, 40, null, null, 'कुलक्षये प्रणश्यन्ति कुलधर्माः सनातनाः ।
धर्मे नष्टे कुलं कृत्स्नमधर्मोऽभिभवत्युत ॥', 'kulakṣaye praṇaśyanti kuladharmāḥ sanātanāḥ |
dharme naṣṭe kulaṃ kṛtsnam adharmo ''bhibhavaty uta ||', null, null),
  ('gita', 1, 41, null, null, 'अधर्माभिभवात्कृष्ण प्रदुष्यन्ति कुलस्त्रियः ।
स्त्रीषु दुष्टासु वार्ष्णेय जायते वर्णसंकरः ॥', 'adharmābhibhavāt kṛṣṇa praduṣyanti kulastriyaḥ |
strīṣu duṣṭāsu vārṣṇeya jāyate varṇasaṃkaraḥ ||', null, null),
  ('gita', 1, 42, null, null, 'संकरो नरकायैव कुलघ्नानां कुलस्य च ।
पतन्ति पितरो ह्येषां लुप्तपिण्डोदकक्रियाः ॥', 'saṃkaro narakāyaiva kulaghnānāṃ kulasya ca |
patanti pitaro hy eṣāṃ luptapiṇḍodakakriyāḥ ||', null, null),
  ('gita', 1, 43, null, null, 'दोषैरेतैः कुलघ्नानां वर्णसंकरकारकैः ।
उत्साद्यन्ते जातिधर्माः कुलधर्माश्च शाश्वताः ॥', 'doṣair etaiḥ kulaghnānāṃ varṇasaṃkarakārakaiḥ |
utsādyante jātidharmāḥ kuladharmāś ca śāśvatāḥ ||', null, null),
  ('gita', 1, 44, null, null, 'उत्सन्नकुलधर्माणां मनुष्याणां जनार्दन ।
नरके नियतं वासो भवतीत्यनुशुश्रुम ॥', 'utsannakuladharmāṇāṃ manuṣyāṇāṃ janārdana |
narake niyataṃ vāso bhavatīty anuśuśruma ||', null, null),
  ('gita', 1, 45, null, null, 'अहो बत महत्पापं कर्तुं व्यवसिता वयम् ।
यद्राज्यसुखलोभेन हन्तुं स्वजनमुद्यताः ॥', 'aho bata mahat pāpaṃ kartuṃ vyavasitā vayam |
yad rājyasukhalobhena hantuṃ svajanam udyatāḥ ||', null, null),
  ('gita', 1, 46, null, null, 'यदि मामप्रतीकारमशस्त्रं शस्त्रपाणयः ।
धार्तराष्ट्रा रणे हन्युस्तन्मे क्षेमतरं भवेत् ॥', 'yadi mām apratīkāram aśastraṃ śastrapāṇayaḥ |
dhārtarāṣṭrā raṇe hanyus tan me kṣemataraṃ bhavet ||', null, null),
  ('gita', 1, 47, null, null, 'एवमुक्त्वार्जुनः संख्ये रथोपस्थ उपाविशत् ।
विसृज्य सशरं चापं शोकसंविग्नमानसः ॥', 'evam uktvārjunaḥ saṃkhye rathopastha upāviśat |
visṛjya saśaraṃ cāpaṃ śokasaṃvignamānasaḥ ||', null, null),
  ('gita', 2, 1, 'संजय उवाच', 'saṃjaya uvāca', 'तं तथा कृपयाविष्टमश्रुपूर्णाकुलेक्षणम् ।
विषीदन्तमिदं वाक्यमुवाच मधुसूदनः ॥', 'taṃ tathā kṛpayāviṣṭam aśrupūrṇākulekṣaṇam |
viṣīdantam idaṃ vākyam uvāca madhusūdanaḥ ||', null, null),
  ('gita', 2, 2, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'कुतस्त्वा कश्मलमिदं विषमे समुपस्थितम् ।
अनार्यजुष्टमस्वर्ग्यमकीर्तिकरमर्जुन ॥', 'kutas tvā kaśmalam idaṃ viṣame samupasthitam |
anāryajuṣṭam asvargyam akīrtikaram arjuna ||', null, null),
  ('gita', 2, 3, null, null, 'क्लैब्यं मा स्म गमः पार्थ नैतत्त्वय्युपपद्यते ।
क्षुद्रं हृदयदौर्बल्यं त्यक्त्वोत्तिष्ठ परंतप ॥', 'klaibyaṃ mā sma gamaḥ pārtha naitat tvayy upapadyate |
kṣudraṃ hṛdayadaurbalyaṃ tyaktvottiṣṭha paraṃtapa ||', null, null),
  ('gita', 2, 4, 'अर्जुन उवाच', 'arjuna uvāca', 'कथं भीष्ममहं संख्ये द्रोणं च मधुसूदन ।
इषुभिः प्रतियोत्स्यामि पूजार्हावरिसूदन ॥', 'kathaṃ bhīṣmam ahaṃ saṃkhye droṇaṃ ca madhusūdana |
iṣubhiḥ pratiyotsyāmi pūjārhāv arisūdana ||', null, null),
  ('gita', 2, 5, null, null, 'गुरूनहत्वा हि महानुभावाञ्श्रेयो भोक्तुं भैक्ष्यमपीह लोके ।
हत्वार्थकामांस्तु गुरूनिहैव भुञ्जीय भोगान्रुधिरप्रदिग्धान् ॥', 'gurūn ahatvā hi mahānubhāvāñ śreyo bhoktuṃ bhaikṣyam apīha loke |
hatvārthakāmāṃs tu gurūn ihaiva bhuñjīya bhogān rudhirapradigdhān ||', null, null),
  ('gita', 2, 6, null, null, 'न चैतद्विद्मः कतरन्नो गरीयो यद्वा जयेम यदि वा नो जयेयुः ।
यानेव हत्वा न जिजीविषामस्तेऽवस्थिताः प्रमुखे धार्तराष्ट्राः ॥', 'na caitad vidmaḥ kataran no garīyo yad vā jayema yadi vā no jayeyuḥ |
yān eva hatvā na jijīviṣāmas te ''vasthitāḥ pramukhe dhārtarāṣṭrāḥ ||', null, null),
  ('gita', 2, 7, null, null, 'कार्पण्यदोषोपहतस्वभावः पृच्छामि त्वां धर्मसंमूढचेताः ।
यच्छ्रेयः स्यान्निश्चितं ब्रूहि तन्मे शिष्यस्तेऽहं शाधि मां त्वां प्रपन्नम् ॥', 'kārpaṇyadoṣopahatasvabhāvaḥ pṛcchāmi tvāṃ dharmasaṃmūḍhacetāḥ |
yac chreyaḥ syān niścitaṃ brūhi tan me śiṣyas te ''haṃ śādhi māṃ tvāṃ prapannam ||', null, null),
  ('gita', 2, 8, null, null, 'न हि प्रपश्यामि ममापनुद्याद्यच्छोकमुच्छोषणमिन्द्रियाणाम् ।
अवाप्य भूमावसपत्नमृद्धं राज्यं सुराणामपि चाधिपत्यम् ॥', 'na hi prapaśyāmi mamāpanudyād yac chokam ucchoṣaṇam indriyāṇām |
avāpya bhūmāv asapatnam ṛddhaṃ rājyaṃ surāṇām api cādhipatyam ||', null, null),
  ('gita', 2, 9, 'संजय उवाच', 'saṃjaya uvāca', 'एवमुक्त्वा हृषीकेशं गुडाकेशः परंतपः ।
न योत्स्य इति गोविन्दमुक्त्वा तूष्णीं बभूव ह ॥', 'evam uktvā hṛṣīkeśaṃ guḍākeśaḥ paraṃtapaḥ |
na yotsya iti govindam uktvā tūṣṇīṃ babhūva ha ||', null, null),
  ('gita', 2, 10, null, null, 'तमुवाच हृषीकेशः प्रहसन्निव भारत ।
सेनयोरुभयोर्मध्ये विषीदन्तमिदं वचः ॥', 'tam uvāca hṛṣīkeśaḥ prahasann iva bhārata |
senayor ubhayor madhye viṣīdantam idaṃ vacaḥ ||', null, null),
  ('gita', 2, 11, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'अशोच्यानन्वशोचस्त्वं प्रज्ञावादांश्च भाषसे ।
गतासूनगतासूंश्च नानुशोचन्ति पण्डिताः ॥', 'aśocyān anvaśocas tvaṃ prajñāvādāṃś ca bhāṣase |
gatāsūn agatāsūṃś ca nānuśocanti paṇḍitāḥ ||', null, null),
  ('gita', 2, 12, null, null, 'न त्वेवाहं जातु नासं न त्वं नेमे जनाधिपाः ।
न चैव न भविष्यामः सर्वे वयमतः परम् ॥', 'na tv evāhaṃ jātu nāsaṃ na tvaṃ neme janādhipāḥ |
na caiva na bhaviṣyāmaḥ sarve vayam ataḥ param ||', null, null),
  ('gita', 2, 13, null, null, 'देहिनोऽस्मिन्यथा देहे कौमारं यौवनं जरा ।
तथा देहान्तरप्राप्तिर्धीरस्तत्र न मुह्यति ॥', 'dehino ''smin yathā dehe kaumāraṃ yauvanaṃ jarā |
tathā dehāntaraprāptir dhīras tatra na muhyati ||', null, null),
  ('gita', 2, 14, null, null, 'मात्रास्पर्शास्तु कौन्तेय शीतोष्णसुखदुःखदाः ।
आगमापायिनोऽनित्यास्तांस्तितिक्षस्व भारत ॥', 'mātrāsparśās tu kaunteya śītoṣṇasukhaduḥkhadāḥ |
āgamāpāyino ''nityās tāṃs titikṣasva bhārata ||', null, null),
  ('gita', 2, 15, null, null, 'यं हि न व्यथयन्त्येते पुरुषं पुरुषर्षभ ।
समदुःखसुखं धीरं सोऽमृतत्वाय कल्पते ॥', 'yaṃ hi na vyathayanty ete puruṣaṃ puruṣarṣabha |
samaduḥkhasukhaṃ dhīraṃ so ''mṛtatvāya kalpate ||', null, null),
  ('gita', 2, 16, null, null, 'नासतो विद्यते भावो नाभावो विद्यते सतः ।
उभयोरपि दृष्टोऽन्तस्त्वनयोस्तत्त्वदर्शिभिः ॥', 'nāsato vidyate bhāvo nābhāvo vidyate sataḥ |
ubhayor api dṛṣṭo ''ntas tv anayos tattvadarśibhiḥ ||', null, null),
  ('gita', 2, 17, null, null, 'अविनाशि तु तद्विद्धि येन सर्वमिदं ततम् ।
विनाशमव्ययस्यास्य न कश्चित्कर्तुमर्हति ॥', 'avināśi tu tad viddhi yena sarvam idaṃ tatam |
vināśam avyayasyāsya na kaś cit kartum arhati ||', null, null),
  ('gita', 2, 18, null, null, 'अन्तवन्त इमे देहा नित्यस्योक्ताः शरीरिणः ।
अनाशिनोऽप्रमेयस्य तस्माद्युध्यस्व भारत ॥', 'antavanta ime dehā nityasyoktāḥ śarīriṇaḥ |
anāśino ''prameyasya tasmād yudhyasva bhārata ||', null, null),
  ('gita', 2, 19, null, null, 'य एनं वेत्ति हन्तारं यश्चैनं मन्यते हतम् ।
उभौ तौ न विजानीतो नायं हन्ति न हन्यते ॥', 'ya enaṃ vetti hantāraṃ yaś cainaṃ manyate hatam |
ubhau tau na vijānīto nāyaṃ hanti na hanyate ||', null, null),
  ('gita', 2, 20, null, null, 'न जायते म्रियते वा कदा चिन्नायं भूत्वा भविता वा न भूयः ।
अजो नित्यः शाश्वतोऽयं पुराणो न हन्यते हन्यमाने शरीरे ॥', 'na jāyate mriyate vā kadā cin nāyaṃ bhūtvā bhavitā vā na bhūyaḥ |
ajo nityaḥ śāśvato ''yaṃ purāṇo na hanyate hanyamāne śarīre ||', null, null),
  ('gita', 2, 21, null, null, 'वेदाविनाशिनं नित्यं य एनमजमव्ययम् ।
कथं स पुरुषः पार्थ कं घातयति हन्ति कम् ॥', 'vedāvināśinaṃ nityaṃ ya enam ajam avyayam |
kathaṃ sa puruṣaḥ pārtha kaṃ ghātayati hanti kam ||', null, null),
  ('gita', 2, 22, null, null, 'वासांसि जीर्णानि यथा विहाय नवानि गृह्णाति नरोऽपराणि ।
तथा शरीराणि विहाय जीर्णानि अन्यानि संयाति नवानि देही ॥', 'vāsāṃsi jīrṇāni yathā vihāya navāni gṛhṇāti naro ''parāṇi |
tathā śarīrāṇi vihāya jīrṇāni anyāni saṃyāti navāni dehī ||', null, null),
  ('gita', 2, 23, null, null, 'नैनं छिन्दन्ति शस्त्राणि नैनं दहति पावकः ।
न चैनं क्लेदयन्त्यापो न शोषयति मारुतः ॥', 'nainaṃ chindanti śastrāṇi nainaṃ dahati pāvakaḥ |
na cainaṃ kledayanty āpo na śoṣayati mārutaḥ ||', null, null),
  ('gita', 2, 24, null, null, 'अच्छेद्योऽयमदाह्योऽयमक्लेद्योऽशोष्य एव च ।
नित्यः सर्वगतः स्थाणुरचलोऽयं सनातनः ॥', 'acchedyo ''yam adāhyo ''yam akledyo ''śoṣya eva ca |
nityaḥ sarvagataḥ sthāṇur acalo ''yaṃ sanātanaḥ ||', null, null),
  ('gita', 2, 25, null, null, 'अव्यक्तोऽयमचिन्त्योऽयमविकार्योऽयमुच्यते ।
तस्मादेवं विदित्वैनं नानुशोचितुमर्हसि ॥', 'avyakto ''yam acintyo ''yam avikāryo ''yam ucyate |
tasmād evaṃ viditvainaṃ nānuśocitum arhasi ||', null, null),
  ('gita', 2, 26, null, null, 'अथ चैनं नित्यजातं नित्यं वा मन्यसे मृतम् ।
तथापि त्वं महाबाहो नैवं शोचितुमर्हसि ॥', 'atha cainaṃ nityajātaṃ nityaṃ vā manyase mṛtam |
tathāpi tvaṃ mahābāho naivaṃ śocitum arhasi ||', null, null),
  ('gita', 2, 27, null, null, 'जातस्य हि ध्रुवो मृत्युर्ध्रुवं जन्म मृतस्य च ।
तस्मादपरिहार्येऽर्थे न त्वं शोचितुमर्हसि ॥', 'jātasya hi dhruvo mṛtyur dhruvaṃ janma mṛtasya ca |
tasmād aparihārye ''rthe na tvaṃ śocitum arhasi ||', null, null),
  ('gita', 2, 28, null, null, 'अव्यक्तादीनि भूतानि व्यक्तमध्यानि भारत ।
अव्यक्तनिधनान्येव तत्र का परिदेवना ॥', 'avyaktādīni bhūtāni vyaktamadhyāni bhārata |
avyaktanidhanāny eva tatra kā paridevanā ||', null, null),
  ('gita', 2, 29, null, null, 'आश्चर्यवत्पश्यति कश्चिदेनमाश्चर्यवद्वदति तथैव चान्यः ।
आश्चर्यवच्चैनमन्यः शृणोति श्रुत्वाप्येनं वेद न चैव कश्चित् ॥', 'āścaryavat paśyati kaś cid enam āścaryavad vadati tathaiva cānyaḥ |
āścaryavac cainam anyaḥ śṛṇoti śrutvāpy enaṃ veda na caiva kaś cit ||', null, null),
  ('gita', 2, 30, null, null, 'देही नित्यमवध्योऽयं देहे सर्वस्य भारत ।
तस्मात्सर्वाणि भूतानि न त्वं शोचितुमर्हसि ॥', 'dehī nityam avadhyo ''yaṃ dehe sarvasya bhārata |
tasmāt sarvāṇi bhūtāni na tvaṃ śocitum arhasi ||', null, null),
  ('gita', 2, 31, null, null, 'स्वधर्ममपि चावेक्ष्य न विकम्पितुमर्हसि ।
धर्म्याद्धि युद्धाच्छ्रेयोऽन्यत्क्षत्रियस्य न विद्यते ॥', 'svadharmam api cāvekṣya na vikampitum arhasi |
dharmyād dhi yuddhāc chreyo ''nyat kṣatriyasya na vidyate ||', null, null),
  ('gita', 2, 32, null, null, 'यदृच्छया चोपपन्नं स्वर्गद्वारमपावृतम् ।
सुखिनः क्षत्रियाः पार्थ लभन्ते युद्धमीदृशम् ॥', 'yadṛcchayā copapannaṃ svargadvāram apāvṛtam |
sukhinaḥ kṣatriyāḥ pārtha labhante yuddham īdṛśam ||', null, null),
  ('gita', 2, 33, null, null, 'अथ चेत्त्वमिमं धर्म्यं संग्रामं न करिष्यसि ।
ततः स्वधर्मं कीर्तिं च हित्वा पापमवाप्स्यसि ॥', 'atha cet tvam imaṃ dharmyaṃ saṃgrāmaṃ na kariṣyasi |
tataḥ svadharmaṃ kīrtiṃ ca hitvā pāpam avāpsyasi ||', null, null),
  ('gita', 2, 34, null, null, 'अकीर्तिं चापि भूतानि कथयिष्यन्ति तेऽव्ययाम् ।
संभावितस्य चाकीर्तिर्मरणादतिरिच्यते ॥', 'akīrtiṃ cāpi bhūtāni kathayiṣyanti te ''vyayām |
saṃbhāvitasya cākīrtir maraṇād atiricyate ||', null, null),
  ('gita', 2, 35, null, null, 'भयाद्रणादुपरतं मंस्यन्ते त्वां महारथाः ।
येषां च त्वं बहुमतो भूत्वा यास्यसि लाघवम् ॥', 'bhayād raṇād uparataṃ maṃsyante tvāṃ mahārathāḥ |
yeṣāṃ ca tvaṃ bahumato bhūtvā yāsyasi lāghavam ||', null, null),
  ('gita', 2, 36, null, null, 'अवाच्यवादांश्च बहून्वदिष्यन्ति तवाहिताः ।
निन्दन्तस्तव सामर्थ्यं ततो दुःखतरं नु किम् ॥', 'avācyavādāṃś ca bahūn vadiṣyanti tavāhitāḥ |
nindantas tava sāmarthyaṃ tato duḥkhataraṃ nu kim ||', null, null),
  ('gita', 2, 37, null, null, 'हतो वा प्राप्स्यसि स्वर्गं जित्वा वा भोक्ष्यसे महीम् ।
तस्मादुत्तिष्ठ कौन्तेय युद्धाय कृतनिश्चयः ॥', 'hato vā prāpsyasi svargaṃ jitvā vā bhokṣyase mahīm |
tasmād uttiṣṭha kaunteya yuddhāya kṛtaniścayaḥ ||', null, null),
  ('gita', 2, 38, null, null, 'सुखदुःखे समे कृत्वा लाभालाभौ जयाजयौ ।
ततो युद्धाय युज्यस्व नैवं पापमवाप्स्यसि ॥', 'sukhaduḥkhe same kṛtvā lābhālābhau jayājayau |
tato yuddhāya yujyasva naivaṃ pāpam avāpsyasi ||', null, null),
  ('gita', 2, 39, null, null, 'एषा तेऽभिहिता सांख्ये बुद्धिर्योगे त्विमां शृणु ।
बुद्ध्या युक्तो यया पार्थ कर्मबन्धं प्रहास्यसि ॥', 'eṣā te ''bhihitā sāṃkhye buddhir yoge tv imāṃ śṛṇu |
buddhyā yukto yayā pārtha karmabandhaṃ prahāsyasi ||', null, null),
  ('gita', 2, 40, null, null, 'नेहाभिक्रमनाशोऽस्ति प्रत्यवायो न विद्यते ।
स्वल्पमप्यस्य धर्मस्य त्रायते महतो भयात् ॥', 'nehābhikramanāśo ''sti pratyavāyo na vidyate |
svalpam apy asya dharmasya trāyate mahato bhayāt ||', null, null),
  ('gita', 2, 41, null, null, 'व्यवसायात्मिका बुद्धिरेकेह कुरुनन्दन ।
बहुशाखा ह्यनन्ताश्च बुद्धयोऽव्यवसायिनाम् ॥', 'vyavasāyātmikā buddhir ekeha kurunandana |
bahuśākhā hy anantāś ca buddhayo ''vyavasāyinām ||', null, null),
  ('gita', 2, 42, null, null, 'यामिमां पुष्पितां वाचं प्रवदन्त्यविपश्चितः ।
वेदवादरताः पार्थ नान्यदस्तीति वादिनः ॥', 'yām imāṃ puṣpitāṃ vācaṃ pravadanty avipaścitaḥ |
vedavādaratāḥ pārtha nānyad astīti vādinaḥ ||', null, null),
  ('gita', 2, 43, null, null, 'कामात्मानः स्वर्गपरा जन्मकर्मफलप्रदाम् ।
क्रियाविशेषबहुलां भोगैश्वर्यगतिं प्रति ॥', 'kāmātmānaḥ svargaparā janmakarmaphalapradām |
kriyāviśeṣabahulāṃ bhogaiśvaryagatiṃ prati ||', null, null),
  ('gita', 2, 44, null, null, 'भोगैश्वर्यप्रसक्तानां तयापहृतचेतसाम् ।
व्यवसायात्मिका बुद्धिः समाधौ न विधीयते ॥', 'bhogaiśvaryaprasaktānāṃ tayāpahṛtacetasām |
vyavasāyātmikā buddhiḥ samādhau na vidhīyate ||', null, null),
  ('gita', 2, 45, null, null, 'त्रैगुण्यविषया वेदा निस्त्रैगुण्यो भवार्जुन ।
निर्द्वन्द्वो नित्यसत्त्वस्थो निर्योगक्षेम आत्मवान् ॥', 'traiguṇyaviṣayā vedā nistraiguṇyo bhavārjuna |
nirdvandvo nityasattvastho niryogakṣema ātmavān ||', null, null),
  ('gita', 2, 46, null, null, 'यावानर्थ उदपाने सर्वतः संप्लुतोदके ।
तावान्सर्वेषु वेदेषु ब्राह्मणस्य विजानतः ॥', 'yāvān artha udapāne sarvataḥ saṃplutodake |
tāvān sarveṣu vedeṣu brāhmaṇasya vijānataḥ ||', null, null),
  ('gita', 2, 47, null, null, 'कर्मण्येवाधिकारस्ते मा फलेषु कदा चन ।
मा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि ॥', 'karmaṇy evādhikāras te mā phaleṣu kadā cana |
mā karmaphalahetur bhūr mā te saṅgo ''stv akarmaṇi ||', null, null),
  ('gita', 2, 48, null, null, 'योगस्थः कुरु कर्माणि सङ्गं त्यक्त्वा धनंजय ।
सिद्ध्यसिद्ध्योः समो भूत्वा समत्वं योग उच्यते ॥', 'yogasthaḥ kuru karmāṇi saṅgaṃ tyaktvā dhanaṃjaya |
siddhyasiddhyoḥ samo bhūtvā samatvaṃ yoga ucyate ||', null, null),
  ('gita', 2, 49, null, null, 'दूरेण ह्यवरं कर्म बुद्धियोगाद्धनंजय ।
बुद्धौ शरणमन्विच्छ कृपणाः फलहेतवः ॥', 'dūreṇa hy avaraṃ karma buddhiyogād dhanaṃjaya |
buddhau śaraṇam anviccha kṛpaṇāḥ phalahetavaḥ ||', null, null),
  ('gita', 2, 50, null, null, 'बुद्धियुक्तो जहातीह उभे सुकृतदुष्कृते ।
तस्माद्योगाय युज्यस्व योगः कर्मसु कौशलम् ॥', 'buddhiyukto jahātīha ubhe sukṛtaduṣkṛte |
tasmād yogāya yujyasva yogaḥ karmasu kauśalam ||', null, null),
  ('gita', 2, 51, null, null, 'कर्मजं बुद्धियुक्ता हि फलं त्यक्त्वा मनीषिणः ।
जन्मबन्धविनिर्मुक्ताः पदं गच्छन्त्यनामयम् ॥', 'karmajaṃ buddhiyuktā hi phalaṃ tyaktvā manīṣiṇaḥ |
janmabandhavinirmuktāḥ padaṃ gacchanty anāmayam ||', null, null),
  ('gita', 2, 52, null, null, 'यदा ते मोहकलिलं बुद्धिर्व्यतितरिष्यति ।
तदा गन्तासि निर्वेदं श्रोतव्यस्य श्रुतस्य च ॥', 'yadā te mohakalilaṃ buddhir vyatitariṣyati |
tadā gantāsi nirvedaṃ śrotavyasya śrutasya ca ||', null, null),
  ('gita', 2, 53, null, null, 'श्रुतिविप्रतिपन्ना ते यदा स्थास्यति निश्चला ।
समाधावचला बुद्धिस्तदा योगमवाप्स्यसि ॥', 'śrutivipratipannā te yadā sthāsyati niścalā |
samādhāv acalā buddhis tadā yogam avāpsyasi ||', null, null),
  ('gita', 2, 54, 'अर्जुन उवाच', 'arjuna uvāca', 'स्थितप्रज्ञस्य का भाषा समाधिस्थस्य केशव ।
स्थितधीः किं प्रभाषेत किमासीत व्रजेत किम् ॥', 'sthitaprajñasya kā bhāṣā samādhisthasya keśava |
sthitadhīḥ kiṃ prabhāṣeta kim āsīta vrajeta kim ||', null, null),
  ('gita', 2, 55, null, null, 'प्रजहाति यदा कामान्सर्वान्पार्थ मनोगतान् ।
आत्मन्येवात्मना तुष्टः स्थितप्रज्ञस्तदोच्यते ॥', 'prajahāti yadā kāmān sarvān pārtha manogatān |
ātmany evātmanā tuṣṭaḥ sthitaprajñas tadocyate ||', null, null),
  ('gita', 2, 56, null, null, 'दुःखेष्वनुद्विग्नमनाः सुखेषु विगतस्पृहः ।
वीतरागभयक्रोधः स्थितधीर्मुनिरुच्यते ॥', 'duḥkheṣv anudvignamanāḥ sukheṣu vigataspṛhaḥ |
vītarāgabhayakrodhaḥ sthitadhīr munir ucyate ||', null, null),
  ('gita', 2, 57, null, null, 'यः सर्वत्रानभिस्नेहस्तत्तत्प्राप्य शुभाशुभम् ।
नाभिनन्दति न द्वेष्टि तस्य प्रज्ञा प्रतिष्ठिता ॥', 'yaḥ sarvatrānabhisnehas tat tat prāpya śubhāśubham |
nābhinandati na dveṣṭi tasya prajñā pratiṣṭhitā ||', null, null),
  ('gita', 2, 58, null, null, 'यदा संहरते चायं कूर्मोऽङ्गानीव सर्वशः ।
इन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता ॥', 'yadā saṃharate cāyaṃ kūrmo ''ṅgānīva sarvaśaḥ |
indriyāṇīndriyārthebhyas tasya prajñā pratiṣṭhitā ||', null, null),
  ('gita', 2, 59, null, null, 'विषया विनिवर्तन्ते निराहारस्य देहिनः ।
रसवर्जं रसोऽप्यस्य परं दृष्ट्वा निवर्तते ॥', 'viṣayā vinivartante nirāhārasya dehinaḥ |
rasavarjaṃ raso ''py asya paraṃ dṛṣṭvā nivartate ||', null, null),
  ('gita', 2, 60, null, null, 'यततो ह्यपि कौन्तेय पुरुषस्य विपश्चितः ।
इन्द्रियाणि प्रमाथीनि हरन्ति प्रसभं मनः ॥', 'yatato hy api kaunteya puruṣasya vipaścitaḥ |
indriyāṇi pramāthīni haranti prasabhaṃ manaḥ ||', null, null),
  ('gita', 2, 61, null, null, 'तानि सर्वाणि संयम्य युक्त आसीत मत्परः ।
वशे हि यस्येन्द्रियाणि तस्य प्रज्ञा प्रतिष्ठिता ॥', 'tāni sarvāṇi saṃyamya yukta āsīta matparaḥ |
vaśe hi yasyendriyāṇi tasya prajñā pratiṣṭhitā ||', null, null),
  ('gita', 2, 62, null, null, 'ध्यायतो विषयान्पुंसः सङ्गस्तेषूपजायते ।
सङ्गात्संजायते कामः कामात्क्रोधोऽभिजायते ॥', 'dhyāyato viṣayān puṃsaḥ saṅgas teṣūpajāyate |
saṅgāt saṃjāyate kāmaḥ kāmāt krodho ''bhijāyate ||', null, null),
  ('gita', 2, 63, null, null, 'क्रोधाद्भवति संमोहः संमोहात्स्मृतिविभ्रमः ।
स्मृतिभ्रंशाद्बुद्धिनाशो बुद्धिनाशात्प्रणश्यति ॥', 'krodhād bhavati saṃmohaḥ saṃmohāt smṛtivibhramaḥ |
smṛtibhraṃśād buddhināśo buddhināśāt praṇaśyati ||', null, null),
  ('gita', 2, 64, null, null, 'रागद्वेषवियुक्तैस्तु विषयानिन्द्रियैश्चरन् ।
आत्मवश्यैर्विधेयात्मा प्रसादमधिगच्छति ॥', 'rāgadveṣaviyuktais tu viṣayān indriyaiś caran |
ātmavaśyair vidheyātmā prasādam adhigacchati ||', null, null),
  ('gita', 2, 65, null, null, 'प्रसादे सर्वदुःखानां हानिरस्योपजायते ।
प्रसन्नचेतसो ह्याशु बुद्धिः पर्यवतिष्ठते ॥', 'prasāde sarvaduḥkhānāṃ hānir asyopajāyate |
prasannacetaso hy āśu buddhiḥ paryavatiṣṭhate ||', null, null),
  ('gita', 2, 66, null, null, 'नास्ति बुद्धिरयुक्तस्य न चायुक्तस्य भावना ।
न चाभावयतः शान्तिरशान्तस्य कुतः सुखम् ॥', 'nāsti buddhir ayuktasya na cāyuktasya bhāvanā |
na cābhāvayataḥ śāntir aśāntasya kutaḥ sukham ||', null, null),
  ('gita', 2, 67, null, null, 'इन्द्रियाणां हि चरतां यन्मनोऽनुविधीयते ।
तदस्य हरति प्रज्ञां वायुर्नावमिवाम्भसि ॥', 'indriyāṇāṃ hi caratāṃ yan mano ''nuvidhīyate |
tad asya harati prajñāṃ vāyur nāvam ivāmbhasi ||', null, null),
  ('gita', 2, 68, null, null, 'तस्माद्यस्य महाबाहो निगृहीतानि सर्वशः ।
इन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता ॥', 'tasmād yasya mahābāho nigṛhītāni sarvaśaḥ |
indriyāṇīndriyārthebhyas tasya prajñā pratiṣṭhitā ||', null, null),
  ('gita', 2, 69, null, null, 'या निशा सर्वभूतानां तस्यां जागर्ति संयमी ।
यस्यां जाग्रति भूतानि सा निशा पश्यतो मुनेः ॥', 'yā niśā sarvabhūtānāṃ tasyāṃ jāgarti saṃyamī |
yasyāṃ jāgrati bhūtāni sā niśā paśyato muneḥ ||', null, null),
  ('gita', 2, 70, null, null, 'आपूर्यमाणमचलप्रतिष्ठं समुद्रमापः प्रविशन्ति यद्वत् ।
तद्वत्कामा यं प्रविशन्ति सर्वे स शान्तिमाप्नोति न कामकामी ॥', 'āpūryamāṇam acalapratiṣṭhaṃ samudram āpaḥ praviśanti yadvat |
tadvat kāmā yaṃ praviśanti sarve sa śāntim āpnoti na kāmakāmī ||', null, null),
  ('gita', 2, 71, null, null, 'विहाय कामान्यः सर्वान्पुमांश्चरति निःस्पृहः ।
निर्ममो निरहंकारः स शान्तिमधिगच्छति ॥', 'vihāya kāmān yaḥ sarvān pumāṃś carati niḥspṛhaḥ |
nirmamo nirahaṃkāraḥ sa śāntim adhigacchati ||', null, null),
  ('gita', 2, 72, null, null, 'एषा ब्राह्मी स्थितिः पार्थ नैनां प्राप्य विमुह्यति ।
स्थित्वास्यामन्तकालेऽपि ब्रह्मनिर्वाणमृच्छति ॥', 'eṣā brāhmī sthitiḥ pārtha naināṃ prāpya vimuhyati |
sthitvāsyām antakāle ''pi brahmanirvāṇam ṛcchati ||', null, null),
  ('gita', 3, 1, 'अर्जुन उवाच', 'arjuna uvāca', 'ज्यायसी चेत्कर्मणस्ते मता बुद्धिर्जनार्दन ।
तत्किं कर्मणि घोरे मां नियोजयसि केशव ॥', 'jyāyasī cet karmaṇas te matā buddhir janārdana |
tat kiṃ karmaṇi ghore māṃ niyojayasi keśava ||', null, null),
  ('gita', 3, 2, null, null, 'व्यामिश्रेणैव वाक्येन बुद्धिं मोहयसीव मे ।
तदेकं वद निश्चित्य येन श्रेयोऽहमाप्नुयाम् ॥', 'vyāmiśreṇaiva vākyena buddhiṃ mohayasīva me |
tad ekaṃ vada niścitya yena śreyo ''ham āpnuyām ||', null, null),
  ('gita', 3, 3, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'लोकेऽस्मिन्द्विविधा निष्ठा पुरा प्रोक्ता मयानघ ।
ज्ञानयोगेन सांख्यानां कर्मयोगेन योगिनाम् ॥', 'loke ''smin dvividhā niṣṭhā purā proktā mayānagha |
jñānayogena sāṃkhyānāṃ karmayogena yoginām ||', null, null),
  ('gita', 3, 4, null, null, 'न कर्मणामनारम्भान्नैष्कर्म्यं पुरुषोऽश्नुते ।
न च संन्यसनादेव सिद्धिं समधिगच्छति ॥', 'na karmaṇām anārambhān naiṣkarmyaṃ puruṣo ''śnute |
na ca saṃnyasanād eva siddhiṃ samadhigacchati ||', null, null),
  ('gita', 3, 5, null, null, 'न हि कश्चित्क्षणमपि जातु तिष्ठत्यकर्मकृत् ।
कार्यते ह्यवशः कर्म सर्वः प्रकृतिजैर्गुणैः ॥', 'na hi kaś cit kṣaṇam api jātu tiṣṭhaty akarmakṛt |
kāryate hy avaśaḥ karma sarvaḥ prakṛtijair guṇaiḥ ||', null, null),
  ('gita', 3, 6, null, null, 'कर्मेन्द्रियाणि संयम्य य आस्ते मनसा स्मरन् ।
इन्द्रियार्थान्विमूढात्मा मिथ्याचारः स उच्यते ॥', 'karmendriyāṇi saṃyamya ya āste manasā smaran |
indriyārthān vimūḍhātmā mithyācāraḥ sa ucyate ||', null, null),
  ('gita', 3, 7, null, null, 'यस्त्विन्द्रियाणि मनसा नियम्यारभतेऽर्जुन ।
कर्मेन्द्रियैः कर्मयोगमसक्तः स विशिष्यते ॥', 'yas tv indriyāṇi manasā niyamyārabhate ''rjuna |
karmendriyaiḥ karmayogam asaktaḥ sa viśiṣyate ||', null, null),
  ('gita', 3, 8, null, null, 'नियतं कुरु कर्म त्वं कर्म ज्यायो ह्यकर्मणः ।
शरीरयात्रापि च ते न प्रसिध्येदकर्मणः ॥', 'niyataṃ kuru karma tvaṃ karma jyāyo hy akarmaṇaḥ |
śarīrayātrāpi ca te na prasidhyed akarmaṇaḥ ||', null, null),
  ('gita', 3, 9, null, null, 'यज्ञार्थात्कर्मणोऽन्यत्र लोकोऽयं कर्मबन्धनः ।
तदर्थं कर्म कौन्तेय मुक्तसङ्गः समाचर ॥', 'yajñārthāt karmaṇo ''nyatra loko ''yaṃ karmabandhanaḥ |
tadarthaṃ karma kaunteya muktasaṅgaḥ samācara ||', null, null),
  ('gita', 3, 10, null, null, 'सहयज्ञाः प्रजाः सृष्ट्वा पुरोवाच प्रजापतिः ।
अनेन प्रसविष्यध्वमेष वोऽस्त्विष्टकामधुक् ॥', 'sahayajñāḥ prajāḥ sṛṣṭvā purovāca prajāpatiḥ |
anena prasaviṣyadhvam eṣa vo ''stv iṣṭakāmadhuk ||', null, null),
  ('gita', 3, 11, null, null, 'देवान्भावयतानेन ते देवा भावयन्तु वः ।
परस्परं भावयन्तः श्रेयः परमवाप्स्यथ ॥', 'devān bhāvayatānena te devā bhāvayantu vaḥ |
parasparaṃ bhāvayantaḥ śreyaḥ param avāpsyatha ||', null, null),
  ('gita', 3, 12, null, null, 'इष्टान्भोगान्हि वो देवा दास्यन्ते यज्ञभाविताः ।
तैर्दत्तानप्रदायैभ्यो यो भुङ्क्ते स्तेन एव सः ॥', 'iṣṭān bhogān hi vo devā dāsyante yajñabhāvitāḥ |
tair dattān apradāyaibhyo yo bhuṅkte stena eva saḥ ||', null, null),
  ('gita', 3, 13, null, null, 'यज्ञशिष्टाशिनः सन्तो मुच्यन्ते सर्वकिल्बिषैः ।
भुञ्जते ते त्वघं पापा ये पचन्त्यात्मकारणात् ॥', 'yajñaśiṣṭāśinaḥ santo mucyante sarvakilbiṣaiḥ |
bhuñjate te tv aghaṃ pāpā ye pacanty ātmakāraṇāt ||', null, null),
  ('gita', 3, 14, null, null, 'अन्नाद्भवन्ति भूतानि पर्जन्यादन्नसंभवः ।
यज्ञाद्भवति पर्जन्यो यज्ञः कर्मसमुद्भवः ॥', 'annād bhavanti bhūtāni parjanyād annasaṃbhavaḥ |
yajñād bhavati parjanyo yajñaḥ karmasamudbhavaḥ ||', null, null),
  ('gita', 3, 15, null, null, 'कर्म ब्रह्मोद्भवं विद्धि ब्रह्माक्षरसमुद्भवम् ।
तस्मात्सर्वगतं ब्रह्म नित्यं यज्ञे प्रतिष्ठितम् ॥', 'karma brahmodbhavaṃ viddhi brahmākṣarasamudbhavam |
tasmāt sarvagataṃ brahma nityaṃ yajñe pratiṣṭhitam ||', null, null),
  ('gita', 3, 16, null, null, 'एवं प्रवर्तितं चक्रं नानुवर्तयतीह यः ।
अघायुरिन्द्रियारामो मोघं पार्थ स जीवति ॥', 'evaṃ pravartitaṃ cakraṃ nānuvartayatīha yaḥ |
aghāyur indriyārāmo moghaṃ pārtha sa jīvati ||', null, null),
  ('gita', 3, 17, null, null, 'यस्त्वात्मरतिरेव स्यादात्मतृप्तश्च मानवः ।
आत्मन्येव च संतुष्टस्तस्य कार्यं न विद्यते ॥', 'yas tv ātmaratir eva syād ātmatṛptaś ca mānavaḥ |
ātmany eva ca saṃtuṣṭas tasya kāryaṃ na vidyate ||', null, null),
  ('gita', 3, 18, null, null, 'नैव तस्य कृतेनार्थो नाकृतेनेह कश्चन ।
न चास्य सर्वभूतेषु कश्चिदर्थव्यपाश्रयः ॥', 'naiva tasya kṛtenārtho nākṛteneha kaś cana |
na cāsya sarvabhūteṣu kaś cid arthavyapāśrayaḥ ||', null, null),
  ('gita', 3, 19, null, null, 'तस्मादसक्तः सततं कार्यं कर्म समाचर ।
असक्तो ह्याचरन्कर्म परमाप्नोति पूरुषः ॥', 'tasmād asaktaḥ satataṃ kāryaṃ karma samācara |
asakto hy ācaran karma param āpnoti pūruṣaḥ ||', null, null),
  ('gita', 3, 20, null, null, 'कर्मणैव हि संसिद्धिमास्थिता जनकादयः ।
लोकसंग्रहमेवापि संपश्यन्कर्तुमर्हसि ॥', 'karmaṇaiva hi saṃsiddhim āsthitā janakādayaḥ |
lokasaṃgraham evāpi saṃpaśyan kartum arhasi ||', null, null),
  ('gita', 3, 21, null, null, 'यद्यदाचरति श्रेष्ठस्तत्तदेवेतरो जनः ।
स यत्प्रमाणं कुरुते लोकस्तदनुवर्तते ॥', 'yad yad ācarati śreṣṭhas tat tad evetaro janaḥ |
sa yat pramāṇaṃ kurute lokas tad anuvartate ||', null, null),
  ('gita', 3, 22, null, null, 'न मे पार्थास्ति कर्तव्यं त्रिषु लोकेषु किं चन ।
नानवाप्तमवाप्तव्यं वर्त एव च कर्मणि ॥', 'na me pārthāsti kartavyaṃ triṣu lokeṣu kiṃ cana |
nānavāptam avāptavyaṃ varta eva ca karmaṇi ||', null, null),
  ('gita', 3, 23, null, null, 'यदि ह्यहं न वर्तेयं जातु कर्मण्यतन्द्रितः ।
मम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः ॥', 'yadi hy ahaṃ na varteyaṃ jātu karmaṇy atandritaḥ |
mama vartmānuvartante manuṣyāḥ pārtha sarvaśaḥ ||', null, null),
  ('gita', 3, 24, null, null, 'उत्सीदेयुरिमे लोका न कुर्यां कर्म चेदहम् ।
संकरस्य च कर्ता स्यामुपहन्यामिमाः प्रजाः ॥', 'utsīdeyur ime lokā na kuryāṃ karma ced aham |
saṃkarasya ca kartā syām upahanyām imāḥ prajāḥ ||', null, null),
  ('gita', 3, 25, null, null, 'सक्ताः कर्मण्यविद्वांसो यथा कुर्वन्ति भारत ।
कुर्याद्विद्वांस्तथासक्तश्चिकीर्षुर्लोकसंग्रहम् ॥', 'saktāḥ karmaṇy avidvāṃso yathā kurvanti bhārata |
kuryād vidvāṃs tathāsaktaś cikīrṣur lokasaṃgraham ||', null, null),
  ('gita', 3, 26, null, null, 'न बुद्धिभेदं जनयेदज्ञानां कर्मसङ्गिनाम् ।
जोषयेत्सर्वकर्माणि विद्वान्युक्तः समाचरन् ॥', 'na buddhibhedaṃ janayed ajñānāṃ karmasaṅginām |
joṣayet sarvakarmāṇi vidvān yuktaḥ samācaran ||', null, null),
  ('gita', 3, 27, null, null, 'प्रकृतेः क्रियमाणानि गुणैः कर्माणि सर्वशः ।
अहंकारविमूढात्मा कर्ताहमिति मन्यते ॥', 'prakṛteḥ kriyamāṇāni guṇaiḥ karmāṇi sarvaśaḥ |
ahaṃkāravimūḍhātmā kartāham iti manyate ||', null, null),
  ('gita', 3, 28, null, null, 'तत्त्ववित्तु महाबाहो गुणकर्मविभागयोः ।
गुणा गुणेषु वर्तन्त इति मत्वा न सज्जते ॥', 'tattvavit tu mahābāho guṇakarmavibhāgayoḥ |
guṇā guṇeṣu vartanta iti matvā na sajjate ||', null, null),
  ('gita', 3, 29, null, null, 'प्रकृतेर्गुणसंमूढाः सज्जन्ते गुणकर्मसु ।
तानकृत्स्नविदो मन्दान्कृत्स्नविन्न विचालयेत् ॥', 'prakṛter guṇasaṃmūḍhāḥ sajjante guṇakarmasu |
tān akṛtsnavido mandān kṛtsnavin na vicālayet ||', null, null),
  ('gita', 3, 30, null, null, 'मयि सर्वाणि कर्माणि संन्यस्याध्यात्मचेतसा ।
निराशीर्निर्ममो भूत्वा युध्यस्व विगतज्वरः ॥', 'mayi sarvāṇi karmāṇi saṃnyasyādhyātmacetasā |
nirāśīr nirmamo bhūtvā yudhyasva vigatajvaraḥ ||', null, null),
  ('gita', 3, 31, null, null, 'ये मे मतमिदं नित्यमनुतिष्ठन्ति मानवाः ।
श्रद्धावन्तोऽनसूयन्तो मुच्यन्ते तेऽपि कर्मभिः ॥', 'ye me matam idaṃ nityam anutiṣṭhanti mānavāḥ |
śraddhāvanto ''nasūyanto mucyante te ''pi karmabhiḥ ||', null, null),
  ('gita', 3, 32, null, null, 'ये त्वेतदभ्यसूयन्तो नानुतिष्ठन्ति मे मतम् ।
सर्वज्ञानविमूढांस्तान्विद्धि नष्टानचेतसः ॥', 'ye tv etad abhyasūyanto nānutiṣṭhanti me matam |
sarvajñānavimūḍhāṃs tān viddhi naṣṭān acetasaḥ ||', null, null),
  ('gita', 3, 33, null, null, 'सदृशं चेष्टते स्वस्याः प्रकृतेर्ज्ञानवानपि ।
प्रकृतिं यान्ति भूतानि निग्रहः किं करिष्यति ॥', 'sadṛśaṃ ceṣṭate svasyāḥ prakṛter jñānavān api |
prakṛtiṃ yānti bhūtāni nigrahaḥ kiṃ kariṣyati ||', null, null),
  ('gita', 3, 34, null, null, 'इन्द्रियस्येन्द्रियस्यार्थे रागद्वेषौ व्यवस्थितौ ।
तयोर्न वशमागच्छेत्तौ ह्यस्य परिपन्थिनौ ॥', 'indriyasyendriyasyārthe rāgadveṣau vyavasthitau |
tayor na vaśam āgacchet tau hy asya paripanthinau ||', null, null),
  ('gita', 3, 35, null, null, 'श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात् ।
स्वधर्मे निधनं श्रेयः परधर्मो भयावहः ॥', 'śreyān svadharmo viguṇaḥ paradharmāt svanuṣṭhitāt |
svadharme nidhanaṃ śreyaḥ paradharmo bhayāvahaḥ ||', null, null),
  ('gita', 3, 36, 'अर्जुन उवाच', 'arjuna uvāca', 'अथ केन प्रयुक्तोऽयं पापं चरति पूरुषः ।
अनिच्छन्नपि वार्ष्णेय बलादिव नियोजितः ॥', 'atha kena prayukto ''yaṃ pāpaṃ carati pūruṣaḥ |
anicchann api vārṣṇeya balād iva niyojitaḥ ||', null, null),
  ('gita', 3, 37, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'काम एष क्रोध एष रजोगुणसमुद्भवः ।
महाशनो महापाप्मा विद्ध्येनमिह वैरिणम् ॥', 'kāma eṣa krodha eṣa rajoguṇasamudbhavaḥ |
mahāśano mahāpāpmā viddhy enam iha vairiṇam ||', null, null),
  ('gita', 3, 38, null, null, 'धूमेनाव्रियते वह्निर्यथादर्शो मलेन च ।
यथोल्बेनावृतो गर्भस्तथा तेनेदमावृतम् ॥', 'dhūmenāvriyate vahnir yathādarśo malena ca |
yatholbenāvṛto garbhas tathā tenedam āvṛtam ||', null, null),
  ('gita', 3, 39, null, null, 'आवृतं ज्ञानमेतेन ज्ञानिनो नित्यवैरिणा ।
कामरूपेण कौन्तेय दुष्पूरेणानलेन च ॥', 'āvṛtaṃ jñānam etena jñānino nityavairiṇā |
kāmarūpeṇa kaunteya duṣpūreṇānalena ca ||', null, null),
  ('gita', 3, 40, null, null, 'इन्द्रियाणि मनो बुद्धिरस्याधिष्ठानमुच्यते ।
एतैर्विमोहयत्येष ज्ञानमावृत्य देहिनम् ॥', 'indriyāṇi mano buddhir asyādhiṣṭhānam ucyate |
etair vimohayaty eṣa jñānam āvṛtya dehinam ||', null, null),
  ('gita', 3, 41, null, null, 'तस्मात्त्वमिन्द्रियाण्यादौ नियम्य भरतर्षभ ।
पाप्मानं प्रजहि ह्येनं ज्ञानविज्ञाननाशनम् ॥', 'tasmāt tvam indriyāṇy ādau niyamya bharatarṣabha |
pāpmānaṃ prajahi hy enaṃ jñānavijñānanāśanam ||', null, null),
  ('gita', 3, 42, null, null, 'इन्द्रियाणि पराण्याहुरिन्द्रियेभ्यः परं मनः ।
मनसस्तु परा बुद्धिर्यो बुद्धेः परतस्तु सः ॥', 'indriyāṇi parāṇy āhur indriyebhyaḥ paraṃ manaḥ |
manasas tu parā buddhir yo buddheḥ paratas tu saḥ ||', null, null),
  ('gita', 3, 43, null, null, 'एवं बुद्धेः परं बुद्ध्वा संस्तभ्यात्मानमात्मना ।
जहि शत्रुं महाबाहो कामरूपं दुरासदम् ॥', 'evaṃ buddheḥ paraṃ buddhvā saṃstabhyātmānam ātmanā |
jahi śatruṃ mahābāho kāmarūpaṃ durāsadam ||', null, null),
  ('gita', 4, 1, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'इमं विवस्वते योगं प्रोक्तवानहमव्ययम् ।
विवस्वान्मनवे प्राह मनुरिक्ष्वाकवेऽब्रवीत् ॥', 'imaṃ vivasvate yogaṃ proktavān aham avyayam |
vivasvān manave prāha manur ikṣvākave ''bravīt ||', null, null),
  ('gita', 4, 2, null, null, 'एवं परम्पराप्राप्तमिमं राजर्षयो विदुः ।
स कालेनेह महता योगो नष्टः परंतप ॥', 'evaṃ paramparāprāptam imaṃ rājarṣayo viduḥ |
sa kāleneha mahatā yogo naṣṭaḥ paraṃtapa ||', null, null),
  ('gita', 4, 3, null, null, 'स एवायं मया तेऽद्य योगः प्रोक्तः पुरातनः ।
भक्तोऽसि मे सखा चेति रहस्यं ह्येतदुत्तमम् ॥', 'sa evāyaṃ mayā te ''dya yogaḥ proktaḥ purātanaḥ |
bhakto ''si me sakhā ceti rahasyaṃ hy etad uttamam ||', null, null),
  ('gita', 4, 4, 'अर्जुन उवाच', 'arjuna uvāca', 'अपरं भवतो जन्म परं जन्म विवस्वतः ।
कथमेतद्विजानीयां त्वमादौ प्रोक्तवानिति ॥', 'aparaṃ bhavato janma paraṃ janma vivasvataḥ |
katham etad vijānīyāṃ tvam ādau proktavān iti ||', null, null),
  ('gita', 4, 5, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'बहूनि मे व्यतीतानि जन्मानि तव चार्जुन ।
तान्यहं वेद सर्वाणि न त्वं वेत्थ परंतप ॥', 'bahūni me vyatītāni janmāni tava cārjuna |
tāny ahaṃ veda sarvāṇi na tvaṃ vettha paraṃtapa ||', null, null),
  ('gita', 4, 6, null, null, 'अजोऽपि सन्नव्ययात्मा भूतानामीश्वरोऽपि सन् ।
प्रकृतिं स्वामधिष्ठाय संभवाम्यात्ममायया ॥', 'ajo ''pi sann avyayātmā bhūtānām īśvaro ''pi san |
prakṛtiṃ svām adhiṣṭhāya saṃbhavāmy ātmamāyayā ||', null, null),
  ('gita', 4, 7, null, null, 'यदा यदा हि धर्मस्य ग्लानिर्भवति भारत ।
अभ्युत्थानमधर्मस्य तदात्मानं सृजाम्यहम् ॥', 'yadā yadā hi dharmasya glānir bhavati bhārata |
abhyutthānam adharmasya tadātmānaṃ sṛjāmy aham ||', null, null),
  ('gita', 4, 8, null, null, 'परित्राणाय साधूनां विनाशाय च दुष्कृताम् ।
धर्मसंस्थापनार्थाय संभवामि युगे युगे ॥', 'paritrāṇāya sādhūnāṃ vināśāya ca duṣkṛtām |
dharmasaṃsthāpanārthāya saṃbhavāmi yuge yuge ||', null, null),
  ('gita', 4, 9, null, null, 'जन्म कर्म च मे दिव्यमेवं यो वेत्ति तत्त्वतः ।
त्यक्त्वा देहं पुनर्जन्म नैति मामेति सोऽर्जुन ॥', 'janma karma ca me divyam evaṃ yo vetti tattvataḥ |
tyaktvā dehaṃ punarjanma naiti mām eti so ''rjuna ||', null, null),
  ('gita', 4, 10, null, null, 'वीतरागभयक्रोधा मन्मया मामुपाश्रिताः ।
बहवो ज्ञानतपसा पूता मद्भावमागताः ॥', 'vītarāgabhayakrodhā manmayā mām upāśritāḥ |
bahavo jñānatapasā pūtā madbhāvam āgatāḥ ||', null, null),
  ('gita', 4, 11, null, null, 'ये यथा मां प्रपद्यन्ते तांस्तथैव भजाम्यहम् ।
मम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः ॥', 'ye yathā māṃ prapadyante tāṃs tathaiva bhajāmy aham |
mama vartmānuvartante manuṣyāḥ pārtha sarvaśaḥ ||', null, null),
  ('gita', 4, 12, null, null, 'काङ्क्षन्तः कर्मणां सिद्धिं यजन्त इह देवताः ।
क्षिप्रं हि मानुषे लोके सिद्धिर्भवति कर्मजा ॥', 'kāṅkṣantaḥ karmaṇāṃ siddhiṃ yajanta iha devatāḥ |
kṣipraṃ hi mānuṣe loke siddhir bhavati karmajā ||', null, null),
  ('gita', 4, 13, null, null, 'चातुर्वर्ण्यं मया सृष्टं गुणकर्मविभागशः ।
तस्य कर्तारमपि मां विद्ध्यकर्तारमव्ययम् ॥', 'cāturvarṇyaṃ mayā sṛṣṭaṃ guṇakarmavibhāgaśaḥ |
tasya kartāram api māṃ viddhy akartāram avyayam ||', null, null),
  ('gita', 4, 14, null, null, 'न मां कर्माणि लिम्पन्ति न मे कर्मफले स्पृहा ।
इति मां योऽभिजानाति कर्मभिर्न स बध्यते ॥', 'na māṃ karmāṇi limpanti na me karmaphale spṛhā |
iti māṃ yo ''bhijānāti karmabhir na sa badhyate ||', null, null),
  ('gita', 4, 15, null, null, 'एवं ज्ञात्वा कृतं कर्म पूर्वैरपि मुमुक्षुभिः ।
कुरु कर्मैव तस्मात्त्वं पूर्वैः पूर्वतरं कृतम् ॥', 'evaṃ jñātvā kṛtaṃ karma pūrvair api mumukṣubhiḥ |
kuru karmaiva tasmāt tvaṃ pūrvaiḥ pūrvataraṃ kṛtam ||', null, null),
  ('gita', 4, 16, null, null, 'किं कर्म किमकर्मेति कवयोऽप्यत्र मोहिताः ।
तत्ते कर्म प्रवक्ष्यामि यज्ज्ञात्वा मोक्ष्यसेऽशुभात् ॥', 'kiṃ karma kimakarmeti kavayo ''py atra mohitāḥ |
tat te karma pravakṣyāmi yaj jñātvā mokṣyase ''śubhāt ||', null, null),
  ('gita', 4, 17, null, null, 'कर्मणो ह्यपि बोद्धव्यं बोद्धव्यं च विकर्मणः ।
अकर्मणश्च बोद्धव्यं गहना कर्मणो गतिः ॥', 'karmaṇo hy api boddhavyaṃ boddhavyaṃ ca vikarmaṇaḥ |
akarmaṇaś ca boddhavyaṃ gahanā karmaṇo gatiḥ ||', null, null),
  ('gita', 4, 18, null, null, 'कर्मण्यकर्म यः पश्येदकर्मणि च कर्म यः ।
स बुद्धिमान्मनुष्येषु स युक्तः कृत्स्नकर्मकृत् ॥', 'karmaṇy akarma yaḥ paśyed akarmaṇi ca karma yaḥ |
sa buddhimān manuṣyeṣu sa yuktaḥ kṛtsnakarmakṛt ||', null, null),
  ('gita', 4, 19, null, null, 'यस्य सर्वे समारम्भाः कामसंकल्पवर्जिताः ।
ज्ञानाग्निदग्धकर्माणं तमाहुः पण्डितं बुधाः ॥', 'yasya sarve samārambhāḥ kāmasaṃkalpavarjitāḥ |
jñānāgnidagdhakarmāṇaṃ tam āhuḥ paṇḍitaṃ budhāḥ ||', null, null),
  ('gita', 4, 20, null, null, 'त्यक्त्वा कर्मफलासङ्गं नित्यतृप्तो निराश्रयः ।
कर्मण्यभिप्रवृत्तोऽपि नैव किं चित्करोति सः ॥', 'tyaktvā karmaphalāsaṅgaṃ nityatṛpto nirāśrayaḥ |
karmaṇy abhipravṛtto ''pi naiva kiṃ cit karoti saḥ ||', null, null),
  ('gita', 4, 21, null, null, 'निराशीर्यतचित्तात्मा त्यक्तसर्वपरिग्रहः ।
शारीरं केवलं कर्म कुर्वन्नाप्नोति किल्बिषम् ॥', 'nirāśīr yatacittātmā tyaktasarvaparigrahaḥ |
śārīraṃ kevalaṃ karma kurvan nāpnoti kilbiṣam ||', null, null),
  ('gita', 4, 22, null, null, 'यदृच्छालाभसंतुष्टो द्वन्द्वातीतो विमत्सरः ।
समः सिद्धावसिद्धौ च कृत्वापि न निबध्यते ॥', 'yadṛcchālābhasaṃtuṣṭo dvandvātīto vimatsaraḥ |
samaḥ siddhāv asiddhau ca kṛtvāpi na nibadhyate ||', null, null),
  ('gita', 4, 23, null, null, 'गतसङ्गस्य मुक्तस्य ज्ञानावस्थितचेतसः ।
यज्ञायाचरतः कर्म समग्रं प्रविलीयते ॥', 'gatasaṅgasya muktasya jñānāvasthitacetasaḥ |
yajñāyācarataḥ karma samagraṃ pravilīyate ||', null, null),
  ('gita', 4, 24, null, null, 'ब्रह्मार्पणं ब्रह्म हविर्ब्रह्माग्नौ ब्रह्मणा हुतम् ।
ब्रह्मैव तेन गन्तव्यं ब्रह्मकर्मसमाधिना ॥', 'brahmārpaṇaṃ brahma havir brahmāgnau brahmaṇā hutam |
brahmaiva tena gantavyaṃ brahmakarmasamādhinā ||', null, null),
  ('gita', 4, 25, null, null, 'दैवमेवापरे यज्ञं योगिनः पर्युपासते ।
ब्रह्माग्नावपरे यज्ञं यज्ञेनैवोपजुह्वति ॥', 'daivam evāpare yajñaṃ yoginaḥ paryupāsate |
brahmāgnāv apare yajñaṃ yajñenaivopajuhvati ||', null, null),
  ('gita', 4, 26, null, null, 'श्रोत्रादीनीन्द्रियाण्यन्ये संयमाग्निषु जुह्वति ।
शब्दादीन्विषयानन्य इन्द्रियाग्निषु जुह्वति ॥', 'śrotrādīnīndriyāṇy anye saṃyamāgniṣu juhvati |
śabdādīn viṣayān anya indriyāgniṣu juhvati ||', null, null),
  ('gita', 4, 27, null, null, 'सर्वाणीन्द्रियकर्माणि प्राणकर्माणि चापरे ।
आत्मसंयमयोगाग्नौ जुह्वति ज्ञानदीपिते ॥', 'sarvāṇīndriyakarmāṇi prāṇakarmāṇi cāpare |
ātmasaṃyamayogāgnau juhvati jñānadīpite ||', null, null),
  ('gita', 4, 28, null, null, 'द्रव्ययज्ञास्तपोयज्ञा योगयज्ञास्तथापरे ।
स्वाध्यायज्ञानयज्ञाश्च यतयः संशितव्रताः ॥', 'dravyayajñās tapoyajñā yogayajñās tathāpare |
svādhyāyajñānayajñāś ca yatayaḥ saṃśitavratāḥ ||', null, null),
  ('gita', 4, 29, null, null, 'अपाने जुह्वति प्राणं प्राणेऽपानं तथापरे ।
प्राणापानगती रुद्ध्वा प्राणायामपरायणाः ॥', 'apāne juhvati prāṇaṃ prāṇe ''pānaṃ tathāpare |
prāṇāpānagatī ruddhvā prāṇāyāmaparāyaṇāḥ ||', null, null),
  ('gita', 4, 30, null, null, 'अपरे नियताहाराः प्राणान्प्राणेषु जुह्वति ।
सर्वेऽप्येते यज्ञविदो यज्ञक्षपितकल्मषाः ॥', 'apare niyatāhārāḥ prāṇān prāṇeṣu juhvati |
sarve ''py ete yajñavido yajñakṣapitakalmaṣāḥ ||', null, null),
  ('gita', 4, 31, null, null, 'यज्ञशिष्टामृतभुजो यान्ति ब्रह्म सनातनम् ।
नायं लोकोऽस्त्ययज्ञस्य कुतोऽन्यः कुरुसत्तम ॥', 'yajñaśiṣṭāmṛtabhujo yānti brahma sanātanam |
nāyaṃ loko ''sty ayajñasya kuto ''nyaḥ kurusattama ||', null, null),
  ('gita', 4, 32, null, null, 'एवं बहुविधा यज्ञा वितता ब्रह्मणो मुखे ।
कर्मजान्विद्धि तान्सर्वानेवं ज्ञात्वा विमोक्ष्यसे ॥', 'evaṃ bahuvidhā yajñā vitatā brahmaṇo mukhe |
karmajān viddhi tān sarvān evaṃ jñātvā vimokṣyase ||', null, null),
  ('gita', 4, 33, null, null, 'श्रेयान्द्रव्यमयाद्यज्ञाज्ज्ञानयज्ञः परंतप ।
सर्वं कर्माखिलं पार्थ ज्ञाने परिसमाप्यते ॥', 'śreyān dravyamayād yajñāj jñānayajñaḥ paraṃtapa |
sarvaṃ karmākhilaṃ pārtha jñāne parisamāpyate ||', null, null),
  ('gita', 4, 34, null, null, 'तद्विद्धि प्रणिपातेन परिप्रश्नेन सेवया ।
उपदेक्ष्यन्ति ते ज्ञानं ज्ञानिनस्तत्त्वदर्शिनः ॥', 'tad viddhi praṇipātena paripraśnena sevayā |
upadekṣyanti te jñānaṃ jñāninas tattvadarśinaḥ ||', null, null),
  ('gita', 4, 35, null, null, 'यज्ज्ञात्वा न पुनर्मोहमेवं यास्यसि पाण्डव ।
येन भूतान्यशेषेण द्रक्ष्यस्यात्मन्यथो मयि ॥', 'yaj jñātvā na punar moham evaṃ yāsyasi pāṇḍava |
yena bhūtāny aśeṣeṇa drakṣyasy ātmany atho mayi ||', null, null),
  ('gita', 4, 36, null, null, 'अपि चेदसि पापेभ्यः सर्वेभ्यः पापकृत्तमः ।
सर्वं ज्ञानप्लवेनैव वृजिनं संतरिष्यसि ॥', 'api ced asi pāpebhyaḥ sarvebhyaḥ pāpakṛttamaḥ |
sarvaṃ jñānaplavenaiva vṛjinaṃ saṃtariṣyasi ||', null, null),
  ('gita', 4, 37, null, null, 'यथैधांसि समिद्धोऽग्निर्भस्मसात्कुरुतेऽर्जुन ।
ज्ञानाग्निः सर्वकर्माणि भस्मसात्कुरुते तथा ॥', 'yathaidhāṃsi samiddho ''gnir bhasmasāt kurute ''rjuna |
jñānāgniḥ sarvakarmāṇi bhasmasāt kurute tathā ||', null, null),
  ('gita', 4, 38, null, null, 'न हि ज्ञानेन सदृशं पवित्रमिह विद्यते ।
तत्स्वयं योगसंसिद्धः कालेनात्मनि विन्दति ॥', 'na hi jñānena sadṛśaṃ pavitram iha vidyate |
tat svayaṃ yogasaṃsiddhaḥ kālenātmani vindati ||', null, null),
  ('gita', 4, 39, null, null, 'श्रद्धावाँल्लभते ज्ञानं तत्परः संयतेन्द्रियः ।
ज्ञानं लब्ध्वा परां शान्तिमचिरेणाधिगच्छति ॥', 'śraddhāvāṁl labhate jñānaṃ tatparaḥ saṃyatendriyaḥ |
jñānaṃ labdhvā parāṃ śāntim acireṇādhigacchati ||', null, null),
  ('gita', 4, 40, null, null, 'अज्ञश्चाश्रद्दधानश्च संशयात्मा विनश्यति ।
नायं लोकोऽस्ति न परो न सुखं संशयात्मनः ॥', 'ajñaś cāśraddadhānaś ca saṃśayātmā vinaśyati |
nāyaṃ loko ''sti na paro na sukhaṃ saṃśayātmanaḥ ||', null, null),
  ('gita', 4, 41, null, null, 'योगसंन्यस्तकर्माणं ज्ञानसंछिन्नसंशयम् ।
आत्मवन्तं न कर्माणि निबध्नन्ति धनंजय ॥', 'yogasaṃnyastakarmāṇaṃ jñānasaṃchinnasaṃśayam |
ātmavantaṃ na karmāṇi nibadhnanti dhanaṃjaya ||', null, null),
  ('gita', 4, 42, null, null, 'तस्मादज्ञानसंभूतं हृत्स्थं ज्ञानासिनात्मनः ।
छित्त्वैनं संशयं योगमातिष्ठोत्तिष्ठ भारत ॥', 'tasmād ajñānasaṃbhūtaṃ hṛtsthaṃ jñānāsinātmanaḥ |
chittvainaṃ saṃśayaṃ yogam ātiṣṭhottiṣṭha bhārata ||', null, null),
  ('gita', 5, 1, 'अर्जुन उवाच', 'arjuna uvāca', 'संन्यासं कर्मणां कृष्ण पुनर्योगं च शंससि ।
यच्छ्रेय एतयोरेकं तन्मे ब्रूहि सुनिश्चितम् ॥', 'saṃnyāsaṃ karmaṇāṃ kṛṣṇa punar yogaṃ ca śaṃsasi |
yac chreya etayor ekaṃ tan me brūhi suniścitam ||', null, null),
  ('gita', 5, 2, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'संन्यासः कर्मयोगश्च निःश्रेयसकरावुभौ ।
तयोस्तु कर्मसंन्यासात्कर्मयोगो विशिष्यते ॥', 'saṃnyāsaḥ karmayogaś ca niḥśreyasakarāv ubhau |
tayos tu karmasaṃnyāsāt karmayogo viśiṣyate ||', null, null),
  ('gita', 5, 3, null, null, 'ज्ञेयः स नित्यसंन्यासी यो न द्वेष्टि न काङ्क्षति ।
निर्द्वन्द्वो हि महाबाहो सुखं बन्धात्प्रमुच्यते ॥', 'jñeyaḥ sa nityasaṃnyāsī yo na dveṣṭi na kāṅkṣati |
nirdvandvo hi mahābāho sukhaṃ bandhāt pramucyate ||', null, null),
  ('gita', 5, 4, null, null, 'सांख्ययोगौ पृथग्बालाः प्रवदन्ति न पण्डिताः ।
एकमप्यास्थितः सम्यगुभयोर्विन्दते फलम् ॥', 'sāṃkhyayogau pṛthag bālāḥ pravadanti na paṇḍitāḥ |
ekam apy āsthitaḥ samyag ubhayor vindate phalam ||', null, null),
  ('gita', 5, 5, null, null, 'यत्सांख्यैः प्राप्यते स्थानं तद्योगैरपि गम्यते ।
एकं सांख्यं च योगं च यः पश्यति स पश्यति ॥', 'yat sāṃkhyaiḥ prāpyate sthānaṃ tad yogair api gamyate |
ekaṃ sāṃkhyaṃ ca yogaṃ ca yaḥ paśyati sa paśyati ||', null, null),
  ('gita', 5, 6, null, null, 'संन्यासस्तु महाबाहो दुःखमाप्तुमयोगतः ।
योगयुक्तो मुनिर्ब्रह्म नचिरेणाधिगच्छति ॥', 'saṃnyāsas tu mahābāho duḥkham āptum ayogataḥ |
yogayukto munir brahma nacireṇādhigacchati ||', null, null),
  ('gita', 5, 7, null, null, 'योगयुक्तो विशुद्धात्मा विजितात्मा जितेन्द्रियः ।
सर्वभूतात्मभूतात्मा कुर्वन्नपि न लिप्यते ॥', 'yogayukto viśuddhātmā vijitātmā jitendriyaḥ |
sarvabhūtātmabhūtātmā kurvann api na lipyate ||', null, null),
  ('gita', 5, 8, null, null, 'नैव किं चित्करोमीति युक्तो मन्येत तत्त्ववित् ।
पश्यञ्शृण्वन्स्पृशञ्जिघ्रन्नश्नन्गच्छन्स्वपञ्श्वसन् ॥', 'naiva kiṃ cit karomīti yukto manyeta tattvavit |
paśyañ śṛṇvan spṛśañ jighrann aśnan gacchan svapañ śvasan ||', null, null),
  ('gita', 5, 9, null, null, 'प्रलपन्विसृजन्गृह्णन्नुन्मिषन्निमिषन्नपि ।
इन्द्रियाणीन्द्रियार्थेषु वर्तन्त इति धारयन् ॥', 'pralapan visṛjan gṛhṇann unmiṣan nimiṣann api |
indriyāṇīndriyārtheṣu vartanta iti dhārayan ||', null, null),
  ('gita', 5, 10, null, null, 'ब्रह्मण्याधाय कर्माणि सङ्गं त्यक्त्वा करोति यः ।
लिप्यते न स पापेन पद्मपत्रमिवाम्भसा ॥', 'brahmaṇy ādhāya karmāṇi saṅgaṃ tyaktvā karoti yaḥ |
lipyate na sa pāpena padmapatram ivāmbhasā ||', null, null),
  ('gita', 5, 11, null, null, 'कायेन मनसा बुद्ध्या केवलैरिन्द्रियैरपि ।
योगिनः कर्म कुर्वन्ति सङ्गं त्यक्त्वात्मशुद्धये ॥', 'kāyena manasā buddhyā kevalair indriyair api |
yoginaḥ karma kurvanti saṅgaṃ tyaktvātmaśuddhaye ||', null, null),
  ('gita', 5, 12, null, null, 'युक्तः कर्मफलं त्यक्त्वा शान्तिमाप्नोति नैष्ठिकीम् ।
अयुक्तः कामकारेण फले सक्तो निबध्यते ॥', 'yuktaḥ karmaphalaṃ tyaktvā śāntim āpnoti naiṣṭhikīm |
ayuktaḥ kāmakāreṇa phale sakto nibadhyate ||', null, null),
  ('gita', 5, 13, null, null, 'सर्वकर्माणि मनसा संन्यस्यास्ते सुखं वशी ।
नवद्वारे पुरे देही नैव कुर्वन्न कारयन् ॥', 'sarvakarmāṇi manasā saṃnyasyāste sukhaṃ vaśī |
navadvāre pure dehī naiva kurvan na kārayan ||', null, null),
  ('gita', 5, 14, null, null, 'न कर्तृत्वं न कर्माणि लोकस्य सृजति प्रभुः ।
न कर्मफलसंयोगं स्वभावस्तु प्रवर्तते ॥', 'na kartṛtvaṃ na karmāṇi lokasya sṛjati prabhuḥ |
na karmaphalasaṃyogaṃ svabhāvas tu pravartate ||', null, null),
  ('gita', 5, 15, null, null, 'नादत्ते कस्य चित्पापं न चैव सुकृतं विभुः ।
अज्ञानेनावृतं ज्ञानं तेन मुह्यन्ति जन्तवः ॥', 'nādatte kasya cit pāpaṃ na caiva sukṛtaṃ vibhuḥ |
ajñānenāvṛtaṃ jñānaṃ tena muhyanti jantavaḥ ||', null, null),
  ('gita', 5, 16, null, null, 'ज्ञानेन तु तदज्ञानं येषां नाशितमात्मनः ।
तेषामादित्यवज्ज्ञानं प्रकाशयति तत्परम् ॥', 'jñānena tu tad ajñānaṃ yeṣāṃ nāśitam ātmanaḥ |
teṣām ādityavaj jñānaṃ prakāśayati tatparam ||', null, null),
  ('gita', 5, 17, null, null, 'तद्बुद्धयस्तदात्मानस्तन्निष्ठास्तत्परायणाः ।
गच्छन्त्यपुनरावृत्तिं ज्ञाननिर्धूतकल्मषाः ॥', 'tadbuddhayas tadātmānas tanniṣṭhās tatparāyaṇāḥ |
gacchanty apunarāvṛttiṃ jñānanirdhūtakalmaṣāḥ ||', null, null),
  ('gita', 5, 18, null, null, 'विद्याविनयसंपन्ने ब्राह्मणे गवि हस्तिनि ।
शुनि चैव श्वपाके च पण्डिताः समदर्शिनः ॥', 'vidyāvinayasaṃpanne brāhmaṇe gavi hastini |
śuni caiva śvapāke ca paṇḍitāḥ samadarśinaḥ ||', null, null),
  ('gita', 5, 19, null, null, 'इहैव तैर्जितः सर्गो येषां साम्ये स्थितं मनः ।
निर्दोषं हि समं ब्रह्म तस्माद्ब्रह्मणि ते स्थिताः ॥', 'ihaiva tair jitaḥ sargo yeṣāṃ sāmye sthitaṃ manaḥ |
nirdoṣaṃ hi samaṃ brahma tasmād brahmaṇi te sthitāḥ ||', null, null),
  ('gita', 5, 20, null, null, 'न प्रहृष्येत्प्रियं प्राप्य नोद्विजेत्प्राप्य चाप्रियम् ।
स्थिरबुद्धिरसंमूढो ब्रह्मविद्ब्रह्मणि स्थितः ॥', 'na prahṛṣyet priyaṃ prāpya nodvijet prāpya cāpriyam |
sthirabuddhir asaṃmūḍho brahmavid brahmaṇi sthitaḥ ||', null, null),
  ('gita', 5, 21, null, null, 'बाह्यस्पर्शेष्वसक्तात्मा विन्दत्यात्मनि यत्सुखम् ।
स ब्रह्मयोगयुक्तात्मा सुखमक्षयमश्नुते ॥', 'bāhyasparśeṣv asaktātmā vindaty ātmani yat sukham |
sa brahmayogayuktātmā sukham akṣayam aśnute ||', null, null),
  ('gita', 5, 22, null, null, 'ये हि संस्पर्शजा भोगा दुःखयोनय एव ते ।
आद्यन्तवन्तः कौन्तेय न तेषु रमते बुधः ॥', 'ye hi saṃsparśajā bhogā duḥkhayonaya eva te |
ādyantavantaḥ kaunteya na teṣu ramate budhaḥ ||', null, null),
  ('gita', 5, 23, null, null, 'शक्नोतीहैव यः सोढुं प्राक्शरीरविमोक्षणात् ।
कामक्रोधोद्भवं वेगं स युक्तः स सुखी नरः ॥', 'śaknotīhaiva yaḥ soḍhuṃ prāk śarīravimokṣaṇāt |
kāmakrodhodbhavaṃ vegaṃ sa yuktaḥ sa sukhī naraḥ ||', null, null),
  ('gita', 5, 24, null, null, 'योऽन्तःसुखोऽन्तरारामस्तथान्तर्ज्योतिरेव यः ।
स योगी ब्रह्मनिर्वाणं ब्रह्मभूतोऽधिगच्छति ॥', 'yo ''ntaḥsukho ''ntarārāmas tathāntarjyotir eva yaḥ |
sa yogī brahmanirvāṇaṃ brahmabhūto ''dhigacchati ||', null, null),
  ('gita', 5, 25, null, null, 'लभन्ते ब्रह्मनिर्वाणमृषयः क्षीणकल्मषाः ।
छिन्नद्वैधा यतात्मानः सर्वभूतहिते रताः ॥', 'labhante brahmanirvāṇam ṛṣayaḥ kṣīṇakalmaṣāḥ |
chinnadvaidhā yatātmānaḥ sarvabhūtahite ratāḥ ||', null, null),
  ('gita', 5, 26, null, null, 'कामक्रोधवियुक्तानां यतीनां यतचेतसाम् ।
अभितो ब्रह्मनिर्वाणं वर्तते विदितात्मनाम् ॥', 'kāmakrodhaviyuktānāṃ yatīnāṃ yatacetasām |
abhito brahmanirvāṇaṃ vartate viditātmanām ||', null, null),
  ('gita', 5, 27, null, null, 'स्पर्शान्कृत्वा बहिर्बाह्यांश्चक्षुश्चैवान्तरे भ्रुवोः ।
प्राणापानौ समौ कृत्वा नासाभ्यन्तरचारिणौ ॥', 'sparśān kṛtvā bahir bāhyāṃś cakṣuś caivāntare bhruvoḥ |
prāṇāpānau samau kṛtvā nāsābhyantaracāriṇau ||', null, null),
  ('gita', 5, 28, null, null, 'यतेन्द्रियमनोबुद्धिर्मुनिर्मोक्षपरायणः ।
विगतेच्छाभयक्रोधो यः सदा मुक्त एव सः ॥', 'yatendriyamanobuddhir munir mokṣaparāyaṇaḥ |
vigatecchābhayakrodho yaḥ sadā mukta eva saḥ ||', null, null),
  ('gita', 5, 29, null, null, 'भोक्तारं यज्ञतपसां सर्वलोकमहेश्वरम् ।
सुहृदं सर्वभूतानां ज्ञात्वा मां शान्तिमृच्छति ॥', 'bhoktāraṃ yajñatapasāṃ sarvalokamaheśvaram |
suhṛdaṃ sarvabhūtānāṃ jñātvā māṃ śāntim ṛcchati ||', null, null),
  ('gita', 6, 1, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'अनाश्रितः कर्मफलं कार्यं कर्म करोति यः ।
स संन्यासी च योगी च न निरग्निर्न चाक्रियः ॥', 'anāśritaḥ karmaphalaṃ kāryaṃ karma karoti yaḥ |
sa saṃnyāsī ca yogī ca na niragnir na cākriyaḥ ||', null, null),
  ('gita', 6, 2, null, null, 'यं संन्यासमिति प्राहुर्योगं तं विद्धि पाण्डव ।
न ह्यसंन्यस्तसंकल्पो योगी भवति कश्चन ॥', 'yaṃ saṃnyāsam iti prāhur yogaṃ taṃ viddhi pāṇḍava |
na hy asaṃnyastasaṃkalpo yogī bhavati kaś cana ||', null, null),
  ('gita', 6, 3, null, null, 'आरुरुक्षोर्मुनेर्योगं कर्म कारणमुच्यते ।
योगारूढस्य तस्यैव शमः कारणमुच्यते ॥', 'ārurukṣor muner yogaṃ karma kāraṇam ucyate |
yogārūḍhasya tasyaiva śamaḥ kāraṇam ucyate ||', null, null),
  ('gita', 6, 4, null, null, 'यदा हि नेन्द्रियार्थेषु न कर्मस्वनुषज्जते ।
सर्वसंकल्पसंन्यासी योगारूढस्तदोच्यते ॥', 'yadā hi nendriyārtheṣu na karmasv anuṣajjate |
sarvasaṃkalpasaṃnyāsī yogārūḍhas tadocyate ||', null, null),
  ('gita', 6, 5, null, null, 'उद्धरेदात्मनात्मानं नात्मानमवसादयेत् ।
आत्मैव ह्यात्मनो बन्धुरात्मैव रिपुरात्मनः ॥', 'uddhared ātmanātmānaṃ nātmānam avasādayet |
ātmaiva hy ātmano bandhur ātmaiva ripur ātmanaḥ ||', null, null),
  ('gita', 6, 6, null, null, 'बन्धुरात्मात्मनस्तस्य येनात्मैवात्मना जितः ।
अनात्मनस्तु शत्रुत्वे वर्तेतात्मैव शत्रुवत् ॥', 'bandhur ātmātmanas tasya yenātmaivātmanā jitaḥ |
anātmanas tu śatrutve vartetātmaiva śatruvat ||', null, null),
  ('gita', 6, 7, null, null, 'जितात्मनः प्रशान्तस्य परमात्मा समाहितः ।
शीतोष्णसुखदुःखेषु तथा मानापमानयोः ॥', 'jitātmanaḥ praśāntasya paramātmā samāhitaḥ |
śītoṣṇasukhaduḥkheṣu tathā mānāpamānayoḥ ||', null, null),
  ('gita', 6, 8, null, null, 'ज्ञानविज्ञानतृप्तात्मा कूटस्थो विजितेन्द्रियः ।
युक्त इत्युच्यते योगी समलोष्टाश्मकाञ्चनः ॥', 'jñānavijñānatṛptātmā kūṭastho vijitendriyaḥ |
yukta ity ucyate yogī samaloṣṭāśmakāñcanaḥ ||', null, null),
  ('gita', 6, 9, null, null, 'सुहृन्मित्रार्युदासीनमध्यस्थद्वेष्यबन्धुषु ।
साधुष्वपि च पापेषु समबुद्धिर्विशिष्यते ॥', 'suhṛnmitrāryudāsīnamadhyasthadveṣyabandhuṣu |
sādhuṣv api ca pāpeṣu samabuddhir viśiṣyate ||', null, null),
  ('gita', 6, 10, null, null, 'योगी युञ्जीत सततमात्मानं रहसि स्थितः ।
एकाकी यतचित्तात्मा निराशीरपरिग्रहः ॥', 'yogī yuñjīta satatam ātmānaṃ rahasi sthitaḥ |
ekākī yatacittātmā nirāśīr aparigrahaḥ ||', null, null),
  ('gita', 6, 11, null, null, 'शुचौ देशे प्रतिष्ठाप्य स्थिरमासनमात्मनः ।
नात्युच्छ्रितं नातिनीचं चैलाजिनकुशोत्तरम् ॥', 'śucau deśe pratiṣṭhāpya sthiram āsanam ātmanaḥ |
nātyucchritaṃ nātinīcaṃ cailājinakuśottaram ||', null, null),
  ('gita', 6, 12, null, null, 'तत्रैकाग्रं मनः कृत्वा यतचित्तेन्द्रियक्रियः ।
उपविश्यासने युञ्ज्याद्योगमात्मविशुद्धये ॥', 'tatraikāgraṃ manaḥ kṛtvā yatacittendriyakriyaḥ |
upaviśyāsane yuñjyād yogam ātmaviśuddhaye ||', null, null),
  ('gita', 6, 13, null, null, 'समं कायशिरोग्रीवं धारयन्नचलं स्थिरः ।
संप्रेक्ष्य नासिकाग्रं स्वं दिशश्चानवलोकयन् ॥', 'samaṃ kāyaśirogrīvaṃ dhārayann acalaṃ sthiraḥ |
saṃprekṣya nāsikāgraṃ svaṃ diśaś cānavalokayan ||', null, null),
  ('gita', 6, 14, null, null, 'प्रशान्तात्मा विगतभीर्ब्रह्मचारिव्रते स्थितः ।
मनः संयम्य मच्चित्तो युक्त आसीत मत्परः ॥', 'praśāntātmā vigatabhīr brahmacārivrate sthitaḥ |
manaḥ saṃyamya maccitto yukta āsīta matparaḥ ||', null, null),
  ('gita', 6, 15, null, null, 'युञ्जन्नेवं सदात्मानं योगी नियतमानसः ।
शान्तिं निर्वाणपरमां मत्संस्थामधिगच्छति ॥', 'yuñjann evaṃ sadātmānaṃ yogī niyatamānasaḥ |
śāntiṃ nirvāṇaparamāṃ matsaṃsthām adhigacchati ||', null, null),
  ('gita', 6, 16, null, null, 'नात्यश्नतस्तु योगोऽस्ति न चैकान्तमनश्नतः ।
न चातिस्वप्नशीलस्य जाग्रतो नैव चार्जुन ॥', 'nātyaśnatas tu yogo ''sti na caikāntam anaśnataḥ |
na cātisvapnaśīlasya jāgrato naiva cārjuna ||', null, null),
  ('gita', 6, 17, null, null, 'युक्ताहारविहारस्य युक्तचेष्टस्य कर्मसु ।
युक्तस्वप्नावबोधस्य योगो भवति दुःखहा ॥', 'yuktāhāravihārasya yuktaceṣṭasya karmasu |
yuktasvapnāvabodhasya yogo bhavati duḥkhahā ||', null, null),
  ('gita', 6, 18, null, null, 'यदा विनियतं चित्तमात्मन्येवावतिष्ठते ।
निःस्पृहः सर्वकामेभ्यो युक्त इत्युच्यते तदा ॥', 'yadā viniyataṃ cittam ātmany evāvatiṣṭhate |
niḥspṛhaḥ sarvakāmebhyo yukta ity ucyate tadā ||', null, null),
  ('gita', 6, 19, null, null, 'यथा दीपो निवातस्थो नेङ्गते सोपमा स्मृता ।
योगिनो यतचित्तस्य युञ्जतो योगमात्मनः ॥', 'yathā dīpo nivātastho neṅgate sopamā smṛtā |
yogino yatacittasya yuñjato yogam ātmanaḥ ||', null, null),
  ('gita', 6, 20, null, null, 'यत्रोपरमते चित्तं निरुद्धं योगसेवया ।
यत्र चैवात्मनात्मानं पश्यन्नात्मनि तुष्यति ॥', 'yatroparamate cittaṃ niruddhaṃ yogasevayā |
yatra caivātmanātmānaṃ paśyann ātmani tuṣyati ||', null, null),
  ('gita', 6, 21, null, null, 'सुखमात्यन्तिकं यत्तद्बुद्धिग्राह्यमतीन्द्रियम् ।
वेत्ति यत्र न चैवायं स्थितश्चलति तत्त्वतः ॥', 'sukham ātyantikaṃ yat tad buddhigrāhyam atīndriyam |
vetti yatra na caivāyaṃ sthitaś calati tattvataḥ ||', null, null),
  ('gita', 6, 22, null, null, 'यं लब्ध्वा चापरं लाभं मन्यते नाधिकं ततः ।
यस्मिन्स्थितो न दुःखेन गुरुणापि विचाल्यते ॥', 'yaṃ labdhvā cāparaṃ lābhaṃ manyate nādhikaṃ tataḥ |
yasmin sthito na duḥkhena guruṇāpi vicālyate ||', null, null),
  ('gita', 6, 23, null, null, 'तं विद्याद्दुःखसंयोगवियोगं योगसंज्ञितम् ।
स निश्चयेन योक्तव्यो योगोऽनिर्विण्णचेतसा ॥', 'taṃ vidyād duḥkhasaṃyogaviyogaṃ yogasaṃjñitam |
sa niścayena yoktavyo yogo ''nirviṇṇacetasā ||', null, null),
  ('gita', 6, 24, null, null, 'संकल्पप्रभवान्कामांस्त्यक्त्वा सर्वानशेषतः ।
मनसैवेन्द्रियग्रामं विनियम्य समन्ततः ॥', 'saṃkalpaprabhavān kāmāṃs tyaktvā sarvān aśeṣataḥ |
manasaivendriyagrāmaṃ viniyamya samantataḥ ||', null, null),
  ('gita', 6, 25, null, null, 'शनैः शनैरुपरमेद्बुद्ध्या धृतिगृहीतया ।
आत्मसंस्थं मनः कृत्वा न किं चिदपि चिन्तयेत् ॥', 'śanaiḥ śanair uparamed buddhyā dhṛtigṛhītayā |
ātmasaṃsthaṃ manaḥ kṛtvā na kiṃ cid api cintayet ||', null, null),
  ('gita', 6, 26, null, null, 'यतो यतो निश्चरति मनश्चञ्चलमस्थिरम् ।
ततस्ततो नियम्यैतदात्मन्येव वशं नयेत् ॥', 'yato yato niścarati manaś cañcalam asthiram |
tatas tato niyamyaitad ātmany eva vaśaṃ nayet ||', null, null),
  ('gita', 6, 27, null, null, 'प्रशान्तमनसं ह्येनं योगिनं सुखमुत्तमम् ।
उपैति शान्तरजसं ब्रह्मभूतमकल्मषम् ॥', 'praśāntamanasaṃ hy enaṃ yoginaṃ sukham uttamam |
upaiti śāntarajasaṃ brahmabhūtam akalmaṣam ||', null, null),
  ('gita', 6, 28, null, null, 'युञ्जन्नेवं सदात्मानं योगी विगतकल्मषः ।
सुखेन ब्रह्मसंस्पर्शमत्यन्तं सुखमश्नुते ॥', 'yuñjann evaṃ sadātmānaṃ yogī vigatakalmaṣaḥ |
sukhena brahmasaṃsparśam atyantaṃ sukham aśnute ||', null, null),
  ('gita', 6, 29, null, null, 'सर्वभूतस्थमात्मानं सर्वभूतानि चात्मनि ।
ईक्षते योगयुक्तात्मा सर्वत्र समदर्शनः ॥', 'sarvabhūtastham ātmānaṃ sarvabhūtāni cātmani |
īkṣate yogayuktātmā sarvatra samadarśanaḥ ||', null, null),
  ('gita', 6, 30, null, null, 'यो मां पश्यति सर्वत्र सर्वं च मयि पश्यति ।
तस्याहं न प्रणश्यामि स च मे न प्रणश्यति ॥', 'yo māṃ paśyati sarvatra sarvaṃ ca mayi paśyati |
tasyāhaṃ na praṇaśyāmi sa ca me na praṇaśyati ||', null, null),
  ('gita', 6, 31, null, null, 'सर्वभूतस्थितं यो मां भजत्येकत्वमास्थितः ।
सर्वथा वर्तमानोऽपि स योगी मयि वर्तते ॥', 'sarvabhūtasthitaṃ yo māṃ bhajaty ekatvam āsthitaḥ |
sarvathā vartamāno ''pi sa yogī mayi vartate ||', null, null),
  ('gita', 6, 32, null, null, 'आत्मौपम्येन सर्वत्र समं पश्यति योऽर्जुन ।
सुखं वा यदि वा दुःखं स योगी परमो मतः ॥', 'ātmaupamyena sarvatra samaṃ paśyati yo ''rjuna |
sukhaṃ vā yadi vā duḥkhaṃ sa yogī paramo mataḥ ||', null, null),
  ('gita', 6, 33, 'अर्जुन उवाच', 'arjuna uvāca', 'योऽयं योगस्त्वया प्रोक्तः साम्येन मधुसूदन ।
एतस्याहं न पश्यामि चञ्चलत्वात्स्थितिं स्थिराम् ॥', 'yo ''yaṃ yogas tvayā proktaḥ sāmyena madhusūdana |
etasyāhaṃ na paśyāmi cañcalatvāt sthitiṃ sthirām ||', null, null),
  ('gita', 6, 34, null, null, 'चञ्चलं हि मनः कृष्ण प्रमाथि बलवद्दृढम् ।
तस्याहं निग्रहं मन्ये वायोरिव सुदुष्करम् ॥', 'cañcalaṃ hi manaḥ kṛṣṇa pramāthi balavad dṛḍham |
tasyāhaṃ nigrahaṃ manye vāyor iva suduṣkaram ||', null, null),
  ('gita', 6, 35, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'असंशयं महाबाहो मनो दुर्णिग्रहं चलम् ।
अभ्यासेन तु कौन्तेय वैराग्येण च गृह्यते ॥', 'asaṃśayaṃ mahābāho mano durṇigrahaṃ calam |
abhyāsena tu kaunteya vairāgyeṇa ca gṛhyate ||', null, null),
  ('gita', 6, 36, null, null, 'असंयतात्मना योगो दुष्प्राप इति मे मतिः ।
वश्यात्मना तु यतता शक्योऽवाप्तुमुपायतः ॥', 'asaṃyatātmanā yogo duṣprāpa iti me matiḥ |
vaśyātmanā tu yatatā śakyo ''vāptum upāyataḥ ||', null, null),
  ('gita', 6, 37, 'अर्जुन उवाच', 'arjuna uvāca', 'अयतिः श्रद्धयोपेतो योगाच्चलितमानसः ।
अप्राप्य योगसंसिद्धिं कां गतिं कृष्ण गच्छति ॥', 'ayatiḥ śraddhayopeto yogāc calitamānasaḥ |
aprāpya yogasaṃsiddhiṃ kāṃ gatiṃ kṛṣṇa gacchati ||', null, null),
  ('gita', 6, 38, null, null, 'कच्चिन्नोभयविभ्रष्टश्छिन्नाभ्रमिव नश्यति ।
अप्रतिष्ठो महाबाहो विमूढो ब्रह्मणः पथि ॥', 'kac cin nobhayavibhraṣṭaś chinnābhram iva naśyati |
apratiṣṭho mahābāho vimūḍho brahmaṇaḥ pathi ||', null, null),
  ('gita', 6, 39, null, null, 'एतन्मे संशयं कृष्ण छेत्तुमर्हस्यशेषतः ।
त्वदन्यः संशयस्यास्य छेत्ता न ह्युपपद्यते ॥', 'etan me saṃśayaṃ kṛṣṇa chettum arhasy aśeṣataḥ |
tvadanyaḥ saṃśayasyāsya chettā na hy upapadyate ||', null, null),
  ('gita', 6, 40, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'पार्थ नैवेह नामुत्र विनाशस्तस्य विद्यते ।
न हि कल्याणकृत्कश्चिद्दुर्गतिं तात गच्छति ॥', 'pārtha naiveha nāmutra vināśas tasya vidyate |
na hi kalyāṇakṛt kaś cid durgatiṃ tāta gacchati ||', null, null),
  ('gita', 6, 41, null, null, 'प्राप्य पुण्यकृतां लोकानुषित्वा शाश्वतीः समाः ।
शुचीनां श्रीमतां गेहे योगभ्रष्टोऽभिजायते ॥', 'prāpya puṇyakṛtāṃ lokān uṣitvā śāśvatīḥ samāḥ |
śucīnāṃ śrīmatāṃ gehe yogabhraṣṭo ''bhijāyate ||', null, null),
  ('gita', 6, 42, null, null, 'अथ वा योगिनामेव कुले भवति धीमताम् ।
एतद्धि दुर्लभतरं लोके जन्म यदीदृशम् ॥', 'atha vā yoginām eva kule bhavati dhīmatām |
etad dhi durlabhataraṃ loke janma yad īdṛśam ||', null, null),
  ('gita', 6, 43, null, null, 'तत्र तं बुद्धिसंयोगं लभते पौर्वदेहिकम् ।
यतते च ततो भूयः संसिद्धौ कुरुनन्दन ॥', 'tatra taṃ buddhisaṃyogaṃ labhate paurvadehikam |
yatate ca tato bhūyaḥ saṃsiddhau kurunandana ||', null, null),
  ('gita', 6, 44, null, null, 'पूर्वाभ्यासेन तेनैव ह्रियते ह्यवशोऽपि सः ।
जिज्ञासुरपि योगस्य शब्दब्रह्मातिवर्तते ॥', 'pūrvābhyāsena tenaiva hriyate hy avaśo ''pi saḥ |
jijñāsur api yogasya śabdabrahmātivartate ||', null, null),
  ('gita', 6, 45, null, null, 'प्रयत्नाद्यतमानस्तु योगी संशुद्धकिल्बिषः ।
अनेकजन्मसंसिद्धस्ततो याति परां गतिम् ॥', 'prayatnād yatamānas tu yogī saṃśuddhakilbiṣaḥ |
anekajanmasaṃsiddhas tato yāti parāṃ gatim ||', null, null),
  ('gita', 6, 46, null, null, 'तपस्विभ्योऽधिको योगी ज्ञानिभ्योऽपि मतोऽधिकः ।
कर्मिभ्यश्चाधिको योगी तस्माद्योगी भवार्जुन ॥', 'tapasvibhyo ''dhiko yogī jñānibhyo ''pi mato ''dhikaḥ |
karmibhyaś cādhiko yogī tasmād yogī bhavārjuna ||', null, null),
  ('gita', 6, 47, null, null, 'योगिनामपि सर्वेषां मद्गतेनान्तरात्मना ।
श्रद्धावान्भजते यो मां स मे युक्ततमो मतः ॥', 'yoginām api sarveṣāṃ madgatenāntarātmanā |
śraddhāvān bhajate yo māṃ sa me yuktatamo mataḥ ||', null, null),
  ('gita', 7, 1, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'मय्यासक्तमनाः पार्थ योगं युञ्जन्मदाश्रयः ।
असंशयं समग्रं मां यथा ज्ञास्यसि तच्छृणु ॥', 'mayy āsaktamanāḥ pārtha yogaṃ yuñjan madāśrayaḥ |
asaṃśayaṃ samagraṃ māṃ yathā jñāsyasi tac chṛṇu ||', null, null),
  ('gita', 7, 2, null, null, 'ज्ञानं तेऽहं सविज्ञानमिदं वक्ष्याम्यशेषतः ।
यज्ज्ञात्वा नेह भूयोऽन्यज्ज्ञातव्यमवशिष्यते ॥', 'jñānaṃ te ''haṃ savijñānam idaṃ vakṣyāmy aśeṣataḥ |
yaj jñātvā neha bhūyo ''nyaj jñātavyam avaśiṣyate ||', null, null),
  ('gita', 7, 3, null, null, 'मनुष्याणां सहस्रेषु कश्चिद्यतति सिद्धये ।
यततामपि सिद्धानां कश्चिन्मां वेत्ति तत्त्वतः ॥', 'manuṣyāṇāṃ sahasreṣu kaś cid yatati siddhaye |
yatatām api siddhānāṃ kaś cin māṃ vetti tattvataḥ ||', null, null),
  ('gita', 7, 4, null, null, 'भूमिरापोऽनलो वायुः खं मनो बुद्धिरेव च ।
अहंकार इतीयं मे भिन्ना प्रकृतिरष्टधा ॥', 'bhūmir āpo ''nalo vāyuḥ khaṃ mano buddhir eva ca |
ahaṃkāra itīyaṃ me bhinnā prakṛtir aṣṭadhā ||', null, null),
  ('gita', 7, 5, null, null, 'अपरेयमितस्त्वन्यां प्रकृतिं विद्धि मे पराम् ।
जीवभूतां महाबाहो ययेदं धार्यते जगत् ॥', 'apareyam itas tv anyāṃ prakṛtiṃ viddhi me parām |
jīvabhūtāṃ mahābāho yayedaṃ dhāryate jagat ||', null, null),
  ('gita', 7, 6, null, null, 'एतद्योनीनि भूतानि सर्वाणीत्युपधारय ।
अहं कृत्स्नस्य जगतः प्रभवः प्रलयस्तथा ॥', 'etadyonīni bhūtāni sarvāṇīty upadhāraya |
ahaṃ kṛtsnasya jagataḥ prabhavaḥ pralayas tathā ||', null, null),
  ('gita', 7, 7, null, null, 'मत्तः परतरं नान्यत्किं चिदस्ति धनंजय ।
मयि सर्वमिदं प्रोतं सूत्रे मणिगणा इव ॥', 'mattaḥ parataraṃ nānyat kiṃ cid asti dhanaṃjaya |
mayi sarvam idaṃ protaṃ sūtre maṇigaṇā iva ||', null, null),
  ('gita', 7, 8, null, null, 'रसोऽहमप्सु कौन्तेय प्रभास्मि शशिसूर्ययोः ।
प्रणवः सर्ववेदेषु शब्दः खे पौरुषं नृषु ॥', 'raso ''ham apsu kaunteya prabhāsmi śaśisūryayoḥ |
praṇavaḥ sarvavedeṣu śabdaḥ khe pauruṣaṃ nṛṣu ||', null, null),
  ('gita', 7, 9, null, null, 'पुण्यो गन्धः पृथिव्यां च तेजश्चास्मि विभावसौ ।
जीवनं सर्वभूतेषु तपश्चास्मि तपस्विषु ॥', 'puṇyo gandhaḥ pṛthivyāṃ ca tejaś cāsmi vibhāvasau |
jīvanaṃ sarvabhūteṣu tapaś cāsmi tapasviṣu ||', null, null),
  ('gita', 7, 10, null, null, 'बीजं मां सर्वभूतानां विद्धि पार्थ सनातनम् ।
बुद्धिर्बुद्धिमतामस्मि तेजस्तेजस्विनामहम् ॥', 'bījaṃ māṃ sarvabhūtānāṃ viddhi pārtha sanātanam |
buddhir buddhimatām asmi tejas tejasvinām aham ||', null, null),
  ('gita', 7, 11, null, null, 'बलं बलवतां चाहं कामरागविवर्जितम् ।
धर्माविरुद्धो भूतेषु कामोऽस्मि भरतर्षभ ॥', 'balaṃ balavatāṃ cāhaṃ kāmarāgavivarjitam |
dharmāviruddho bhūteṣu kāmo ''smi bharatarṣabha ||', null, null),
  ('gita', 7, 12, null, null, 'ये चैव सात्त्विका भावा राजसास्तामसाश्च ये ।
मत्त एवेति तान्विद्धि न त्वहं तेषु ते मयि ॥', 'ye caiva sāttvikā bhāvā rājasās tāmasāś ca ye |
matta eveti tān viddhi na tv ahaṃ teṣu te mayi ||', null, null),
  ('gita', 7, 13, null, null, 'त्रिभिर्गुणमयैर्भावैरेभिः सर्वमिदं जगत् ।
मोहितं नाभिजानाति मामेभ्यः परमव्ययम् ॥', 'tribhir guṇamayair bhāvair ebhiḥ sarvam idaṃ jagat |
mohitaṃ nābhijānāti mām ebhyaḥ param avyayam ||', null, null),
  ('gita', 7, 14, null, null, 'दैवी ह्येषा गुणमयी मम माया दुरत्यया ।
मामेव ये प्रपद्यन्ते मायामेतां तरन्ति ते ॥', 'daivī hy eṣā guṇamayī mama māyā duratyayā |
mām eva ye prapadyante māyām etāṃ taranti te ||', null, null),
  ('gita', 7, 15, null, null, 'न मां दुष्कृतिनो मूढाः प्रपद्यन्ते नराधमाः ।
माययापहृतज्ञाना आसुरं भावमाश्रिताः ॥', 'na māṃ duṣkṛtino mūḍhāḥ prapadyante narādhamāḥ |
māyayāpahṛtajñānā āsuraṃ bhāvam āśritāḥ ||', null, null),
  ('gita', 7, 16, null, null, 'चतुर्विधा भजन्ते मां जनाः सुकृतिनोऽर्जुन ।
आर्तो जिज्ञासुरर्थार्थी ज्ञानी च भरतर्षभ ॥', 'caturvidhā bhajante māṃ janāḥ sukṛtino ''rjuna |
ārto jijñāsur arthārthī jñānī ca bharatarṣabha ||', null, null),
  ('gita', 7, 17, null, null, 'तेषां ज्ञानी नित्ययुक्त एकभक्तिर्विशिष्यते ।
प्रियो हि ज्ञानिनोऽत्यर्थमहं स च मम प्रियः ॥', 'teṣāṃ jñānī nityayukta ekabhaktir viśiṣyate |
priyo hi jñānino ''tyartham ahaṃ sa ca mama priyaḥ ||', null, null),
  ('gita', 7, 18, null, null, 'उदाराः सर्व एवैते ज्ञानी त्वात्मैव मे मतम् ।
आस्थितः स हि युक्तात्मा मामेवानुत्तमां गतिम् ॥', 'udārāḥ sarva evaite jñānī tv ātmaiva me matam |
āsthitaḥ sa hi yuktātmā mām evānuttamāṃ gatim ||', null, null),
  ('gita', 7, 19, null, null, 'बहूनां जन्मनामन्ते ज्ञानवान्मां प्रपद्यते ।
वासुदेवः सर्वमिति स महात्मा सुदुर्लभः ॥', 'bahūnāṃ janmanām ante jñānavān māṃ prapadyate |
vāsudevaḥ sarvam iti sa mahātmā sudurlabhaḥ ||', null, null),
  ('gita', 7, 20, null, null, 'कामैस्तैस्तैर्हृतज्ञानाः प्रपद्यन्तेऽन्यदेवताः ।
तं तं नियममास्थाय प्रकृत्या नियताः स्वया ॥', 'kāmais tais tair hṛtajñānāḥ prapadyante ''nyadevatāḥ |
taṃ taṃ niyamam āsthāya prakṛtyā niyatāḥ svayā ||', null, null),
  ('gita', 7, 21, null, null, 'यो यो यां यां तनुं भक्तः श्रद्धयार्चितुमिच्छति ।
तस्य तस्याचलां श्रद्धां तामेव विदधाम्यहम् ॥', 'yo yo yāṃ yāṃ tanuṃ bhaktaḥ śraddhayārcitum icchati |
tasya tasyācalāṃ śraddhāṃ tām eva vidadhāmy aham ||', null, null),
  ('gita', 7, 22, null, null, 'स तया श्रद्धया युक्तस्तस्या राधनमीहते ।
लभते च ततः कामान्मयैव विहितान्हि तान् ॥', 'sa tayā śraddhayā yuktas tasyā rādhanam īhate |
labhate ca tataḥ kāmān mayaiva vihitān hi tān ||', null, null),
  ('gita', 7, 23, null, null, 'अन्तवत्तु फलं तेषां तद्भवत्यल्पमेधसाम् ।
देवान्देवयजो यान्ति मद्भक्ता यान्ति मामपि ॥', 'antavat tu phalaṃ teṣāṃ tad bhavaty alpamedhasām |
devān devayajo yānti madbhaktā yānti mām api ||', null, null),
  ('gita', 7, 24, null, null, 'अव्यक्तं व्यक्तिमापन्नं मन्यन्ते मामबुद्धयः ।
परं भावमजानन्तो ममाव्ययमनुत्तमम् ॥', 'avyaktaṃ vyaktim āpannaṃ manyante mām abuddhayaḥ |
paraṃ bhāvam ajānanto mamāvyayam anuttamam ||', null, null),
  ('gita', 7, 25, null, null, 'नाहं प्रकाशः सर्वस्य योगमायासमावृतः ।
मूढोऽयं नाभिजानाति लोको मामजमव्ययम् ॥', 'nāhaṃ prakāśaḥ sarvasya yogamāyāsamāvṛtaḥ |
mūḍho ''yaṃ nābhijānāti loko mām ajam avyayam ||', null, null),
  ('gita', 7, 26, null, null, 'वेदाहं समतीतानि वर्तमानानि चार्जुन ।
भविष्याणि च भूतानि मां तु वेद न कश्चन ॥', 'vedāhaṃ samatītāni vartamānāni cārjuna |
bhaviṣyāṇi ca bhūtāni māṃ tu veda na kaś cana ||', null, null),
  ('gita', 7, 27, null, null, 'इच्छाद्वेषसमुत्थेन द्वन्द्वमोहेन भारत ।
सर्वभूतानि संमोहं सर्गे यान्ति परंतप ॥', 'icchādveṣasamutthena dvandvamohena bhārata |
sarvabhūtāni saṃmohaṃ sarge yānti paraṃtapa ||', null, null),
  ('gita', 7, 28, null, null, 'येषां त्वन्तगतं पापं जनानां पुण्यकर्मणाम् ।
ते द्वन्द्वमोहनिर्मुक्ता भजन्ते मां दृढव्रताः ॥', 'yeṣāṃ tv antagataṃ pāpaṃ janānāṃ puṇyakarmaṇām |
te dvandvamohanirmuktā bhajante māṃ dṛḍhavratāḥ ||', null, null),
  ('gita', 7, 29, null, null, 'जरामरणमोक्षाय मामाश्रित्य यतन्ति ये ।
ते ब्रह्म तद्विदुः कृत्स्नमध्यात्मं कर्म चाखिलम् ॥', 'jarāmaraṇamokṣāya mām āśritya yatanti ye |
te brahma tad viduḥ kṛtsnam adhyātmaṃ karma cākhilam ||', null, null),
  ('gita', 7, 30, null, null, 'साधिभूताधिदैवं मां साधियज्ञं च ये विदुः ।
प्रयाणकालेऽपि च मां ते विदुर्युक्तचेतसः ॥', 'sādhibhūtādhidaivaṃ māṃ sādhiyajñaṃ ca ye viduḥ |
prayāṇakāle ''pi ca māṃ te vidur yuktacetasaḥ ||', null, null),
  ('gita', 8, 1, 'अर्जुन उवाच', 'arjuna uvāca', 'किं तद्ब्रह्म किमध्यात्मं किं कर्म पुरुषोत्तम ।
अधिभूतं च किं प्रोक्तमधिदैवं किमुच्यते ॥', 'kiṃ tad brahma kim adhyātmaṃ kiṃ karma puruṣottama |
adhibhūtaṃ ca kiṃ proktam adhidaivaṃ kim ucyate ||', null, null),
  ('gita', 8, 2, null, null, 'अधियज्ञः कथं कोऽत्र देहेऽस्मिन्मधुसूदन ।
प्रयाणकाले च कथं ज्ञेयोऽसि नियतात्मभिः ॥', 'adhiyajñaḥ kathaṃ ko ''tra dehe ''smin madhusūdana |
prayāṇakāle ca kathaṃ jñeyo ''si niyatātmabhiḥ ||', null, null),
  ('gita', 8, 3, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'अक्षरं ब्रह्म परमं स्वभावोऽध्यात्ममुच्यते ।
भूतभावोद्भवकरो विसर्गः कर्मसंज्ञितः ॥', 'akṣaraṃ brahma paramaṃ svabhāvo ''dhyātmam ucyate |
bhūtabhāvodbhavakaro visargaḥ karmasaṃjñitaḥ ||', null, null),
  ('gita', 8, 4, null, null, 'अधिभूतं क्षरो भावः पुरुषश्चाधिदैवतम् ।
अधियज्ञोऽहमेवात्र देहे देहभृतां वर ॥', 'adhibhūtaṃ kṣaro bhāvaḥ puruṣaś cādhidaivatam |
adhiyajño ''ham evātra dehe dehabhṛtāṃ vara ||', null, null),
  ('gita', 8, 5, null, null, 'अन्तकाले च मामेव स्मरन्मुक्त्वा कलेवरम् ।
यः प्रयाति स मद्भावं याति नास्त्यत्र संशयः ॥', 'antakāle ca mām eva smaran muktvā kalevaram |
yaḥ prayāti sa madbhāvaṃ yāti nāsty atra saṃśayaḥ ||', null, null),
  ('gita', 8, 6, null, null, 'यं यं वापि स्मरन्भावं त्यजत्यन्ते कलेवरम् ।
तं तमेवैति कौन्तेय सदा तद्भावभावितः ॥', 'yaṃ yaṃ vāpi smaran bhāvaṃ tyajaty ante kalevaram |
taṃ tam evaiti kaunteya sadā tadbhāvabhāvitaḥ ||', null, null),
  ('gita', 8, 7, null, null, 'तस्मात्सर्वेषु कालेषु मामनुस्मर युध्य च ।
मय्यर्पितमनोबुद्धिर्मामेवैष्यस्यसंशयः ॥', 'tasmāt sarveṣu kāleṣu mām anusmara yudhya ca |
mayy arpitamanobuddhir mām evaiṣyasy asaṃśayaḥ ||', null, null),
  ('gita', 8, 8, null, null, 'अभ्यासयोगयुक्तेन चेतसा नान्यगामिना ।
परमं पुरुषं दिव्यं याति पार्थानुचिन्तयन् ॥', 'abhyāsayogayuktena cetasā nānyagāminā |
paramaṃ puruṣaṃ divyaṃ yāti pārthānucintayan ||', null, null),
  ('gita', 8, 9, null, null, 'कविं पुराणमनुशासितारमणोरणीयांसमनुस्मरेद्यः ।
सर्वस्य धातारमचिन्त्यरूपमादित्यवर्णं तमसः परस्तात् ॥', 'kaviṃ purāṇam anuśāsitāram aṇor aṇīyāṃsam anusmared yaḥ |
sarvasya dhātāram acintyarūpam ādityavarṇaṃ tamasaḥ parastāt ||', null, null),
  ('gita', 8, 10, null, null, 'प्रयाणकाले मनसाचलेन भक्त्या युक्तो योगबलेन चैव ।
भ्रुवोर्मध्ये प्राणमावेश्य सम्यक्स तं परं पुरुषमुपैति दिव्यम् ॥', 'prayāṇakāle manasācalena bhaktyā yukto yogabalena caiva |
bhruvor madhye prāṇam āveśya samyak sa taṃ paraṃ puruṣam upaiti divyam ||', null, null),
  ('gita', 8, 11, null, null, 'यदक्षरं वेदविदो वदन्ति विशन्ति यद्यतयो वीतरागाः ।
यदिच्छन्तो ब्रह्मचर्यं चरन्ति तत्ते पदं संग्रहेण प्रवक्ष्ये ॥', 'yad akṣaraṃ vedavido vadanti viśanti yad yatayo vītarāgāḥ |
yad icchanto brahmacaryaṃ caranti tat te padaṃ saṃgraheṇa pravakṣye ||', null, null),
  ('gita', 8, 12, null, null, 'सर्वद्वाराणि संयम्य मनो हृदि निरुध्य च ।
मूर्ध्न्याधायात्मनः प्राणमास्थितो योगधारणाम् ॥', 'sarvadvārāṇi saṃyamya mano hṛdi nirudhya ca |
mūrdhny ādhāyātmanaḥ prāṇam āsthito yogadhāraṇām ||', null, null),
  ('gita', 8, 13, null, null, 'ओमित्येकाक्षरं ब्रह्म व्याहरन्मामनुस्मरन् ।
यः प्रयाति त्यजन्देहं स याति परमां गतिम् ॥', 'om ity ekākṣaraṃ brahma vyāharan mām anusmaran |
yaḥ prayāti tyajan dehaṃ sa yāti paramāṃ gatim ||', null, null),
  ('gita', 8, 14, null, null, 'अनन्यचेताः सततं यो मां स्मरति नित्यशः ।
तस्याहं सुलभः पार्थ नित्ययुक्तस्य योगिनः ॥', 'ananyacetāḥ satataṃ yo māṃ smarati nityaśaḥ |
tasyāhaṃ sulabhaḥ pārtha nityayuktasya yoginaḥ ||', null, null),
  ('gita', 8, 15, null, null, 'मामुपेत्य पुनर्जन्म दुःखालयमशाश्वतम् ।
नाप्नुवन्ति महात्मानः संसिद्धिं परमां गताः ॥', 'mām upetya punarjanma duḥkhālayam aśāśvatam |
nāpnuvanti mahātmānaḥ saṃsiddhiṃ paramāṃ gatāḥ ||', null, null),
  ('gita', 8, 16, null, null, 'आ ब्रह्मभुवनाल्लोकाः पुनरावर्तिनोऽर्जुन ।
मामुपेत्य तु कौन्तेय पुनर्जन्म न विद्यते ॥', 'ā brahmabhuvanāl lokāḥ punarāvartino ''rjuna |
mām upetya tu kaunteya punarjanma na vidyate ||', null, null),
  ('gita', 8, 17, null, null, 'सहस्रयुगपर्यन्तमहर्यद्ब्रह्मणो विदुः ।
रात्रिं युगसहस्रान्तां तेऽहोरात्रविदो जनाः ॥', 'sahasrayugaparyantam ahar yad brahmaṇo viduḥ |
rātriṃ yugasahasrāntāṃ te ''horātravido janāḥ ||', null, null),
  ('gita', 8, 18, null, null, 'अव्यक्ताद्व्यक्तयः सर्वाः प्रभवन्त्यहरागमे ।
रात्र्यागमे प्रलीयन्ते तत्रैवाव्यक्तसंज्ञके ॥', 'avyaktād vyaktayaḥ sarvāḥ prabhavanty aharāgame |
rātryāgame pralīyante tatraivāvyaktasaṃjñake ||', null, null),
  ('gita', 8, 19, null, null, 'भूतग्रामः स एवायं भूत्वा भूत्वा प्रलीयते ।
रात्र्यागमेऽवशः पार्थ प्रभवत्यहरागमे ॥', 'bhūtagrāmaḥ sa evāyaṃ bhūtvā bhūtvā pralīyate |
rātryāgame ''vaśaḥ pārtha prabhavaty aharāgame ||', null, null),
  ('gita', 8, 20, null, null, 'परस्तस्मात्तु भावोऽन्योऽव्यक्तोऽव्यक्तात्सनातनः ।
यः स सर्वेषु भूतेषु नश्यत्सु न विनश्यति ॥', 'paras tasmāt tu bhāvo ''nyo ''vyakto ''vyaktāt sanātanaḥ |
yaḥ sa sarveṣu bhūteṣu naśyatsu na vinaśyati ||', null, null),
  ('gita', 8, 21, null, null, 'अव्यक्तोऽक्षर इत्युक्तस्तमाहुः परमां गतिम् ।
यं प्राप्य न निवर्तन्ते तद्धाम परमं मम ॥', 'avyakto ''kṣara ity uktas tam āhuḥ paramāṃ gatim |
yaṃ prāpya na nivartante tad dhāma paramaṃ mama ||', null, null),
  ('gita', 8, 22, null, null, 'पुरुषः स परः पार्थ भक्त्या लभ्यस्त्वनन्यया ।
यस्यान्तःस्थानि भूतानि येन सर्वमिदं ततम् ॥', 'puruṣaḥ sa paraḥ pārtha bhaktyā labhyas tv ananyayā |
yasyāntaḥsthāni bhūtāni yena sarvam idaṃ tatam ||', null, null),
  ('gita', 8, 23, null, null, 'यत्र काले त्वनावृत्तिमावृत्तिं चैव योगिनः ।
प्रयाता यान्ति तं कालं वक्ष्यामि भरतर्षभ ॥', 'yatra kāle tv anāvṛttim āvṛttiṃ caiva yoginaḥ |
prayātā yānti taṃ kālaṃ vakṣyāmi bharatarṣabha ||', null, null),
  ('gita', 8, 24, null, null, 'अग्निर्ज्योतिरहः शुक्लः षण्मासा उत्तरायणम् ।
तत्र प्रयाता गच्छन्ति ब्रह्म ब्रह्मविदो जनाः ॥', 'agnir jyotir ahaḥ śuklaḥ ṣaṇmāsā uttarāyaṇam |
tatra prayātā gacchanti brahma brahmavido janāḥ ||', null, null),
  ('gita', 8, 25, null, null, 'धूमो रात्रिस्तथा कृष्णः षण्मासा दक्षिणायनम् ।
तत्र चान्द्रमसं ज्योतिर्योगी प्राप्य निवर्तते ॥', 'dhūmo rātris tathā kṛṣṇaḥ ṣaṇmāsā dakṣiṇāyanam |
tatra cāndramasaṃ jyotir yogī prāpya nivartate ||', null, null),
  ('gita', 8, 26, null, null, 'शुक्लकृष्णे गती ह्येते जगतः शाश्वते मते ।
एकया यात्यनावृत्तिमन्ययावर्तते पुनः ॥', 'śuklakṛṣṇe gatī hy ete jagataḥ śāśvate mate |
ekayā yāty anāvṛttim anyayāvartate punaḥ ||', null, null),
  ('gita', 8, 27, null, null, 'नैते सृती पार्थ जानन्योगी मुह्यति कश्चन ।
तस्मात्सर्वेषु कालेषु योगयुक्तो भवार्जुन ॥', 'naite sṛtī pārtha jānan yogī muhyati kaś cana |
tasmāt sarveṣu kāleṣu yogayukto bhavārjuna ||', null, null),
  ('gita', 8, 28, null, null, 'वेदेषु यज्ञेषु तपःसु चैव दानेषु यत्पुण्यफलं प्रदिष्टम् ।
अत्येति तत्सर्वमिदं विदित्वा योगी परं स्थानमुपैति चाद्यम् ॥', 'vedeṣu yajñeṣu tapaḥsu caiva dāneṣu yat puṇyaphalaṃ pradiṣṭam |
atyeti tat sarvam idaṃ viditvā yogī paraṃ sthānam upaiti cādyam ||', null, null),
  ('gita', 9, 1, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'इदं तु ते गुह्यतमं प्रवक्ष्याम्यनसूयवे ।
ज्ञानं विज्ञानसहितं यज्ज्ञात्वा मोक्ष्यसेऽशुभात् ॥', 'idaṃ tu te guhyatamaṃ pravakṣyāmy anasūyave |
jñānaṃ vijñānasahitaṃ yaj jñātvā mokṣyase ''śubhāt ||', null, null),
  ('gita', 9, 2, null, null, 'राजविद्या राजगुह्यं पवित्रमिदमुत्तमम् ।
प्रत्यक्षावगमं धर्म्यं सुसुखं कर्तुमव्ययम् ॥', 'rājavidyā rājaguhyaṃ pavitram idam uttamam |
pratyakṣāvagamaṃ dharmyaṃ susukhaṃ kartum avyayam ||', null, null),
  ('gita', 9, 3, null, null, 'अश्रद्दधानाः पुरुषा धर्मस्यास्य परंतप ।
अप्राप्य मां निवर्तन्ते मृत्युसंसारवर्त्मनि ॥', 'aśraddadhānāḥ puruṣā dharmasyāsya paraṃtapa |
aprāpya māṃ nivartante mṛtyusaṃsāravartmani ||', null, null),
  ('gita', 9, 4, null, null, 'मया ततमिदं सर्वं जगदव्यक्तमूर्तिना ।
मत्स्थानि सर्वभूतानि न चाहं तेष्ववस्थितः ॥', 'mayā tatam idaṃ sarvaṃ jagad avyaktamūrtinā |
matsthāni sarvabhūtāni na cāhaṃ teṣv avasthitaḥ ||', null, null),
  ('gita', 9, 5, null, null, 'न च मत्स्थानि भूतानि पश्य मे योगमैश्वरम् ।
भूतभृन्न च भूतस्थो ममात्मा भूतभावनः ॥', 'na ca matsthāni bhūtāni paśya me yogam aiśvaram |
bhūtabhṛn na ca bhūtastho mamātmā bhūtabhāvanaḥ ||', null, null),
  ('gita', 9, 6, null, null, 'यथाकाशस्थितो नित्यं वायुः सर्वत्रगो महान् ।
तथा सर्वाणि भूतानि मत्स्थानीत्युपधारय ॥', 'yathākāśasthito nityaṃ vāyuḥ sarvatrago mahān |
tathā sarvāṇi bhūtāni matsthānīty upadhāraya ||', null, null),
  ('gita', 9, 7, null, null, 'सर्वभूतानि कौन्तेय प्रकृतिं यान्ति मामिकाम् ।
कल्पक्षये पुनस्तानि कल्पादौ विसृजाम्यहम् ॥', 'sarvabhūtāni kaunteya prakṛtiṃ yānti māmikām |
kalpakṣaye punas tāni kalpādau visṛjāmy aham ||', null, null),
  ('gita', 9, 8, null, null, 'प्रकृतिं स्वामवष्टभ्य विसृजामि पुनः पुनः ।
भूतग्राममिमं कृत्स्नमवशं प्रकृतेर्वशात् ॥', 'prakṛtiṃ svām avaṣṭabhya visṛjāmi punaḥ punaḥ |
bhūtagrāmam imaṃ kṛtsnam avaśaṃ prakṛter vaśāt ||', null, null),
  ('gita', 9, 9, null, null, 'न च मां तानि कर्माणि निबध्नन्ति धनंजय ।
उदासीनवदासीनमसक्तं तेषु कर्मसु ॥', 'na ca māṃ tāni karmāṇi nibadhnanti dhanaṃjaya |
udāsīnavad āsīnam asaktaṃ teṣu karmasu ||', null, null),
  ('gita', 9, 10, null, null, 'मयाध्यक्षेण प्रकृतिः सूयते सचराचरम् ।
हेतुनानेन कौन्तेय जगद्विपरिवर्तते ॥', 'mayādhyakṣeṇa prakṛtiḥ sūyate sacarācaram |
hetunānena kaunteya jagad viparivartate ||', null, null),
  ('gita', 9, 11, null, null, 'अवजानन्ति मां मूढा मानुषीं तनुमाश्रितम् ।
परं भावमजानन्तो मम भूतमहेश्वरम् ॥', 'avajānanti māṃ mūḍhā mānuṣīṃ tanum āśritam |
paraṃ bhāvam ajānanto mama bhūtamaheśvaram ||', null, null),
  ('gita', 9, 12, null, null, 'मोघाशा मोघकर्माणो मोघज्ञाना विचेतसः ।
राक्षसीमासुरीं चैव प्रकृतिं मोहिनीं श्रिताः ॥', 'moghāśā moghakarmāṇo moghajñānā vicetasaḥ |
rākṣasīm āsurīṃ caiva prakṛtiṃ mohinīṃ śritāḥ ||', null, null),
  ('gita', 9, 13, null, null, 'महात्मानस्तु मां पार्थ दैवीं प्रकृतिमाश्रिताः ।
भजन्त्यनन्यमनसो ज्ञात्वा भूतादिमव्ययम् ॥', 'mahātmānas tu māṃ pārtha daivīṃ prakṛtim āśritāḥ |
bhajanty ananyamanaso jñātvā bhūtādim avyayam ||', null, null),
  ('gita', 9, 14, null, null, 'सततं कीर्तयन्तो मां यतन्तश्च दृढव्रताः ।
नमस्यन्तश्च मां भक्त्या नित्ययुक्ता उपासते ॥', 'satataṃ kīrtayanto māṃ yatantaś ca dṛḍhavratāḥ |
namasyantaś ca māṃ bhaktyā nityayuktā upāsate ||', null, null),
  ('gita', 9, 15, null, null, 'ज्ञानयज्ञेन चाप्यन्ये यजन्तो मामुपासते ।
एकत्वेन पृथक्त्वेन बहुधा विश्वतोमुखम् ॥', 'jñānayajñena cāpy anye yajanto mām upāsate |
ekatvena pṛthaktvena bahudhā viśvatomukham ||', null, null),
  ('gita', 9, 16, null, null, 'अहं क्रतुरहं यज्ञः स्वधाहमहमौषधम् ।
मन्त्रोऽहमहमेवाज्यमहमग्निरहं हुतम् ॥', 'ahaṃ kratur ahaṃ yajñaḥ svadhāham aham auṣadham |
mantro ''ham aham evājyam aham agnir ahaṃ hutam ||', null, null),
  ('gita', 9, 17, null, null, 'पिताहमस्य जगतो माता धाता पितामहः ।
वेद्यं पवित्रमोङ्कार ऋक्साम यजुरेव च ॥', 'pitāham asya jagato mātā dhātā pitāmahaḥ |
vedyaṃ pavitram oṃkāra ṛk sāma yajur eva ca ||', null, null),
  ('gita', 9, 18, null, null, 'गतिर्भर्ता प्रभुः साक्षी निवासः शरणं सुहृत् ।
प्रभवः प्रलयः स्थानं निधानं बीजमव्ययम् ॥', 'gatir bhartā prabhuḥ sākṣī nivāsaḥ śaraṇaṃ suhṛt |
prabhavaḥ pralayaḥ sthānaṃ nidhānaṃ bījam avyayam ||', null, null),
  ('gita', 9, 19, null, null, 'तपाम्यहमहं वर्षं निगृह्णाम्युत्सृजामि च ।
अमृतं चैव मृत्युश्च सदसच्चाहमर्जुन ॥', 'tapāmy aham ahaṃ varṣaṃ nigṛhṇāmy utsṛjāmi ca |
amṛtaṃ caiva mṛtyuś ca sad asac cāham arjuna ||', null, null),
  ('gita', 9, 20, null, null, 'त्रैविद्या मां सोमपाः पूतपापा यज्ञैरिष्ट्वा स्वर्गतिं प्रार्थयन्ते ।
ते पुण्यमासाद्य सुरेन्द्रलोकमश्नन्ति दिव्यान्दिवि देवभोगान् ॥', 'traividyā māṃ somapāḥ pūtapāpā yajñair iṣṭvā svargatiṃ prārthayante |
te puṇyam āsādya surendralokam aśnanti divyān divi devabhogān ||', null, null),
  ('gita', 9, 21, null, null, 'ते तं भुक्त्वा स्वर्गलोकं विशालं क्षीणे पुण्ये मर्त्यलोकं विशन्ति ।
एवं त्रयीधर्ममनुप्रपन्ना गतागतं कामकामा लभन्ते ॥', 'te taṃ bhuktvā svargalokaṃ viśālaṃ kṣīṇe puṇye martyalokaṃ viśanti |
evaṃ trayīdharmam anuprapannā gatāgataṃ kāmakāmā labhante ||', null, null),
  ('gita', 9, 22, null, null, 'अनन्याश्चिन्तयन्तो मां ये जनाः पर्युपासते ।
तेषां नित्याभियुक्तानां योगक्षेमं वहाम्यहम् ॥', 'ananyāś cintayanto māṃ ye janāḥ paryupāsate |
teṣāṃ nityābhiyuktānāṃ yogakṣemaṃ vahāmy aham ||', null, null),
  ('gita', 9, 23, null, null, 'येऽप्यन्यदेवताभक्ता यजन्ते श्रद्धयान्विताः ।
तेऽपि मामेव कौन्तेय यजन्त्यविधिपूर्वकम् ॥', 'ye ''py anyadevatābhaktā yajante śraddhayānvitāḥ |
te ''pi mām eva kaunteya yajanty avidhipūrvakam ||', null, null),
  ('gita', 9, 24, null, null, 'अहं हि सर्वयज्ञानां भोक्ता च प्रभुरेव च ।
न तु मामभिजानन्ति तत्त्वेनातश्च्यवन्ति ते ॥', 'ahaṃ hi sarvayajñānāṃ bhoktā ca prabhur eva ca |
na tu mām abhijānanti tattvenātaś cyavanti te ||', null, null),
  ('gita', 9, 25, null, null, 'यान्ति देवव्रता देवान्पितॄन्यान्ति पितृव्रताः ।
भूतानि यान्ति भूतेज्या यान्ति मद्याजिनोऽपि माम् ॥', 'yānti devavratā devān pitṝn yānti pitṛvratāḥ |
bhūtāni yānti bhūtejyā yānti madyājino ''pi mām ||', null, null),
  ('gita', 9, 26, null, null, 'पत्रं पुष्पं फलं तोयं यो मे भक्त्या प्रयच्छति ।
तदहं भक्त्युपहृतमश्नामि प्रयतात्मनः ॥', 'patraṃ puṣpaṃ phalaṃ toyaṃ yo me bhaktyā prayacchati |
tad ahaṃ bhaktyupahṛtam aśnāmi prayatātmanaḥ ||', null, null),
  ('gita', 9, 27, null, null, 'यत्करोषि यदश्नासि यज्जुहोषि ददासि यत् ।
यत्तपस्यसि कौन्तेय तत्कुरुष्व मदर्पणम् ॥', 'yat karoṣi yad aśnāsi yaj juhoṣi dadāsi yat |
yat tapasyasi kaunteya tat kuruṣva madarpaṇam ||', null, null),
  ('gita', 9, 28, null, null, 'शुभाशुभफलैरेवं मोक्ष्यसे कर्मबन्धनैः ।
संन्यासयोगयुक्तात्मा विमुक्तो मामुपैष्यसि ॥', 'śubhāśubhaphalair evaṃ mokṣyase karmabandhanaiḥ |
saṃnyāsayogayuktātmā vimukto mām upaiṣyasi ||', null, null),
  ('gita', 9, 29, null, null, 'समोऽहं सर्वभूतेषु न मे द्वेष्योऽस्ति न प्रियः ।
ये भजन्ति तु मां भक्त्या मयि ते तेषु चाप्यहम् ॥', 'samo ''haṃ sarvabhūteṣu na me dveṣyo ''sti na priyaḥ |
ye bhajanti tu māṃ bhaktyā mayi te teṣu cāpy aham ||', null, null),
  ('gita', 9, 30, null, null, 'अपि चेत्सुदुराचारो भजते मामनन्यभाक् ।
साधुरेव स मन्तव्यः सम्यग्व्यवसितो हि सः ॥', 'api cet sudurācāro bhajate mām ananyabhāk |
sādhur eva sa mantavyaḥ samyag vyavasito hi saḥ ||', null, null),
  ('gita', 9, 31, null, null, 'क्षिप्रं भवति धर्मात्मा शश्वच्छान्तिं निगच्छति ।
कौन्तेय प्रतिजानीहि न मे भक्तः प्रणश्यति ॥', 'kṣipraṃ bhavati dharmātmā śaśvacchāntiṃ nigacchati |
kaunteya pratijānīhi na me bhaktaḥ praṇaśyati ||', null, null),
  ('gita', 9, 32, null, null, 'मां हि पार्थ व्यपाश्रित्य येऽपि स्युः पापयोनयः ।
स्त्रियो वैश्यास्तथा शूद्रास्तेऽपि यान्ति परां गतिम् ॥', 'māṃ hi pārtha vyapāśritya ye ''pi syuḥ pāpayonayaḥ |
striyo vaiśyās tathā śūdrās te ''pi yānti parāṃ gatim ||', null, null),
  ('gita', 9, 33, null, null, 'किं पुनर्ब्राह्मणाः पुण्या भक्ता राजर्षयस्तथा ।
अनित्यमसुखं लोकमिमं प्राप्य भजस्व माम् ॥', 'kiṃ punar brāhmaṇāḥ puṇyā bhaktā rājarṣayas tathā |
anityam asukhaṃ lokam imaṃ prāpya bhajasva mām ||', null, null),
  ('gita', 9, 34, null, null, 'मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु ।
मामेवैष्यसि युक्त्वैवमात्मानं मत्परायणः ॥', 'manmanā bhava madbhakto madyājī māṃ namaskuru |
mām evaiṣyasi yuktvaivam ātmānaṃ matparāyaṇaḥ ||', null, null),
  ('gita', 10, 1, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'भूय एव महाबाहो शृणु मे परमं वचः ।
यत्तेऽहं प्रीयमाणाय वक्ष्यामि हितकाम्यया ॥', 'bhūya eva mahābāho śṛṇu me paramaṃ vacaḥ |
yat te ''haṃ prīyamāṇāya vakṣyāmi hitakāmyayā ||', null, null),
  ('gita', 10, 2, null, null, 'न मे विदुः सुरगणाः प्रभवं न महर्षयः ।
अहमादिर्हि देवानां महर्षीणां च सर्वशः ॥', 'na me viduḥ suragaṇāḥ prabhavaṃ na maharṣayaḥ |
aham ādir hi devānāṃ maharṣīṇāṃ ca sarvaśaḥ ||', null, null),
  ('gita', 10, 3, null, null, 'यो मामजमनादिं च वेत्ति लोकमहेश्वरम् ।
असंमूढः स मर्त्येषु सर्वपापैः प्रमुच्यते ॥', 'yo mām ajam anādiṃ ca vetti lokamaheśvaram |
asaṃmūḍhaḥ sa martyeṣu sarvapāpaiḥ pramucyate ||', null, null),
  ('gita', 10, 4, null, null, 'बुद्धिर्ज्ञानमसंमोहः क्षमा सत्यं दमः शमः ।
सुखं दुःखं भवोऽभावो भयं चाभयमेव च ॥', 'buddhir jñānam asaṃmohaḥ kṣamā satyaṃ damaḥ śamaḥ |
sukhaṃ duḥkhaṃ bhavo ''bhāvo bhayaṃ cābhayam eva ca ||', null, null),
  ('gita', 10, 5, null, null, 'अहिंसा समता तुष्टिस्तपो दानं यशोऽयशः ।
भवन्ति भावा भूतानां मत्त एव पृथग्विधाः ॥', 'ahiṃsā samatā tuṣṭis tapo dānaṃ yaśo ''yaśaḥ |
bhavanti bhāvā bhūtānāṃ matta eva pṛthagvidhāḥ ||', null, null),
  ('gita', 10, 6, null, null, 'महर्षयः सप्त पूर्वे चत्वारो मनवस्तथा ।
मद्भावा मानसा जाता येषां लोक इमाः प्रजाः ॥', 'maharṣayaḥ sapta pūrve catvāro manavas tathā |
madbhāvā mānasā jātā yeṣāṃ loka imāḥ prajāḥ ||', null, null),
  ('gita', 10, 7, null, null, 'एतां विभूतिं योगं च मम यो वेत्ति तत्त्वतः ।
सोऽविकम्पेन योगेन युज्यते नात्र संशयः ॥', 'etāṃ vibhūtiṃ yogaṃ ca mama yo vetti tattvataḥ |
so ''vikampena yogena yujyate nātra saṃśayaḥ ||', null, null),
  ('gita', 10, 8, null, null, 'अहं सर्वस्य प्रभवो मत्तः सर्वं प्रवर्तते ।
इति मत्वा भजन्ते मां बुधा भावसमन्विताः ॥', 'ahaṃ sarvasya prabhavo mattaḥ sarvaṃ pravartate |
iti matvā bhajante māṃ budhā bhāvasamanvitāḥ ||', null, null),
  ('gita', 10, 9, null, null, 'मच्चित्ता मद्गतप्राणा बोधयन्तः परस्परम् ।
कथयन्तश्च मां नित्यं तुष्यन्ति च रमन्ति च ॥', 'maccittā madgataprāṇā bodhayantaḥ parasparam |
kathayantaś ca māṃ nityaṃ tuṣyanti ca ramanti ca ||', null, null),
  ('gita', 10, 10, null, null, 'तेषां सततयुक्तानां भजतां प्रीतिपूर्वकम् ।
ददामि बुद्धियोगं तं येन मामुपयान्ति ते ॥', 'teṣāṃ satatayuktānāṃ bhajatāṃ prītipūrvakam |
dadāmi buddhiyogaṃ taṃ yena mām upayānti te ||', null, null),
  ('gita', 10, 11, null, null, 'तेषामेवानुकम्पार्थमहमज्ञानजं तमः ।
नाशयाम्यात्मभावस्थो ज्ञानदीपेन भास्वता ॥', 'teṣām evānukampārtham aham ajñānajaṃ tamaḥ |
nāśayāmy ātmabhāvastho jñānadīpena bhāsvatā ||', null, null),
  ('gita', 10, 12, 'अर्जुन उवाच', 'arjuna uvāca', 'परं ब्रह्म परं धाम पवित्रं परमं भवान् ।
पुरुषं शाश्वतं दिव्यमादिदेवमजं विभुम् ॥', 'paraṃ brahma paraṃ dhāma pavitraṃ paramaṃ bhavān |
puruṣaṃ śāśvataṃ divyam ādidevam ajaṃ vibhum ||', null, null),
  ('gita', 10, 13, null, null, 'आहुस्त्वामृषयः सर्वे देवर्षिर्नारदस्तथा ।
असितो देवलो व्यासः स्वयं चैव ब्रवीषि मे ॥', 'āhus tvām ṛṣayaḥ sarve devarṣir nāradas tathā |
asito devalo vyāsaḥ svayaṃ caiva bravīṣi me ||', null, null),
  ('gita', 10, 14, null, null, 'सर्वमेतदृतं मन्ये यन्मां वदसि केशव ।
न हि ते भगवन्व्यक्तिं विदुर्देवा न दानवाः ॥', 'sarvam etad ṛtaṃ manye yan māṃ vadasi keśava |
na hi te bhagavan vyaktiṃ vidur devā na dānavāḥ ||', null, null),
  ('gita', 10, 15, null, null, 'स्वयमेवात्मनात्मानं वेत्थ त्वं पुरुषोत्तम ।
भूतभावन भूतेश देवदेव जगत्पते ॥', 'svayam evātmanātmānaṃ vettha tvaṃ puruṣottama |
bhūtabhāvana bhūteśa devadeva jagatpate ||', null, null),
  ('gita', 10, 16, null, null, 'वक्तुमर्हस्यशेषेण दिव्या ह्यात्मविभूतयः ।
याभिर्विभूतिभिर्लोकानिमांस्त्वं व्याप्य तिष्ठसि ॥', 'vaktum arhasy aśeṣeṇa divyā hy ātmavibhūtayaḥ |
yābhir vibhūtibhir lokān imāṃs tvaṃ vyāpya tiṣṭhasi ||', null, null),
  ('gita', 10, 17, null, null, 'कथं विद्यामहं योगिंस्त्वां सदा परिचिन्तयन् ।
केषु केषु च भावेषु चिन्त्योऽसि भगवन्मया ॥', 'kathaṃ vidyām ahaṃ yogiṃs tvāṃ sadā paricintayan |
keṣu keṣu ca bhāveṣu cintyo ''si bhagavan mayā ||', null, null),
  ('gita', 10, 18, null, null, 'विस्तरेणात्मनो योगं विभूतिं च जनार्दन ।
भूयः कथय तृप्तिर्हि शृण्वतो नास्ति मेऽमृतम् ॥', 'vistareṇātmano yogaṃ vibhūtiṃ ca janārdana |
bhūyaḥ kathaya tṛptir hi śṛṇvato nāsti me ''mṛtam ||', null, null),
  ('gita', 10, 19, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'हन्त ते कथयिष्यामि दिव्या ह्यात्मविभूतयः ।
प्राधान्यतः कुरुश्रेष्ठ नास्त्यन्तो विस्तरस्य मे ॥', 'hanta te kathayiṣyāmi divyā hy ātmavibhūtayaḥ |
prādhānyataḥ kuruśreṣṭha nāsty anto vistarasya me ||', null, null),
  ('gita', 10, 20, null, null, 'अहमात्मा गुडाकेश सर्वभूताशयस्थितः ।
अहमादिश्च मध्यं च भूतानामन्त एव च ॥', 'aham ātmā guḍākeśa sarvabhūtāśayasthitaḥ |
aham ādiś ca madhyaṃ ca bhūtānām anta eva ca ||', null, null),
  ('gita', 10, 21, null, null, 'आदित्यानामहं विष्णुर्ज्योतिषां रविरंशुमान् ।
मरीचिर्मरुतामस्मि नक्षत्राणामहं शशी ॥', 'ādityānām ahaṃ viṣṇur jyotiṣāṃ ravir aṃśumān |
marīcir marutām asmi nakṣatrāṇām ahaṃ śaśī ||', null, null),
  ('gita', 10, 22, null, null, 'वेदानां सामवेदोऽस्मि देवानामस्मि वासवः ।
इन्द्रियाणां मनश्चास्मि भूतानामस्मि चेतना ॥', 'vedānāṃ sāmavedo ''smi devānām asmi vāsavaḥ |
indriyāṇāṃ manaś cāsmi bhūtānām asmi cetanā ||', null, null),
  ('gita', 10, 23, null, null, 'रुद्राणां शंकरश्चास्मि वित्तेशो यक्षरक्षसाम् ।
वसूनां पावकश्चास्मि मेरुः शिखरिणामहम् ॥', 'rudrāṇāṃ śaṃkaraś cāsmi vitteśo yakṣarakṣasām |
vasūnāṃ pāvakaś cāsmi meruḥ śikhariṇām aham ||', null, null),
  ('gita', 10, 24, null, null, 'पुरोधसां च मुख्यं मां विद्धि पार्थ बृहस्पतिम् ।
सेनानीनामहं स्कन्दः सरसामस्मि सागरः ॥', 'purodhasāṃ ca mukhyaṃ māṃ viddhi pārtha bṛhaspatim |
senānīnām ahaṃ skandaḥ sarasām asmi sāgaraḥ ||', null, null),
  ('gita', 10, 25, null, null, 'महर्षीणां भृगुरहं गिरामस्म्येकमक्षरम् ।
यज्ञानां जपयज्ञोऽस्मि स्थावराणां हिमालयः ॥', 'maharṣīṇāṃ bhṛgur ahaṃ girām asmy ekam akṣaram |
yajñānāṃ japayajño ''smi sthāvarāṇāṃ himālayaḥ ||', null, null),
  ('gita', 10, 26, null, null, 'अश्वत्थः सर्ववृक्षाणां देवर्षीणां च नारदः ।
गन्धर्वाणां चित्ररथः सिद्धानां कपिलो मुनिः ॥', 'aśvatthaḥ sarvavṛkṣāṇāṃ devarṣīṇāṃ ca nāradaḥ |
gandharvāṇāṃ citrarathaḥ siddhānāṃ kapilo muniḥ ||', null, null),
  ('gita', 10, 27, null, null, 'उच्चैःश्रवसमश्वानां विद्धि माममृतोद्भवम् ।
ऐरावतं गजेन्द्राणां नराणां च नराधिपम् ॥', 'uccaiḥśravasam aśvānāṃ viddhi mām amṛtodbhavam |
airāvataṃ gajendrāṇāṃ narāṇāṃ ca narādhipam ||', null, null),
  ('gita', 10, 28, null, null, 'आयुधानामहं वज्रं धेनूनामस्मि कामधुक् ।
प्रजनश्चास्मि कन्दर्पः सर्पाणामस्मि वासुकिः ॥', 'āyudhānām ahaṃ vajraṃ dhenūnām asmi kāmadhuk |
prajanaś cāsmi kandarpaḥ sarpāṇām asmi vāsukiḥ ||', null, null),
  ('gita', 10, 29, null, null, 'अनन्तश्चास्मि नागानां वरुणो यादसामहम् ।
पितॄणामर्यमा चास्मि यमः संयमतामहम् ॥', 'anantaś cāsmi nāgānāṃ varuṇo yādasām aham |
pitṝṇām aryamā cāsmi yamaḥ saṃyamatām aham ||', null, null),
  ('gita', 10, 30, null, null, 'प्रह्लादश्चास्मि दैत्यानां कालः कलयतामहम् ।
मृगाणां च मृगेन्द्रोऽहं वैनतेयश्च पक्षिणाम् ॥', 'prahlādaś cāsmi daityānāṃ kālaḥ kalayatām aham |
mṛgāṇāṃ ca mṛgendro ''haṃ vainateyaś ca pakṣiṇām ||', null, null),
  ('gita', 10, 31, null, null, 'पवनः पवतामस्मि रामः शस्त्रभृतामहम् ।
झषाणां मकरश्चास्मि स्रोतसामस्मि जाह्नवी ॥', 'pavanaḥ pavatām asmi rāmaḥ śastrabhṛtām aham |
jhaṣāṇāṃ makaraś cāsmi srotasām asmi jāhnavī ||', null, null),
  ('gita', 10, 32, null, null, 'सर्गाणामादिरन्तश्च मध्यं चैवाहमर्जुन ।
अध्यात्मविद्या विद्यानां वादः प्रवदतामहम् ॥', 'sargāṇām ādir antaś ca madhyaṃ caivāham arjuna |
adhyātmavidyā vidyānāṃ vādaḥ pravadatām aham ||', null, null),
  ('gita', 10, 33, null, null, 'अक्षराणामकारोऽस्मि द्वन्द्वः सामासिकस्य च ।
अहमेवाक्षयः कालो धाताहं विश्वतोमुखः ॥', 'akṣarāṇām akāro ''smi dvandvaḥ sāmāsikasya ca |
aham evākṣayaḥ kālo dhātāhaṃ viśvatomukhaḥ ||', null, null),
  ('gita', 10, 34, null, null, 'मृत्युः सर्वहरश्चाहमुद्भवश्च भविष्यताम् ।
कीर्तिः श्रीर्वाक्च नारीणां स्मृतिर्मेधा धृतिः क्षमा ॥', 'mṛtyuḥ sarvaharaś cāham udbhavaś ca bhaviṣyatām |
kīrtiḥ śrīr vāk ca nārīṇāṃ smṛtir medhā dhṛtiḥ kṣamā ||', null, null),
  ('gita', 10, 35, null, null, 'बृहत्साम तथा साम्नां गायत्री छन्दसामहम् ।
मासानां मार्गशीर्षोऽहमृतूनां कुसुमाकरः ॥', 'bṛhatsāma tathā sāmnāṃ gāyatrī chandasām aham |
māsānāṃ mārgaśīrṣo ''ham ṛtūnāṃ kusumākaraḥ ||', null, null),
  ('gita', 10, 36, null, null, 'द्यूतं छलयतामस्मि तेजस्तेजस्विनामहम् ।
जयोऽस्मि व्यवसायोऽस्मि सत्त्वं सत्त्ववतामहम् ॥', 'dyūtaṃ chalayatām asmi tejas tejasvinām aham |
jayo ''smi vyavasāyo ''smi sattvaṃ sattvavatām aham ||', null, null),
  ('gita', 10, 37, null, null, 'वृष्णीनां वासुदेवोऽस्मि पाण्डवानां धनंजयः ।
मुनीनामप्यहं व्यासः कवीनामुशना कविः ॥', 'vṛṣṇīnāṃ vāsudevo ''smi pāṇḍavānāṃ dhanaṃjayaḥ |
munīnām apy ahaṃ vyāsaḥ kavīnām uśanā kaviḥ ||', null, null),
  ('gita', 10, 38, null, null, 'दण्डो दमयतामस्मि नीतिरस्मि जिगीषताम् ।
मौनं चैवास्मि गुह्यानां ज्ञानं ज्ञानवतामहम् ॥', 'daṇḍo damayatām asmi nītir asmi jigīṣatām |
maunaṃ caivāsmi guhyānāṃ jñānaṃ jñānavatām aham ||', null, null),
  ('gita', 10, 39, null, null, 'यच्चापि सर्वभूतानां बीजं तदहमर्जुन ।
न तदस्ति विना यत्स्यान्मया भूतं चराचरम् ॥', 'yac cāpi sarvabhūtānāṃ bījaṃ tad aham arjuna |
na tad asti vinā yat syān mayā bhūtaṃ carācaram ||', null, null),
  ('gita', 10, 40, null, null, 'नान्तोऽस्ति मम दिव्यानां विभूतीनां परंतप ।
एष तूद्देशतः प्रोक्तो विभूतेर्विस्तरो मया ॥', 'nānto ''sti mama divyānāṃ vibhūtīnāṃ paraṃtapa |
eṣa tūddeśataḥ prokto vibhūter vistaro mayā ||', null, null),
  ('gita', 10, 41, null, null, 'यद्यद्विभूतिमत्सत्त्वं श्रीमदूर्जितमेव वा ।
तत्तदेवावगच्छ त्वं मम तेजोऽंशसंभवम् ॥', 'yad yad vibhūtimat sattvaṃ śrīmad ūrjitam eva vā |
tat tad evāvagaccha tvaṃ mama tejo ''ṃśasaṃbhavam ||', null, null),
  ('gita', 10, 42, null, null, 'अथ वा बहुनैतेन किं ज्ञातेन तवार्जुन ।
विष्टभ्याहमिदं कृत्स्नमेकांशेन स्थितो जगत् ॥', 'atha vā bahunaitena kiṃ jñātena tavārjuna |
viṣṭabhyāham idaṃ kṛtsnam ekāṃśena sthito jagat ||', null, null),
  ('gita', 11, 1, 'अर्जुन उवाच', 'arjuna uvāca', 'मदनुग्रहाय परमं गुह्यमध्यात्मसंज्ञितम् ।
यत्त्वयोक्तं वचस्तेन मोहोऽयं विगतो मम ॥', 'madanugrahāya paramaṃ guhyam adhyātmasaṃjñitam |
yat tvayoktaṃ vacas tena moho ''yaṃ vigato mama ||', null, null),
  ('gita', 11, 2, null, null, 'भवाप्ययौ हि भूतानां श्रुतौ विस्तरशो मया ।
त्वत्तः कमलपत्राक्ष माहात्म्यमपि चाव्ययम् ॥', 'bhavāpyayau hi bhūtānāṃ śrutau vistaraśo mayā |
tvattaḥ kamalapatrākṣa māhātmyam api cāvyayam ||', null, null),
  ('gita', 11, 3, null, null, 'एवमेतद्यथात्थ त्वमात्मानं परमेश्वर ।
द्रष्टुमिच्छामि ते रूपमैश्वरं पुरुषोत्तम ॥', 'evam etad yathāttha tvam ātmānaṃ parameśvara |
draṣṭum icchāmi te rūpam aiśvaraṃ puruṣottama ||', null, null),
  ('gita', 11, 4, null, null, 'मन्यसे यदि तच्छक्यं मया द्रष्टुमिति प्रभो ।
योगेश्वर ततो मे त्वं दर्शयात्मानमव्ययम् ॥', 'manyase yadi tac chakyaṃ mayā draṣṭum iti prabho |
yogeśvara tato me tvaṃ darśayātmānam avyayam ||', null, null),
  ('gita', 11, 5, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'पश्य मे पार्थ रूपाणि शतशोऽथ सहस्रशः ।
नानाविधानि दिव्यानि नानावर्णाकृतीनि च ॥', 'paśya me pārtha rūpāṇi śataśo ''tha sahasraśaḥ |
nānāvidhāni divyāni nānāvarṇākṛtīni ca ||', null, null),
  ('gita', 11, 6, null, null, 'पश्यादित्यान्वसून्रुद्रानश्विनौ मरुतस्तथा ।
बहून्यदृष्टपूर्वाणि पश्याश्चर्याणि भारत ॥', 'paśyādityān vasūn rudrān aśvinau marutas tathā |
bahūny adṛṣṭapūrvāṇi paśyāścaryāṇi bhārata ||', null, null),
  ('gita', 11, 7, null, null, 'इहैकस्थं जगत्कृत्स्नं पश्याद्य सचराचरम् ।
मम देहे गुडाकेश यच्चान्यद्द्रष्टुमिच्छसि ॥', 'ihaikasthaṃ jagat kṛtsnaṃ paśyādya sacarācaram |
mama dehe guḍākeśa yac cānyad draṣṭum icchasi ||', null, null),
  ('gita', 11, 8, null, null, 'न तु मां शक्यसे द्रष्टुमनेनैव स्वचक्षुषा ।
दिव्यं ददामि ते चक्षुः पश्य मे योगमैश्वरम् ॥', 'na tu māṃ śakyase draṣṭum anenaiva svacakṣuṣā |
divyaṃ dadāmi te cakṣuḥ paśya me yogam aiśvaram ||', null, null),
  ('gita', 11, 9, 'संजय उवाच', 'saṃjaya uvāca', 'एवमुक्त्वा ततो राजन्महायोगेश्वरो हरिः ।
दर्शयामास पार्थाय परमं रूपमैश्वरम् ॥', 'evam uktvā tato rājan mahāyogeśvaro hariḥ |
darśayām āsa pārthāya paramaṃ rūpam aiśvaram ||', null, null),
  ('gita', 11, 10, null, null, 'अनेकवक्त्रनयनमनेकाद्भुतदर्शनम् ।
अनेकदिव्याभरणं दिव्यानेकोद्यतायुधम् ॥', 'anekavaktranayanam anekādbhutadarśanam |
anekadivyābharaṇaṃ divyānekodyatāyudham ||', null, null),
  ('gita', 11, 11, null, null, 'दिव्यमाल्याम्बरधरं दिव्यगन्धानुलेपनम् ।
सर्वाश्चर्यमयं देवमनन्तं विश्वतोमुखम् ॥', 'divyamālyāmbaradharaṃ divyagandhānulepanam |
sarvāścaryamayaṃ devam anantaṃ viśvatomukham ||', null, null),
  ('gita', 11, 12, null, null, 'दिवि सूर्यसहस्रस्य भवेद्युगपदुत्थिता ।
यदि भाः सदृशी सा स्याद्भासस्तस्य महात्मनः ॥', 'divi sūryasahasrasya bhaved yugapad utthitā |
yadi bhāḥ sadṛśī sā syād bhāsas tasya mahātmanaḥ ||', null, null),
  ('gita', 11, 13, null, null, 'तत्रैकस्थं जगत्कृत्स्नं प्रविभक्तमनेकधा ।
अपश्यद्देवदेवस्य शरीरे पाण्डवस्तदा ॥', 'tatraikasthaṃ jagat kṛtsnaṃ pravibhaktam anekadhā |
apaśyad devadevasya śarīre pāṇḍavas tadā ||', null, null),
  ('gita', 11, 14, null, null, 'ततः स विस्मयाविष्टो हृष्टरोमा धनंजयः ।
प्रणम्य शिरसा देवं कृताञ्जलिरभाषत ॥', 'tataḥ sa vismayāviṣṭo hṛṣṭaromā dhanaṃjayaḥ |
praṇamya śirasā devaṃ kṛtāñjalir abhāṣata ||', null, null),
  ('gita', 11, 15, 'अर्जुन उवाच', 'arjuna uvāca', 'पश्यामि देवांस्तव देव देहे सर्वांस्तथा भूतविशेषसंघान् ।
ब्रह्माणमीशं कमलासनस्थमृषींश्च सर्वानुरगांश्च दिव्यान् ॥', 'paśyāmi devāṃs tava deva dehe sarvāṃs tathā bhūtaviśeṣasaṃghān |
brahmāṇam īśaṃ kamalāsanastham ṛṣīṃś ca sarvān uragāṃś ca divyān ||', null, null),
  ('gita', 11, 16, null, null, 'अनेकबाहूदरवक्त्रनेत्रं पश्यामि त्वा सर्वतोऽनन्तरूपम् ।
नान्तं न मध्यं न पुनस्तवादिं पश्यामि विश्वेश्वर विश्वरूप ॥', 'anekabāhūdaravaktranetraṃ paśyāmi tvā sarvato ''nantarūpam |
nāntaṃ na madhyaṃ na punas tavādiṃ paśyāmi viśveśvara viśvarūpa ||', null, null),
  ('gita', 11, 17, null, null, 'किरीटिनं गदिनं चक्रिणं च तेजोराशिं सर्वतो दीप्तिमन्तम् ।
पश्यामि त्वां दुर्निरीक्ष्यं समन्ताद्दीप्तानलार्कद्युतिमप्रमेयम् ॥', 'kirīṭinaṃ gadinaṃ cakriṇaṃ ca tejorāśiṃ sarvato dīptimantam |
paśyāmi tvāṃ durnirīkṣyaṃ samantād dīptānalārkadyutim aprameyam ||', null, null),
  ('gita', 11, 18, null, null, 'त्वमक्षरं परमं वेदितव्यं त्वमस्य विश्वस्य परं निधानम् ।
त्वमव्ययः शाश्वतधर्मगोप्ता सनातनस्त्वं पुरुषो मतो मे ॥', 'tvam akṣaraṃ paramaṃ veditavyaṃ tvam asya viśvasya paraṃ nidhānam |
tvam avyayaḥ śāśvatadharmagoptā sanātanas tvaṃ puruṣo mato me ||', null, null),
  ('gita', 11, 19, null, null, 'अनादिमध्यान्तमनन्तवीर्यमनन्तबाहुं शशिसूर्यनेत्रम् ।
पश्यामि त्वां दीप्तहुताशवक्त्रं स्वतेजसा विश्वमिदं तपन्तम् ॥', 'anādimadhyāntam anantavīryam anantabāhuṃ śaśisūryanetram |
paśyāmi tvāṃ dīptahutāśavaktraṃ svatejasā viśvam idaṃ tapantam ||', null, null),
  ('gita', 11, 20, null, null, 'द्यावापृथिव्योरिदमन्तरं हि व्याप्तं त्वयैकेन दिशश्च सर्वाः ।
दृष्ट्वाद्भुतं रूपमिदं तवोग्रं लोकत्रयं प्रव्यथितं महात्मन् ॥', 'dyāvāpṛthivyor idam antaraṃ hi vyāptaṃ tvayaikena diśaś ca sarvāḥ |
dṛṣṭvādbhutaṃ rūpam idaṃ tavograṃ lokatrayaṃ pravyathitaṃ mahātman ||', null, null),
  ('gita', 11, 21, null, null, 'अमी हि त्वा सुरसंघा विशन्ति के चिद्भीताः प्राञ्जलयो गृणन्ति ।
स्वस्तीत्युक्त्वा महर्षिसिद्धसंघाः स्तुवन्ति त्वां स्तुतिभिः पुष्कलाभिः ॥', 'amī hi tvā surasaṃghā viśanti ke cid bhītāḥ prāñjalayo gṛṇanti |
svastīty uktvā maharṣisiddhasaṃghāḥ stuvanti tvāṃ stutibhiḥ puṣkalābhiḥ ||', null, null),
  ('gita', 11, 22, null, null, 'रुद्रादित्या वसवो ये च साध्या विश्वेऽश्विनौ मरुतश्चोष्मपाश्च ।
गन्धर्वयक्षासुरसिद्धसंघा वीक्षन्ते त्वां विस्मिताश्चैव सर्वे ॥', 'rudrādityā vasavo ye ca sādhyā viśve ''śvinau marutaś coṣmapāś ca |
gandharvayakṣāsurasiddhasaṃghā vīkṣante tvāṃ vismitāś caiva sarve ||', null, null),
  ('gita', 11, 23, null, null, 'रूपं महत्ते बहुवक्त्रनेत्रं महाबाहो बहुबाहूरुपादम् ।
बहूदरं बहुदंष्ट्राकरालं दृष्ट्वा लोकाः प्रव्यथितास्तथाहम् ॥', 'rūpaṃ mahat te bahuvaktranetraṃ mahābāho bahubāhūrupādam |
bahūdaraṃ bahudaṃṣṭrākarālaṃ dṛṣṭvā lokāḥ pravyathitās tathāham ||', null, null),
  ('gita', 11, 24, null, null, 'नभःस्पृशं दीप्तमनेकवर्णं व्यात्ताननं दीप्तविशालनेत्रम् ।
दृष्ट्वा हि त्वां प्रव्यथितान्तरात्मा धृतिं न विन्दामि शमं च विष्णो ॥', 'nabhaḥspṛśaṃ dīptam anekavarṇaṃ vyāttānanaṃ dīptaviśālanetram |
dṛṣṭvā hi tvāṃ pravyathitāntarātmā dhṛtiṃ na vindāmi śamaṃ ca viṣṇo ||', null, null),
  ('gita', 11, 25, null, null, 'दंष्ट्राकरालानि च ते मुखानि दृष्ट्वैव कालानलसंनिभानि ।
दिशो न जाने न लभे च शर्म प्रसीद देवेश जगन्निवास ॥', 'daṃṣṭrākarālāni ca te mukhāni dṛṣṭvaiva kālānalasaṃnibhāni |
diśo na jāne na labhe ca śarma prasīda deveśa jagannivāsa ||', null, null),
  ('gita', 11, 26, null, null, 'अमी च त्वां धृतराष्ट्रस्य पुत्राः सर्वे सहैवावनिपालसंघैः ।
भीष्मो द्रोणः सूतपुत्रस्तथासौ सहास्मदीयैरपि योधमुख्यैः ॥', 'amī ca tvāṃ dhṛtarāṣṭrasya putrāḥ sarve sahaivāvanipālasaṃghaiḥ |
bhīṣmo droṇaḥ sūtaputras tathāsau sahāsmadīyair api yodhamukhyaiḥ ||', null, null),
  ('gita', 11, 27, null, null, 'वक्त्राणि ते त्वरमाणा विशन्ति दंष्ट्राकरालानि भयानकानि ।
के चिद्विलग्ना दशनान्तरेषु संदृश्यन्ते चूर्णितैरुत्तमाङ्गैः ॥', 'vaktrāṇi te tvaramāṇā viśanti daṃṣṭrākarālāni bhayānakāni |
ke cid vilagnā daśanāntareṣu saṃdṛśyante cūrṇitair uttamāṅgaiḥ ||', null, null),
  ('gita', 11, 28, null, null, 'यथा नदीनां बहवोऽम्बुवेगाः समुद्रमेवाभिमुखा द्रवन्ति ।
तथा तवामी नरलोकवीरा विशन्ति वक्त्राण्यभिविज्वलन्ति ॥', 'yathā nadīnāṃ bahavo ''mbuvegāḥ samudram evābhimukhā dravanti |
tathā tavāmī naralokavīrā viśanti vaktrāṇy abhivijvalanti ||', null, null),
  ('gita', 11, 29, null, null, 'यथा प्रदीप्तं ज्वलनं पतंगा विशन्ति नाशाय समृद्धवेगाः ।
तथैव नाशाय विशन्ति लोकास्तवापि वक्त्राणि समृद्धवेगाः ॥', 'yathā pradīptaṃ jvalanaṃ pataṃgā viśanti nāśāya samṛddhavegāḥ |
tathaiva nāśāya viśanti lokās tavāpi vaktrāṇi samṛddhavegāḥ ||', null, null),
  ('gita', 11, 30, null, null, 'लेलिह्यसे ग्रसमानः समन्ताल्लोकान्समग्रान्वदनैर्ज्वलद्भिः ।
तेजोभिरापूर्य जगत्समग्रं भासस्तवोग्राः प्रतपन्ति विष्णो ॥', 'lelihyase grasamānaḥ samantāl lokān samagrān vadanair jvaladbhiḥ |
tejobhir āpūrya jagat samagraṃ bhāsas tavogrāḥ pratapanti viṣṇo ||', null, null),
  ('gita', 11, 31, null, null, 'आख्याहि मे को भवानुग्ररूपो नमोऽस्तु ते देववर प्रसीद ।
विज्ञातुमिच्छामि भवन्तमाद्यं न हि प्रजानामि तव प्रवृत्तिम् ॥', 'ākhyāhi me ko bhavān ugrarūpo namo ''stu te devavara prasīda |
vijñātum icchāmi bhavantam ādyaṃ na hi prajānāmi tava pravṛttim ||', null, null),
  ('gita', 11, 32, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'कालोऽस्मि लोकक्षयकृत्प्रवृद्धो लोकान्समाहर्तुमिह प्रवृत्तः ।
ऋतेऽपि त्वा न भविष्यन्ति सर्वे येऽवस्थिताः प्रत्यनीकेषु योधाः ॥', 'kālo ''smi lokakṣayakṛt pravṛddho lokān samāhartum iha pravṛttaḥ |
ṛte ''pi tvā na bhaviṣyanti sarve ye ''vasthitāḥ pratyanīkeṣu yodhāḥ ||', null, null),
  ('gita', 11, 33, null, null, 'तस्मात्त्वमुत्तिष्ठ यशो लभस्व जित्वा शत्रून्भुङ्क्ष्व राज्यं समृद्धम् ।
मयैवैते निहताः पूर्वमेव निमित्तमात्रं भव सव्यसाचिन् ॥', 'tasmāt tvam uttiṣṭha yaśo labhasva jitvā śatrūn bhuṅkṣva rājyaṃ samṛddham |
mayaivaite nihatāḥ pūrvam eva nimittamātraṃ bhava savyasācin ||', null, null),
  ('gita', 11, 34, null, null, 'द्रोणं च भीष्मं च जयद्रथं च कर्णं तथान्यानपि योधवीरान् ।
मया हतांस्त्वं जहि मा व्यथिष्ठा युध्यस्व जेतासि रणे सपत्नान् ॥', 'droṇaṃ ca bhīṣmaṃ ca jayadrathaṃ ca karṇaṃ tathānyān api yodhavīrān |
mayā hatāṃs tvaṃ jahi mā vyathiṣṭhā yudhyasva jetāsi raṇe sapatnān ||', null, null),
  ('gita', 11, 35, 'संजय उवाच', 'saṃjaya uvāca', 'एतच्छ्रुत्वा वचनं केशवस्य कृताञ्जलिर्वेपमानः किरीटी ।
नमस्कृत्वा भूय एवाह कृष्णं सगद्गदं भीतभीतः प्रणम्य ॥', 'etac chrutvā vacanaṃ keśavasya kṛtāñjalir vepamānaḥ kirīṭī |
namaskṛtvā bhūya evāha kṛṣṇaṃ sagadgadaṃ bhītabhītaḥ praṇamya ||', null, null),
  ('gita', 11, 36, 'अर्जुन उवाच', 'arjuna uvāca', 'स्थाने हृषीकेश तव प्रकीर्त्या जगत्प्रहृष्यत्यनुरज्यते च ।
रक्षांसि भीतानि दिशो द्रवन्ति सर्वे नमस्यन्ति च सिद्धसंघाः ॥', 'sthāne hṛṣīkeśa tava prakīrtyā jagat prahṛṣyaty anurajyate ca |
rakṣāṃsi bhītāni diśo dravanti sarve namasyanti ca siddhasaṃghāḥ ||', null, null),
  ('gita', 11, 37, null, null, 'कस्माच्च ते न नमेरन्महात्मन्गरीयसे ब्रह्मणोऽप्यादिकर्त्रे ।
अनन्त देवेश जगन्निवास त्वमक्षरं सदसत्तत्परं यत् ॥', 'kasmāc ca te na nameran mahātman garīyase brahmaṇo ''py ādikartre |
ananta deveśa jagannivāsa tvam akṣaraṃ sad asat tatparaṃ yat ||', null, null),
  ('gita', 11, 38, null, null, 'त्वमादिदेवः पुरुषः पुराणस्त्वमस्य विश्वस्य परं निधानम् ।
वेत्तासि वेद्यं च परं च धाम त्वया ततं विश्वमनन्तरूप ॥', 'tvam ādidevaḥ puruṣaḥ purāṇas tvam asya viśvasya paraṃ nidhānam |
vettāsi vedyaṃ ca paraṃ ca dhāma tvayā tataṃ viśvam anantarūpa ||', null, null),
  ('gita', 11, 39, null, null, 'वायुर्यमोऽग्निर्वरुणः शशाङ्कः प्रजापतिस्त्वं प्रपितामहश्च ।
नमो नमस्तेऽस्तु सहस्रकृत्वः पुनश्च भूयोऽपि नमो नमस्ते ॥', 'vāyur yamo ''gnir varuṇaḥ śaśāṅkaḥ prajāpatis tvaṃ prapitāmahaś ca |
namo namas te ''stu sahasrakṛtvaḥ punaś ca bhūyo ''pi namo namas te ||', null, null),
  ('gita', 11, 40, null, null, 'नमः पुरस्तादथ पृष्ठतस्ते नमोऽस्तु ते सर्वत एव सर्व ।
अनन्तवीर्यामितविक्रमस्त्वं सर्वं समाप्नोषि ततोऽसि सर्वः ॥', 'namaḥ purastād atha pṛṣṭhatas te namo ''stu te sarvata eva sarva |
anantavīryāmitavikramas tvaṃ sarvaṃ samāpnoṣi tato ''si sarvaḥ ||', null, null),
  ('gita', 11, 41, null, null, 'सखेति मत्वा प्रसभं यदुक्तं हे कृष्ण हे यादव हे सखेति ।
अजानता महिमानं तवेदं मया प्रमादात्प्रणयेन वापि ॥', 'sakheti matvā prasabhaṃ yad uktaṃ he kṛṣṇa he yādava he sakheti |
ajānatā mahimānaṃ tavedaṃ mayā pramādāt praṇayena vāpi ||', null, null),
  ('gita', 11, 42, null, null, 'यच्चावहासार्थमसत्कृतोऽसि विहारशय्यासनभोजनेषु ।
एकोऽथ वाप्यच्युत तत्समक्षं तत्क्षामये त्वामहमप्रमेयम् ॥', 'yac cāvahāsārtham asatkṛto ''si vihāraśayyāsanabhojaneṣu |
eko ''tha vāpy acyuta tatsamakṣaṃ tat kṣāmaye tvām aham aprameyam ||', null, null),
  ('gita', 11, 43, null, null, 'पितासि लोकस्य चराचरस्य त्वमस्य पूज्यश्च गुरुर्गरीयान् ।
न त्वत्समोऽस्त्यभ्यधिकः कुतोऽन्यो लोकत्रयेऽप्यप्रतिमप्रभाव ॥', 'pitāsi lokasya carācarasya tvam asya pūjyaś ca gurur garīyān |
na tvatsamo ''sty abhyadhikaḥ kuto ''nyo lokatraye ''py apratimaprabhāva ||', null, null),
  ('gita', 11, 44, null, null, 'तस्मात्प्रणम्य प्रणिधाय कायं प्रसादये त्वामहमीशमीड्यम् ।
पितेव पुत्रस्य सखेव सख्युः प्रियः प्रियायार्हसि देव सोढुम् ॥', 'tasmāt praṇamya praṇidhāya kāyaṃ prasādaye tvām aham īśam īḍyam |
piteva putrasya sakheva sakhyuḥ priyaḥ priyāyārhasi deva soḍhum ||', null, null),
  ('gita', 11, 45, null, null, 'अदृष्टपूर्वं हृषितोऽस्मि दृष्ट्वा भयेन च प्रव्यथितं मनो मे ।
तदेव मे दर्शय देव रूपं प्रसीद देवेश जगन्निवास ॥', 'adṛṣṭapūrvaṃ hṛṣito ''smi dṛṣṭvā bhayena ca pravyathitaṃ mano me |
tad eva me darśaya deva rūpaṃ prasīda deveśa jagannivāsa ||', null, null),
  ('gita', 11, 46, null, null, 'किरीटिनं गदिनं चक्रहस्तमिच्छामि त्वां द्रष्टुमहं तथैव ।
तेनैव रूपेण चतुर्भुजेन सहस्रबाहो भव विश्वमूर्ते ॥', 'kirīṭinaṃ gadinaṃ cakrahastam icchāmi tvāṃ draṣṭum ahaṃ tathaiva |
tenaiva rūpeṇa caturbhujena sahasrabāho bhava viśvamūrte ||', null, null),
  ('gita', 11, 47, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'मया प्रसन्नेन तवार्जुनेदं रूपं परं दर्शितमात्मयोगात् ।
तेजोमयं विश्वमनन्तमाद्यं यन्मे त्वदन्येन न दृष्टपूर्वम् ॥', 'mayā prasannena tavārjunedaṃ rūpaṃ paraṃ darśitam ātmayogāt |
tejomayaṃ viśvam anantam ādyaṃ yan me tvadanyena na dṛṣṭapūrvam ||', null, null),
  ('gita', 11, 48, null, null, 'न वेद यज्ञाध्ययनैर्न दानैर्न च क्रियाभिर्न तपोभिरुग्रैः ।
एवंरूपः शक्य अहं नृलोके द्रष्टुं त्वदन्येन कुरुप्रवीर ॥', 'na veda yajñādhyayanair na dānair na ca kriyābhir na tapobhir ugraiḥ |
evaṃrūpaḥ śakya ahaṃ nṛloke draṣṭuṃ tvadanyena kurupravīra ||', null, null),
  ('gita', 11, 49, null, null, 'मा ते व्यथा मा च विमूढभावो दृष्ट्वा रूपं घोरमीदृङ्ममेदम् ।
व्यपेतभीः प्रीतमनाः पुनस्त्वं तदेव मे रूपमिदं प्रपश्य ॥', 'mā te vyathā mā ca vimūḍhabhāvo dṛṣṭvā rūpaṃ ghoram īdṛṅ mamedam |
vyapetabhīḥ prītamanāḥ punas tvaṃ tad eva me rūpam idaṃ prapaśya ||', null, null),
  ('gita', 11, 50, 'संजय उवाच', 'saṃjaya uvāca', 'इत्यर्जुनं वासुदेवस्तथोक्त्वा स्वकं रूपं दर्शयामास भूयः ।
आश्वासयामास च भीतमेनं भूत्वा पुनः सौम्यवपुर्महात्मा ॥', 'ity arjunaṃ vāsudevas tathoktvā svakaṃ rūpaṃ darśayām āsa bhūyaḥ |
āśvāsayām āsa ca bhītam enaṃ bhūtvā punaḥ saumyavapur mahātmā ||', null, null),
  ('gita', 11, 51, 'अर्जुन उवाच', 'arjuna uvāca', 'दृष्ट्वेदं मानुषं रूपं तव सौम्यं जनार्दन ।
इदानीमस्मि संवृत्तः सचेताः प्रकृतिं गतः ॥', 'dṛṣṭvedaṃ mānuṣaṃ rūpaṃ tava saumyaṃ janārdana |
idānīm asmi saṃvṛttaḥ sacetāḥ prakṛtiṃ gataḥ ||', null, null),
  ('gita', 11, 52, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'सुदुर्दर्शमिदं रूपं दृष्टवानसि यन्मम ।
देवा अप्यस्य रूपस्य नित्यं दर्शनकाङ्क्षिणः ॥', 'sudurdarśam idaṃ rūpaṃ dṛṣṭavān asi yan mama |
devā apy asya rūpasya nityaṃ darśanakāṅkṣiṇaḥ ||', null, null),
  ('gita', 11, 53, null, null, 'नाहं वेदैर्न तपसा न दानेन न चेज्यया ।
शक्य एवंविधो द्रष्टुं दृष्टवानसि मां यथा ॥', 'nāhaṃ vedair na tapasā na dānena na cejyayā |
śakya evaṃvidho draṣṭuṃ dṛṣṭavān asi māṃ yathā ||', null, null),
  ('gita', 11, 54, null, null, 'भक्त्या त्वनन्यया शक्य अहमेवंविधोऽर्जुन ।
ज्ञातुं द्रष्टुं च तत्त्वेन प्रवेष्टुं च परंतप ॥', 'bhaktyā tv ananyayā śakya aham evaṃvidho ''rjuna |
jñātuṃ draṣṭuṃ ca tattvena praveṣṭuṃ ca paraṃtapa ||', null, null),
  ('gita', 11, 55, null, null, 'मत्कर्मकृन्मत्परमो मद्भक्तः सङ्गवर्जितः ।
निर्वैरः सर्वभूतेषु यः स मामेति पाण्डव ॥', 'matkarmakṛn matparamo madbhaktaḥ saṅgavarjitaḥ |
nirvairaḥ sarvabhūteṣu yaḥ sa mām eti pāṇḍava ||', null, null),
  ('gita', 12, 1, 'अर्जुन उवाच', 'arjuna uvāca', 'एवं सततयुक्ता ये भक्तास्त्वां पर्युपासते ।
ये चाप्यक्षरमव्यक्तं तेषां के योगवित्तमाः ॥', 'evaṃ satatayuktā ye bhaktās tvāṃ paryupāsate |
ye cāpy akṣaram avyaktaṃ teṣāṃ ke yogavittamāḥ ||', null, null),
  ('gita', 12, 2, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'मय्यावेश्य मनो ये मां नित्ययुक्ता उपासते ।
श्रद्धया परयोपेतास्ते मे युक्ततमा मताः ॥', 'mayy āveśya mano ye māṃ nityayuktā upāsate |
śraddhayā parayopetās te me yuktatamā matāḥ ||', null, null),
  ('gita', 12, 3, null, null, 'ये त्वक्षरमनिर्देश्यमव्यक्तं पर्युपासते ।
सर्वत्रगमचिन्त्यं च कूटस्थमचलं ध्रुवम् ॥', 'ye tv akṣaram anirdeśyam avyaktaṃ paryupāsate |
sarvatragam acintyaṃ ca kūṭastham acalaṃ dhruvam ||', null, null),
  ('gita', 12, 4, null, null, 'संनियम्येन्द्रियग्रामं सर्वत्र समबुद्धयः ।
ते प्राप्नुवन्ति मामेव सर्वभूतहिते रताः ॥', 'saṃniyamyendriyagrāmaṃ sarvatra samabuddhayaḥ |
te prāpnuvanti mām eva sarvabhūtahite ratāḥ ||', null, null),
  ('gita', 12, 5, null, null, 'क्लेशोऽधिकतरस्तेषामव्यक्तासक्तचेतसाम् ।
अव्यक्ता हि गतिर्दुःखं देहवद्भिरवाप्यते ॥', 'kleśo ''dhikataras teṣām avyaktāsaktacetasām |
avyaktā hi gatir duḥkhaṃ dehavadbhir avāpyate ||', null, null),
  ('gita', 12, 6, null, null, 'ये तु सर्वाणि कर्माणि मयि संन्यस्य मत्पराः ।
अनन्येनैव योगेन मां ध्यायन्त उपासते ॥', 'ye tu sarvāṇi karmāṇi mayi saṃnyasya matparāḥ |
ananyenaiva yogena māṃ dhyāyanta upāsate ||', null, null),
  ('gita', 12, 7, null, null, 'तेषामहं समुद्धर्ता मृत्युसंसारसागरात् ।
भवामि नचिरात्पार्थ मय्यावेशितचेतसाम् ॥', 'teṣām ahaṃ samuddhartā mṛtyusaṃsārasāgarāt |
bhavāmi nacirāt pārtha mayy āveśitacetasām ||', null, null),
  ('gita', 12, 8, null, null, 'मय्येव मन आधत्स्व मयि बुद्धिं निवेशय ।
निवसिष्यसि मय्येव अत ऊर्ध्वं न संशयः ॥', 'mayy eva mana ādhatsva mayi buddhiṃ niveśaya |
nivasiṣyasi mayy eva ata ūrdhvaṃ na saṃśayaḥ ||', null, null),
  ('gita', 12, 9, null, null, 'अथ चित्तं समाधातुं न शक्नोषि मयि स्थिरम् ।
अभ्यासयोगेन ततो मामिच्छाप्तुं धनंजय ॥', 'atha cittaṃ samādhātuṃ na śaknoṣi mayi sthiram |
abhyāsayogena tato mām icchāptuṃ dhanaṃjaya ||', null, null),
  ('gita', 12, 10, null, null, 'अभ्यासेऽप्यसमर्थोऽसि मत्कर्मपरमो भव ।
मदर्थमपि कर्माणि कुर्वन्सिद्धिमवाप्स्यसि ॥', 'abhyāse ''py asamartho ''si matkarmaparamo bhava |
madartham api karmāṇi kurvan siddhim avāpsyasi ||', null, null),
  ('gita', 12, 11, null, null, 'अथैतदप्यशक्तोऽसि कर्तुं मद्योगमाश्रितः ।
सर्वकर्मफलत्यागं ततः कुरु यतात्मवान् ॥', 'athaitad apy aśakto ''si kartuṃ madyogam āśritaḥ |
sarvakarmaphalatyāgaṃ tataḥ kuru yatātmavān ||', null, null),
  ('gita', 12, 12, null, null, 'श्रेयो हि ज्ञानमभ्यासाज्ज्ञानाद्ध्यानं विशिष्यते ।
ध्यानात्कर्मफलत्यागस्त्यागाच्छान्तिरनन्तरम् ॥', 'śreyo hi jñānam abhyāsāj jñānād dhyānaṃ viśiṣyate |
dhyānāt karmaphalatyāgas tyāgāc chāntir anantaram ||', null, null),
  ('gita', 12, 13, null, null, 'अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च ।
निर्ममो निरहंकारः समदुःखसुखः क्षमी ॥', 'adveṣṭā sarvabhūtānāṃ maitraḥ karuṇa eva ca |
nirmamo nirahaṃkāraḥ samaduḥkhasukhaḥ kṣamī ||', null, null),
  ('gita', 12, 14, null, null, 'संतुष्टः सततं योगी यतात्मा दृढनिश्चयः ।
मय्यर्पितमनोबुद्धिर्यो मद्भक्तः स मे प्रियः ॥', 'saṃtuṣṭaḥ satataṃ yogī yatātmā dṛḍhaniścayaḥ |
mayy arpitamanobuddhir yo madbhaktaḥ sa me priyaḥ ||', null, null),
  ('gita', 12, 15, null, null, 'यस्मान्नोद्विजते लोको लोकान्नोद्विजते च यः ।
हर्षामर्षभयोद्वेगैर्मुक्तो यः स च मे प्रियः ॥', 'yasmān nodvijate loko lokān nodvijate ca yaḥ |
harṣāmarṣabhayodvegair mukto yaḥ sa ca me priyaḥ ||', null, null),
  ('gita', 12, 16, null, null, 'अनपेक्षः शुचिर्दक्ष उदासीनो गतव्यथः ।
सर्वारम्भपरित्यागी यो मद्भक्तः स मे प्रियः ॥', 'anapekṣaḥ śucir dakṣa udāsīno gatavyathaḥ |
sarvārambhaparityāgī yo madbhaktaḥ sa me priyaḥ ||', null, null),
  ('gita', 12, 17, null, null, 'यो न हृष्यति न द्वेष्टि न शोचति न काङ्क्षति ।
शुभाशुभपरित्यागी भक्तिमान्यः स मे प्रियः ॥', 'yo na hṛṣyati na dveṣṭi na śocati na kāṅkṣati |
śubhāśubhaparityāgī bhaktimān yaḥ sa me priyaḥ ||', null, null),
  ('gita', 12, 18, null, null, 'समः शत्रौ च मित्रे च तथा मानापमानयोः ।
शीतोष्णसुखदुःखेषु समः सङ्गविवर्जितः ॥', 'samaḥ śatrau ca mitre ca tathā mānāpamānayoḥ |
śītoṣṇasukhaduḥkheṣu samaḥ saṅgavivarjitaḥ ||', null, null),
  ('gita', 12, 19, null, null, 'तुल्यनिन्दास्तुतिर्मौनी संतुष्टो येन केन चित् ।
अनिकेतः स्थिरमतिर्भक्तिमान्मे प्रियो नरः ॥', 'tulyanindāstutir maunī saṃtuṣṭo yena kena cit |
aniketaḥ sthiramatir bhaktimān me priyo naraḥ ||', null, null),
  ('gita', 12, 20, null, null, 'ये तु धर्म्यामृतमिदं यथोक्तं पर्युपासते ।
श्रद्दधाना मत्परमा भक्तास्तेऽतीव मे प्रियाः ॥', 'ye tu dharmyāmṛtam idaṃ yathoktaṃ paryupāsate |
śraddadhānā matparamā bhaktās te ''tīva me priyāḥ ||', null, null),
  ('gita', 13, 1, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'इदं शरीरं कौन्तेय क्षेत्रमित्यभिधीयते ।
एतद्यो वेत्ति तं प्राहुः क्षेत्रज्ञ इति तद्विदः ॥', 'idaṃ śarīraṃ kaunteya kṣetram ity abhidhīyate |
etad yo vetti taṃ prāhuḥ kṣetrajña iti tadvidaḥ ||', null, null),
  ('gita', 13, 2, null, null, 'क्षेत्रज्ञं चापि मां विद्धि सर्वक्षेत्रेषु भारत ।
क्षेत्रक्षेत्रज्ञयोर्ज्ञानं यत्तज्ज्ञानं मतं मम ॥', 'kṣetrajñaṃ cāpi māṃ viddhi sarvakṣetreṣu bhārata |
kṣetrakṣetrajñayor jñānaṃ yat taj jñānaṃ mataṃ mama ||', null, null),
  ('gita', 13, 3, null, null, 'तत्क्षेत्रं यच्च यादृक्च यद्विकारि यतश्च यत् ।
स च यो यत्प्रभावश्च तत्समासेन मे शृणु ॥', 'tat kṣetraṃ yac ca yādṛk ca yadvikāri yataś ca yat |
sa ca yo yatprabhāvaś ca tat samāsena me śṛṇu ||', null, null),
  ('gita', 13, 4, null, null, 'ऋषिभिर्बहुधा गीतं छन्दोभिर्विविधैः पृथक् ।
ब्रह्मसूत्रपदैश्चैव हेतुमद्भिर्विनिश्चितैः ॥', 'ṛṣibhir bahudhā gītaṃ chandobhir vividhaiḥ pṛthak |
brahmasūtrapadaiś caiva hetumadbhir viniścitaiḥ ||', null, null),
  ('gita', 13, 5, null, null, 'महाभूतान्यहंकारो बुद्धिरव्यक्तमेव च ।
इन्द्रियाणि दशैकं च पञ्च चेन्द्रियगोचराः ॥', 'mahābhūtāny ahaṃkāro buddhir avyaktam eva ca |
indriyāṇi daśaikaṃ ca pañca cendriyagocarāḥ ||', null, null),
  ('gita', 13, 6, null, null, 'इच्छा द्वेषः सुखं दुःखं संघातश्चेतना धृतिः ।
एतत्क्षेत्रं समासेन सविकारमुदाहृतम् ॥', 'icchā dveṣaḥ sukhaṃ duḥkhaṃ saṃghātaś cetanā dhṛtiḥ |
etat kṣetraṃ samāsena savikāram udāhṛtam ||', null, null),
  ('gita', 13, 7, null, null, 'अमानित्वमदम्भित्वमहिंसा क्षान्तिरार्जवम् ।
आचार्योपासनं शौचं स्थैर्यमात्मविनिग्रहः ॥', 'amānitvam adambhitvam ahiṃsā kṣāntir ārjavam |
ācāryopāsanaṃ śaucaṃ sthairyam ātmavinigrahaḥ ||', null, null),
  ('gita', 13, 8, null, null, 'इन्द्रियार्थेषु वैराग्यमनहंकार एव च ।
जन्ममृत्युजराव्याधिदुःखदोषानुदर्शनम् ॥', 'indriyārtheṣu vairāgyam anahaṃkāra eva ca |
janmamṛtyujarāvyādhiduḥkhadoṣānudarśanam ||', null, null),
  ('gita', 13, 9, null, null, 'असक्तिरनभिष्वङ्गः पुत्रदारगृहादिषु ।
नित्यं च समचित्तत्वमिष्टानिष्टोपपत्तिषु ॥', 'asaktir anabhiṣvaṅgaḥ putradāragṛhādiṣu |
nityaṃ ca samacittatvam iṣṭāniṣṭopapattiṣu ||', null, null),
  ('gita', 13, 10, null, null, 'मयि चानन्ययोगेन भक्तिरव्यभिचारिणी ।
विविक्तदेशसेवित्वमरतिर्जनसंसदि ॥', 'mayi cānanyayogena bhaktir avyabhicāriṇī |
viviktadeśasevitvam aratir janasaṃsadi ||', null, null),
  ('gita', 13, 11, null, null, 'अध्यात्मज्ञाननित्यत्वं तत्त्वज्ञानार्थदर्शनम् ।
एतज्ज्ञानमिति प्रोक्तमज्ञानं यदतोऽन्यथा ॥', 'adhyātmajñānanityatvaṃ tattvajñānārthadarśanam |
etaj jñānam iti proktam ajñānaṃ yad ato ''nyathā ||', null, null),
  ('gita', 13, 12, null, null, 'ज्ञेयं यत्तत्प्रवक्ष्यामि यज्ज्ञात्वामृतमश्नुते ।
अनादिमत्परं ब्रह्म न सत्तन्नासदुच्यते ॥', 'jñeyaṃ yat tat pravakṣyāmi yaj jñātvāmṛtam aśnute |
anādimat paraṃ brahma na sat tan nāsad ucyate ||', null, null),
  ('gita', 13, 13, null, null, 'सर्वतः पाणिपादं तत्सर्वतोऽक्षिशिरोमुखम् ।
सर्वतः श्रुतिमल्लोके सर्वमावृत्य तिष्ठति ॥', 'sarvataḥ pāṇipādaṃ tat sarvato ''kṣiśiromukham |
sarvataḥ śrutimal loke sarvam āvṛtya tiṣṭhati ||', null, null),
  ('gita', 13, 14, null, null, 'सर्वेन्द्रियगुणाभासं सर्वेन्द्रियविवर्जितम् ।
असक्तं सर्वभृच्चैव निर्गुणं गुणभोक्तृ च ॥', 'sarvendriyaguṇābhāsaṃ sarvendriyavivarjitam |
asaktaṃ sarvabhṛc caiva nirguṇaṃ guṇabhoktṛ ca ||', null, null),
  ('gita', 13, 15, null, null, 'बहिरन्तश्च भूतानामचरं चरमेव च ।
सूक्ष्मत्वात्तदविज्ञेयं दूरस्थं चान्तिके च तत् ॥', 'bahir antaś ca bhūtānām acaraṃ caram eva ca |
sūkṣmatvāt tad avijñeyaṃ dūrasthaṃ cāntike ca tat ||', null, null),
  ('gita', 13, 16, null, null, 'अविभक्तं च भूतेषु विभक्तमिव च स्थितम् ।
भूतभर्तृ च तज्ज्ञेयं ग्रसिष्णु प्रभविष्णु च ॥', 'avibhaktaṃ ca bhūteṣu vibhaktam iva ca sthitam |
bhūtabhartṛ ca taj jñeyaṃ grasiṣṇu prabhaviṣṇu ca ||', null, null),
  ('gita', 13, 17, null, null, 'ज्योतिषामपि तज्ज्योतिस्तमसः परमुच्यते ।
ज्ञानं ज्ञेयं ज्ञानगम्यं हृदि सर्वस्य विष्ठितम् ॥', 'jyotiṣām api taj jyotis tamasaḥ param ucyate |
jñānaṃ jñeyaṃ jñānagamyaṃ hṛdi sarvasya viṣṭhitam ||', null, null),
  ('gita', 13, 18, null, null, 'इति क्षेत्रं तथा ज्ञानं ज्ञेयं चोक्तं समासतः ।
मद्भक्त एतद्विज्ञाय मद्भावायोपपद्यते ॥', 'iti kṣetraṃ tathā jñānaṃ jñeyaṃ coktaṃ samāsataḥ |
madbhakta etad vijñāya madbhāvāyopapadyate ||', null, null),
  ('gita', 13, 19, null, null, 'प्रकृतिं पुरुषं चैव विद्ध्यनादी उभावपि ।
विकारांश्च गुणांश्चैव विद्धि प्रकृतिसंभवान् ॥', 'prakṛtiṃ puruṣaṃ caiva viddhy anādī ubhāv api |
vikārāṃś ca guṇāṃś caiva viddhi prakṛtisaṃbhavān ||', null, null),
  ('gita', 13, 20, null, null, 'कार्यकारणकर्तृत्वे हेतुः प्रकृतिरुच्यते ।
पुरुषः सुखदुःखानां भोक्तृत्वे हेतुरुच्यते ॥', 'kāryakāraṇakartṛtve hetuḥ prakṛtir ucyate |
puruṣaḥ sukhaduḥkhānāṃ bhoktṛtve hetur ucyate ||', null, null),
  ('gita', 13, 21, null, null, 'पुरुषः प्रकृतिस्थो हि भुङ्क्ते प्रकृतिजान्गुणान् ।
कारणं गुणसङ्गोऽस्य सदसद्योनिजन्मसु ॥', 'puruṣaḥ prakṛtistho hi bhuṅkte prakṛtijān guṇān |
kāraṇaṃ guṇasaṅgo ''sya sadasadyonijanmasu ||', null, null),
  ('gita', 13, 22, null, null, 'उपद्रष्टानुमन्ता च भर्ता भोक्ता महेश्वरः ।
परमात्मेति चाप्युक्तो देहेऽस्मिन्पुरुषः परः ॥', 'upadraṣṭānumantā ca bhartā bhoktā maheśvaraḥ |
paramātmeti cāpy ukto dehe ''smin puruṣaḥ paraḥ ||', null, null),
  ('gita', 13, 23, null, null, 'य एवं वेत्ति पुरुषं प्रकृतिं च गुणैः सह ।
सर्वथा वर्तमानोऽपि न स भूयोऽभिजायते ॥', 'ya evaṃ vetti puruṣaṃ prakṛtiṃ ca guṇaiḥ saha |
sarvathā vartamāno ''pi na sa bhūyo ''bhijāyate ||', null, null),
  ('gita', 13, 24, null, null, 'ध्यानेनात्मनि पश्यन्ति के चिदात्मानमात्मना ।
अन्ये सांख्येन योगेन कर्मयोगेन चापरे ॥', 'dhyānenātmani paśyanti ke cid ātmānam ātmanā |
anye sāṃkhyena yogena karmayogena cāpare ||', null, null),
  ('gita', 13, 25, null, null, 'अन्ये त्वेवमजानन्तः श्रुत्वान्येभ्य उपासते ।
तेऽपि चातितरन्त्येव मृत्युं श्रुतिपरायणाः ॥', 'anye tv evam ajānantaḥ śrutvānyebhya upāsate |
te ''pi cātitaranty eva mṛtyuṃ śrutiparāyaṇāḥ ||', null, null),
  ('gita', 13, 26, null, null, 'यावत्संजायते किं चित्सत्त्वं स्थावरजङ्गमम् ।
क्षेत्रक्षेत्रज्ञसंयोगात्तद्विद्धि भरतर्षभ ॥', 'yāvat saṃjāyate kiṃ cit sattvaṃ sthāvarajaṅgamam |
kṣetrakṣetrajñasaṃyogāt tad viddhi bharatarṣabha ||', null, null),
  ('gita', 13, 27, null, null, 'समं सर्वेषु भूतेषु तिष्ठन्तं परमेश्वरम् ।
विनश्यत्स्वविनश्यन्तं यः पश्यति स पश्यति ॥', 'samaṃ sarveṣu bhūteṣu tiṣṭhantaṃ parameśvaram |
vinaśyatsv avinaśyantaṃ yaḥ paśyati sa paśyati ||', null, null),
  ('gita', 13, 28, null, null, 'समं पश्यन्हि सर्वत्र समवस्थितमीश्वरम् ।
न हिनस्त्यात्मनात्मानं ततो याति परां गतिम् ॥', 'samaṃ paśyan hi sarvatra samavasthitam īśvaram |
na hinasty ātmanātmānaṃ tato yāti parāṃ gatim ||', null, null),
  ('gita', 13, 29, null, null, 'प्रकृत्यैव च कर्माणि क्रियमाणानि सर्वशः ।
यः पश्यति तथात्मानमकर्तारं स पश्यति ॥', 'prakṛtyaiva ca karmāṇi kriyamāṇāni sarvaśaḥ |
yaḥ paśyati tathātmānam akartāraṃ sa paśyati ||', null, null),
  ('gita', 13, 30, null, null, 'यदा भूतपृथग्भावमेकस्थमनुपश्यति ।
तत एव च विस्तारं ब्रह्म संपद्यते तदा ॥', 'yadā bhūtapṛthagbhāvam ekastham anupaśyati |
tata eva ca vistāraṃ brahma saṃpadyate tadā ||', null, null),
  ('gita', 13, 31, null, null, 'अनादित्वान्निर्गुणत्वात्परमात्मायमव्ययः ।
शरीरस्थोऽपि कौन्तेय न करोति न लिप्यते ॥', 'anāditvān nirguṇatvāt paramātmāyam avyayaḥ |
śarīrastho ''pi kaunteya na karoti na lipyate ||', null, null),
  ('gita', 13, 32, null, null, 'यथा सर्वगतं सौक्ष्म्यादाकाशं नोपलिप्यते ।
सर्वत्रावस्थितो देहे तथात्मा नोपलिप्यते ॥', 'yathā sarvagataṃ saukṣmyād ākāśaṃ nopalipyate |
sarvatrāvasthito dehe tathātmā nopalipyate ||', null, null),
  ('gita', 13, 33, null, null, 'यथा प्रकाशयत्येकः कृत्स्नं लोकमिमं रविः ।
क्षेत्रं क्षेत्री तथा कृत्स्नं प्रकाशयति भारत ॥', 'yathā prakāśayaty ekaḥ kṛtsnaṃ lokam imaṃ raviḥ |
kṣetraṃ kṣetrī tathā kṛtsnaṃ prakāśayati bhārata ||', null, null),
  ('gita', 13, 34, null, null, 'क्षेत्रक्षेत्रज्ञयोरेवमन्तरं ज्ञानचक्षुषा ।
भूतप्रकृतिमोक्षं च ये विदुर्यान्ति ते परम् ॥', 'kṣetrakṣetrajñayor evam antaraṃ jñānacakṣuṣā |
bhūtaprakṛtimokṣaṃ ca ye vidur yānti te param ||', null, null),
  ('gita', 14, 1, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'परं भूयः प्रवक्ष्यामि ज्ञानानां ज्ञानमुत्तमम् ।
यज्ज्ञात्वा मुनयः सर्वे परां सिद्धिमितो गताः ॥', 'paraṃ bhūyaḥ pravakṣyāmi jñānānāṃ jñānam uttamam |
yaj jñātvā munayaḥ sarve parāṃ siddhim ito gatāḥ ||', null, null),
  ('gita', 14, 2, null, null, 'इदं ज्ञानमुपाश्रित्य मम साधर्म्यमागताः ।
सर्गेऽपि नोपजायन्ते प्रलये न व्यथन्ति च ॥', 'idaṃ jñānam upāśritya mama sādharmyam āgatāḥ |
sarge ''pi nopajāyante pralaye na vyathanti ca ||', null, null),
  ('gita', 14, 3, null, null, 'मम योनिर्महद्ब्रह्म तस्मिन्गर्भं दधाम्यहम् ।
संभवः सर्वभूतानां ततो भवति भारत ॥', 'mama yonir mahad brahma tasmin garbhaṃ dadhāmy aham |
saṃbhavaḥ sarvabhūtānāṃ tato bhavati bhārata ||', null, null),
  ('gita', 14, 4, null, null, 'सर्वयोनिषु कौन्तेय मूर्तयः संभवन्ति याः ।
तासां ब्रह्म महद्योनिरहं बीजप्रदः पिता ॥', 'sarvayoniṣu kaunteya mūrtayaḥ saṃbhavanti yāḥ |
tāsāṃ brahma mahad yonir ahaṃ bījapradaḥ pitā ||', null, null),
  ('gita', 14, 5, null, null, 'सत्त्वं रजस्तम इति गुणाः प्रकृतिसंभवाः ।
निबध्नन्ति महाबाहो देहे देहिनमव्ययम् ॥', 'sattvaṃ rajas tama iti guṇāḥ prakṛtisaṃbhavāḥ |
nibadhnanti mahābāho dehe dehinam avyayam ||', null, null),
  ('gita', 14, 6, null, null, 'तत्र सत्त्वं निर्मलत्वात्प्रकाशकमनामयम् ।
सुखसङ्गेन बध्नाति ज्ञानसङ्गेन चानघ ॥', 'tatra sattvaṃ nirmalatvāt prakāśakam anāmayam |
sukhasaṅgena badhnāti jñānasaṅgena cānagha ||', null, null),
  ('gita', 14, 7, null, null, 'रजो रागात्मकं विद्धि तृष्णासङ्गसमुद्भवम् ।
तन्निबध्नाति कौन्तेय कर्मसङ्गेन देहिनम् ॥', 'rajo rāgātmakaṃ viddhi tṛṣṇāsaṅgasamudbhavam |
tan nibadhnāti kaunteya karmasaṅgena dehinam ||', null, null),
  ('gita', 14, 8, null, null, 'तमस्त्वज्ञानजं विद्धि मोहनं सर्वदेहिनाम् ।
प्रमादालस्यनिद्राभिस्तन्निबध्नाति भारत ॥', 'tamas tv ajñānajaṃ viddhi mohanaṃ sarvadehinām |
pramādālasyanidrābhis tan nibadhnāti bhārata ||', null, null),
  ('gita', 14, 9, null, null, 'सत्त्वं सुखे संजयति रजः कर्मणि भारत ।
ज्ञानमावृत्य तु तमः प्रमादे संजयत्युत ॥', 'sattvaṃ sukhe saṃjayati rajaḥ karmaṇi bhārata |
jñānam āvṛtya tu tamaḥ pramāde saṃjayaty uta ||', null, null),
  ('gita', 14, 10, null, null, 'रजस्तमश्चाभिभूय सत्त्वं भवति भारत ।
रजः सत्त्वं तमश्चैव तमः सत्त्वं रजस्तथा ॥', 'rajas tamaś cābhibhūya sattvaṃ bhavati bhārata |
rajaḥ sattvaṃ tamaś caiva tamaḥ sattvaṃ rajas tathā ||', null, null),
  ('gita', 14, 11, null, null, 'सर्वद्वारेषु देहेऽस्मिन्प्रकाश उपजायते ।
ज्ञानं यदा तदा विद्याद्विवृद्धं सत्त्वमित्युत ॥', 'sarvadvāreṣu dehe ''smin prakāśa upajāyate |
jñānaṃ yadā tadā vidyād vivṛddhaṃ sattvam ity uta ||', null, null),
  ('gita', 14, 12, null, null, 'लोभः प्रवृत्तिरारम्भः कर्मणामशमः स्पृहा ।
रजस्येतानि जायन्ते विवृद्धे भरतर्षभ ॥', 'lobhaḥ pravṛttir ārambhaḥ karmaṇām aśamaḥ spṛhā |
rajasy etāni jāyante vivṛddhe bharatarṣabha ||', null, null),
  ('gita', 14, 13, null, null, 'अप्रकाशोऽप्रवृत्तिश्च प्रमादो मोह एव च ।
तमस्येतानि जायन्ते विवृद्धे कुरुनन्दन ॥', 'aprakāśo ''pravṛttiś ca pramādo moha eva ca |
tamasy etāni jāyante vivṛddhe kurunandana ||', null, null),
  ('gita', 14, 14, null, null, 'यदा सत्त्वे प्रवृद्धे तु प्रलयं याति देहभृत् ।
तदोत्तमविदां लोकानमलान्प्रतिपद्यते ॥', 'yadā sattve pravṛddhe tu pralayaṃ yāti dehabhṛt |
tadottamavidāṃ lokān amalān pratipadyate ||', null, null),
  ('gita', 14, 15, null, null, 'रजसि प्रलयं गत्वा कर्मसङ्गिषु जायते ।
तथा प्रलीनस्तमसि मूढयोनिषु जायते ॥', 'rajasi pralayaṃ gatvā karmasaṅgiṣu jāyate |
tathā pralīnas tamasi mūḍhayoniṣu jāyate ||', null, null),
  ('gita', 14, 16, null, null, 'कर्मणः सुकृतस्याहुः सात्त्विकं निर्मलं फलम् ।
रजसस्तु फलं दुःखमज्ञानं तमसः फलम् ॥', 'karmaṇaḥ sukṛtasyāhuḥ sāttvikaṃ nirmalaṃ phalam |
rajasas tu phalaṃ duḥkham ajñānaṃ tamasaḥ phalam ||', null, null),
  ('gita', 14, 17, null, null, 'सत्त्वात्संजायते ज्ञानं रजसो लोभ एव च ।
प्रमादमोहौ तमसो भवतोऽज्ञानमेव च ॥', 'sattvāt saṃjāyate jñānaṃ rajaso lobha eva ca |
pramādamohau tamaso bhavato ''jñānam eva ca ||', null, null),
  ('gita', 14, 18, null, null, 'ऊर्ध्वं गच्छन्ति सत्त्वस्था मध्ये तिष्ठन्ति राजसाः ।
जघन्यगुणवृत्तस्था अधो गच्छन्ति तामसाः ॥', 'ūrdhvaṃ gacchanti sattvasthā madhye tiṣṭhanti rājasāḥ |
jaghanyaguṇavṛttasthā adho gacchanti tāmasāḥ ||', null, null),
  ('gita', 14, 19, null, null, 'नान्यं गुणेभ्यः कर्तारं यदा द्रष्टानुपश्यति ।
गुणेभ्यश्च परं वेत्ति मद्भावं सोऽधिगच्छति ॥', 'nānyaṃ guṇebhyaḥ kartāraṃ yadā draṣṭānupaśyati |
guṇebhyaś ca paraṃ vetti madbhāvaṃ so ''dhigacchati ||', null, null),
  ('gita', 14, 20, null, null, 'गुणानेतानतीत्य त्रीन्देही देहसमुद्भवान् ।
जन्ममृत्युजरादुःखैर्विमुक्तोऽमृतमश्नुते ॥', 'guṇān etān atītya trīn dehī dehasamudbhavān |
janmamṛtyujarāduḥkhair vimukto ''mṛtam aśnute ||', null, null),
  ('gita', 14, 21, 'अर्जुन उवाच', 'arjuna uvāca', 'कैर्लिङ्गैस्त्रीन्गुणानेतानतीतो भवति प्रभो ।
किमाचारः कथं चैतांस्त्रीन्गुणानतिवर्तते ॥', 'kair liṅgais trīn guṇān etān atīto bhavati prabho |
kimācāraḥ kathaṃ caitāṃs trīn guṇān ativartate ||', null, null),
  ('gita', 14, 22, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'प्रकाशं च प्रवृत्तिं च मोहमेव च पाण्डव ।
न द्वेष्टि संप्रवृत्तानि न निवृत्तानि काङ्क्षति ॥', 'prakāśaṃ ca pravṛttiṃ ca moham eva ca pāṇḍava |
na dveṣṭi saṃpravṛttāni na nivṛttāni kāṅkṣati ||', null, null),
  ('gita', 14, 23, null, null, 'उदासीनवदासीनो गुणैर्यो न विचाल्यते ।
गुणा वर्तन्त इत्येव योऽवतिष्ठति नेङ्गते ॥', 'udāsīnavad āsīno guṇair yo na vicālyate |
guṇā vartanta ity eva yo ''vatiṣṭhati neṅgate ||', null, null),
  ('gita', 14, 24, null, null, 'समदुःखसुखः स्वस्थः समलोष्टाश्मकाञ्चनः ।
तुल्यप्रियाप्रियो धीरस्तुल्यनिन्दात्मसंस्तुतिः ॥', 'samaduḥkhasukhaḥ svasthaḥ samaloṣṭāśmakāñcanaḥ |
tulyapriyāpriyo dhīras tulyanindātmasaṃstutiḥ ||', null, null),
  ('gita', 14, 25, null, null, 'मानापमानयोस्तुल्यस्तुल्यो मित्रारिपक्षयोः ।
सर्वारम्भपरित्यागी गुणातीतः स उच्यते ॥', 'mānāpamānayos tulyas tulyo mitrāripakṣayoḥ |
sarvārambhaparityāgī guṇātītaḥ sa ucyate ||', null, null),
  ('gita', 14, 26, null, null, 'मां च योऽव्यभिचारेण भक्तियोगेन सेवते ।
स गुणान्समतीत्यैतान्ब्रह्मभूयाय कल्पते ॥', 'māṃ ca yo ''vyabhicāreṇa bhaktiyogena sevate |
sa guṇān samatītyaitān brahmabhūyāya kalpate ||', null, null),
  ('gita', 14, 27, null, null, 'ब्रह्मणो हि प्रतिष्ठाहममृतस्याव्ययस्य च ।
शाश्वतस्य च धर्मस्य सुखस्यैकान्तिकस्य च ॥', 'brahmaṇo hi pratiṣṭhāham amṛtasyāvyayasya ca |
śāśvatasya ca dharmasya sukhasyaikāntikasya ca ||', null, null),
  ('gita', 15, 1, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'ऊर्ध्वमूलमधःशाखमश्वत्थं प्राहुरव्ययम् ।
छन्दांसि यस्य पर्णानि यस्तं वेद स वेदवित् ॥', 'ūrdhvamūlam adhaḥśākham aśvatthaṃ prāhur avyayam |
chandāṃsi yasya parṇāni yas taṃ veda sa vedavit ||', null, null),
  ('gita', 15, 2, null, null, 'अधश्चोर्ध्वं प्रसृतास्तस्य शाखा गुणप्रवृद्धा विषयप्रवालाः ।
अधश्च मूलान्यनुसंततानि कर्मानुबन्धीनि मनुष्यलोके ॥', 'adhaś cordhvaṃ prasṛtās tasya śākhā guṇapravṛddhā viṣayapravālāḥ |
adhaś ca mūlāny anusaṃtatāni karmānubandhīni manuṣyaloke ||', null, null),
  ('gita', 15, 3, null, null, 'न रूपमस्येह तथोपलभ्यते नान्तो न चादिर्न च संप्रतिष्ठा ।
अश्वत्थमेनं सुविरूढमूलमसङ्गशस्त्रेण दृढेन छित्त्वा ॥', 'na rūpam asyeha tathopalabhyate nānto na cādir na ca saṃpratiṣṭhā |
aśvattham enaṃ suvirūḍhamūlam asaṅgaśastreṇa dṛḍhena chittvā ||', null, null),
  ('gita', 15, 4, null, null, 'ततः पदं तत्परिमार्गितव्यं यस्मिन्गता न निवर्तन्ति भूयः ।
तमेव चाद्यं पुरुषं प्रपद्ये यतः प्रवृत्तिः प्रसृता पुराणी ॥', 'tataḥ padaṃ tatparimārgitavyaṃ yasmin gatā na nivartanti bhūyaḥ |
tam eva cādyaṃ puruṣaṃ prapadye yataḥ pravṛttiḥ prasṛtā purāṇī ||', null, null),
  ('gita', 15, 5, null, null, 'निर्मानमोहा जितसङ्गदोषा अध्यात्मनित्या विनिवृत्तकामाः ।
द्वन्द्वैर्विमुक्ताः सुखदुःखसंज्ञैर्गच्छन्त्यमूढाः पदमव्ययं तत् ॥', 'nirmānamohā jitasaṅgadoṣā adhyātmanityā vinivṛttakāmāḥ |
dvandvair vimuktāḥ sukhaduḥkhasaṃjñair gacchanty amūḍhāḥ padam avyayaṃ tat ||', null, null),
  ('gita', 15, 6, null, null, 'न तद्भासयते सूर्यो न शशाङ्को न पावकः ।
यद्गत्वा न निवर्तन्ते तद्धाम परमं मम ॥', 'na tad bhāsayate sūryo na śaśāṅko na pāvakaḥ |
yad gatvā na nivartante tad dhāma paramaṃ mama ||', null, null),
  ('gita', 15, 7, null, null, 'ममैवांशो जीवलोके जीवभूतः सनातनः ।
मनःषष्ठानीन्द्रियाणि प्रकृतिस्थानि कर्षति ॥', 'mamaivāṃśo jīvaloke jīvabhūtaḥ sanātanaḥ |
manaḥṣaṣṭhānīndriyāṇi prakṛtisthāni karṣati ||', null, null),
  ('gita', 15, 8, null, null, 'शरीरं यदवाप्नोति यच्चाप्युत्क्रामतीश्वरः ।
गृहीत्वैतानि संयाति वायुर्गन्धानिवाशयात् ॥', 'śarīraṃ yad avāpnoti yac cāpy utkrāmatīśvaraḥ |
gṛhītvaitāni saṃyāti vāyur gandhān ivāśayāt ||', null, null),
  ('gita', 15, 9, null, null, 'श्रोत्रं चक्षुः स्पर्शनं च रसनं घ्राणमेव च ।
अधिष्ठाय मनश्चायं विषयानुपसेवते ॥', 'śrotraṃ cakṣuḥ sparśanaṃ ca rasanaṃ ghrāṇam eva ca |
adhiṣṭhāya manaś cāyaṃ viṣayān upasevate ||', null, null),
  ('gita', 15, 10, null, null, 'उत्क्रामन्तं स्थितं वापि भुञ्जानं वा गुणान्वितम् ।
विमूढा नानुपश्यन्ति पश्यन्ति ज्ञानचक्षुषः ॥', 'utkrāmantaṃ sthitaṃ vāpi bhuñjānaṃ vā guṇānvitam |
vimūḍhā nānupaśyanti paśyanti jñānacakṣuṣaḥ ||', null, null),
  ('gita', 15, 11, null, null, 'यतन्तो योगिनश्चैनं पश्यन्त्यात्मन्यवस्थितम् ।
यतन्तोऽप्यकृतात्मानो नैनं पश्यन्त्यचेतसः ॥', 'yatanto yoginaś cainaṃ paśyanty ātmany avasthitam |
yatanto ''py akṛtātmāno nainaṃ paśyanty acetasaḥ ||', null, null),
  ('gita', 15, 12, null, null, 'यदादित्यगतं तेजो जगद्भासयतेऽखिलम् ।
यच्चन्द्रमसि यच्चाग्नौ तत्तेजो विद्धि मामकम् ॥', 'yad ādityagataṃ tejo jagad bhāsayate ''khilam |
yac candramasi yac cāgnau tat tejo viddhi māmakam ||', null, null),
  ('gita', 15, 13, null, null, 'गामाविश्य च भूतानि धारयाम्यहमोजसा ।
पुष्णामि चौषधीः सर्वाः सोमो भूत्वा रसात्मकः ॥', 'gām āviśya ca bhūtāni dhārayāmy aham ojasā |
puṣṇāmi cauṣadhīḥ sarvāḥ somo bhūtvā rasātmakaḥ ||', null, null),
  ('gita', 15, 14, null, null, 'अहं वैश्वानरो भूत्वा प्राणिनां देहमाश्रितः ।
प्राणापानसमायुक्तः पचाम्यन्नं चतुर्विधम् ॥', 'ahaṃ vaiśvānaro bhūtvā prāṇināṃ deham āśritaḥ |
prāṇāpānasamāyuktaḥ pacāmy annaṃ caturvidham ||', null, null),
  ('gita', 15, 15, null, null, 'सर्वस्य चाहं हृदि संनिविष्टो मत्तः स्मृतिर्ज्ञानमपोहनं च ।
वेदैश्च सर्वैरहमेव वेद्यो वेदान्तकृद्वेदविदेव चाहम् ॥', 'sarvasya cāhaṃ hṛdi saṃniviṣṭo mattaḥ smṛtir jñānam apohanaṃ ca |
vedaiś ca sarvair aham eva vedyo vedāntakṛd vedavid eva cāham ||', null, null),
  ('gita', 15, 16, null, null, 'द्वाविमौ पुरुषौ लोके क्षरश्चाक्षर एव च ।
क्षरः सर्वाणि भूतानि कूटस्थोऽक्षर उच्यते ॥', 'dvāv imau puruṣau loke kṣaraś cākṣara eva ca |
kṣaraḥ sarvāṇi bhūtāni kūṭastho ''kṣara ucyate ||', null, null),
  ('gita', 15, 17, null, null, 'उत्तमः पुरुषस्त्वन्यः परमात्मेत्युदाहृतः ।
यो लोकत्रयमाविश्य बिभर्त्यव्यय ईश्वरः ॥', 'uttamaḥ puruṣas tv anyaḥ paramātmety udāhṛtaḥ |
yo lokatrayam āviśya bibharty avyaya īśvaraḥ ||', null, null),
  ('gita', 15, 18, null, null, 'यस्मात्क्षरमतीतोऽहमक्षरादपि चोत्तमः ।
अतोऽस्मि लोके वेदे च प्रथितः पुरुषोत्तमः ॥', 'yasmāt kṣaram atīto ''ham akṣarād api cottamaḥ |
ato ''smi loke vede ca prathitaḥ puruṣottamaḥ ||', null, null),
  ('gita', 15, 19, null, null, 'यो मामेवमसंमूढो जानाति पुरुषोत्तमम् ।
स सर्वविद्भजति मां सर्वभावेन भारत ॥', 'yo mām evam asaṃmūḍho jānāti puruṣottamam |
sa sarvavid bhajati māṃ sarvabhāvena bhārata ||', null, null),
  ('gita', 15, 20, null, null, 'इति गुह्यतमं शास्त्रमिदमुक्तं मयानघ ।
एतद्बुद्ध्वा बुद्धिमान्स्यात्कृतकृत्यश्च भारत ॥', 'iti guhyatamaṃ śāstram idam uktaṃ mayānagha |
etad buddhvā buddhimān syāt kṛtakṛtyaś ca bhārata ||', null, null),
  ('gita', 16, 1, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'अभयं सत्त्वसंशुद्धिर्ज्ञानयोगव्यवस्थितिः ।
दानं दमश्च यज्ञश्च स्वाध्यायस्तप आर्जवम् ॥', 'abhayaṃ sattvasaṃśuddhir jñānayogavyavasthitiḥ |
dānaṃ damaś ca yajñaś ca svādhyāyas tapa ārjavam ||', null, null),
  ('gita', 16, 2, null, null, 'अहिंसा सत्यमक्रोधस्त्यागः शान्तिरपैशुनम् ।
दया भूतेष्वलोलुप्त्वं मार्दवं ह्रीरचापलम् ॥', 'ahiṃsā satyam akrodhas tyāgaḥ śāntir apaiśunam |
dayā bhūteṣv aloluptvaṃ mārdavaṃ hrīr acāpalam ||', null, null),
  ('gita', 16, 3, null, null, 'तेजः क्षमा धृतिः शौचमद्रोहो नातिमानिता ।
भवन्ति संपदं दैवीमभिजातस्य भारत ॥', 'tejaḥ kṣamā dhṛtiḥ śaucam adroho nātimānitā |
bhavanti saṃpadaṃ daivīm abhijātasya bhārata ||', null, null),
  ('gita', 16, 4, null, null, 'दम्भो दर्पोऽतिमानश्च क्रोधः पारुष्यमेव च ।
अज्ञानं चाभिजातस्य पार्थ संपदमासुरीम् ॥', 'dambho darpo ''timānaś ca krodhaḥ pāruṣyam eva ca |
ajñānaṃ cābhijātasya pārtha saṃpadam āsurīm ||', null, null),
  ('gita', 16, 5, null, null, 'दैवी संपद्विमोक्षाय निबन्धायासुरी मता ।
मा शुचः संपदं दैवीमभिजातोऽसि पाण्डव ॥', 'daivī saṃpad vimokṣāya nibandhāyāsurī matā |
mā śucaḥ saṃpadaṃ daivīm abhijāto ''si pāṇḍava ||', null, null),
  ('gita', 16, 6, null, null, 'द्वौ भूतसर्गौ लोकेऽस्मिन्दैव आसुर एव च ।
दैवो विस्तरशः प्रोक्त आसुरं पार्थ मे शृणु ॥', 'dvau bhūtasargau loke ''smin daiva āsura eva ca |
daivo vistaraśaḥ prokta āsuraṃ pārtha me śṛṇu ||', null, null),
  ('gita', 16, 7, null, null, 'प्रवृत्तिं च निवृत्तिं च जना न विदुरासुराः ।
न शौचं नापि चाचारो न सत्यं तेषु विद्यते ॥', 'pravṛttiṃ ca nivṛttiṃ ca janā na vidur āsurāḥ |
na śaucaṃ nāpi cācāro na satyaṃ teṣu vidyate ||', null, null),
  ('gita', 16, 8, null, null, 'असत्यमप्रतिष्ठं ते जगदाहुरनीश्वरम् ।
अपरस्परसंभूतं किमन्यत्कामहैतुकम् ॥', 'asatyam apratiṣṭhaṃ te jagad āhur anīśvaram |
aparasparasaṃbhūtaṃ kim anyat kāmahaitukam ||', null, null),
  ('gita', 16, 9, null, null, 'एतां दृष्टिमवष्टभ्य नष्टात्मानोऽल्पबुद्धयः ।
प्रभवन्त्युग्रकर्माणः क्षयाय जगतोऽहिताः ॥', 'etāṃ dṛṣṭim avaṣṭabhya naṣṭātmāno ''lpabuddhayaḥ |
prabhavanty ugrakarmāṇaḥ kṣayāya jagato ''hitāḥ ||', null, null),
  ('gita', 16, 10, null, null, 'काममाश्रित्य दुष्पूरं दम्भमानमदान्विताः ।
मोहाद्गृहीत्वासद्ग्राहान्प्रवर्तन्तेऽशुचिव्रताः ॥', 'kāmam āśritya duṣpūraṃ dambhamānamadānvitāḥ |
mohād gṛhītvāsadgrāhān pravartante ''śucivratāḥ ||', null, null),
  ('gita', 16, 11, null, null, 'चिन्तामपरिमेयां च प्रलयान्तामुपाश्रिताः ।
कामोपभोगपरमा एतावदिति निश्चिताः ॥', 'cintām aparimeyāṃ ca pralayāntām upāśritāḥ |
kāmopabhogaparamā etāvad iti niścitāḥ ||', null, null),
  ('gita', 16, 12, null, null, 'आशापाशशतैर्बद्धाः कामक्रोधपरायणाः ।
ईहन्ते कामभोगार्थमन्यायेनार्थसंचयान् ॥', 'āśāpāśaśatair baddhāḥ kāmakrodhaparāyaṇāḥ |
īhante kāmabhogārtham anyāyenārthasaṃcayān ||', null, null),
  ('gita', 16, 13, null, null, 'इदमद्य मया लब्धमिदं प्राप्स्ये मनोरथम् ।
इदमस्तीदमपि मे भविष्यति पुनर्धनम् ॥', 'idam adya mayā labdham idaṃ prāpsye manoratham |
idam astīdam api me bhaviṣyati punar dhanam ||', null, null),
  ('gita', 16, 14, null, null, 'असौ मया हतः शत्रुर्हनिष्ये चापरानपि ।
ईश्वरोऽहमहं भोगी सिद्धोऽहं बलवान्सुखी ॥', 'asau mayā hataḥ śatrur haniṣye cāparān api |
īśvaro ''ham ahaṃ bhogī siddho ''haṃ balavān sukhī ||', null, null),
  ('gita', 16, 15, null, null, 'आढ्योऽभिजनवानस्मि कोऽन्योऽस्ति सदृशो मया ।
यक्ष्ये दास्यामि मोदिष्य इत्यज्ञानविमोहिताः ॥', 'āḍhyo ''bhijanavān asmi ko ''nyo ''sti sadṛśo mayā |
yakṣye dāsyāmi modiṣya ity ajñānavimohitāḥ ||', null, null),
  ('gita', 16, 16, null, null, 'अनेकचित्तविभ्रान्ता मोहजालसमावृताः ।
प्रसक्ताः कामभोगेषु पतन्ति नरकेऽशुचौ ॥', 'anekacittavibhrāntā mohajālasamāvṛtāḥ |
prasaktāḥ kāmabhogeṣu patanti narake ''śucau ||', null, null),
  ('gita', 16, 17, null, null, 'आत्मसंभाविताः स्तब्धा धनमानमदान्विताः ।
यजन्ते नामयज्ञैस्ते दम्भेनाविधिपूर्वकम् ॥', 'ātmasaṃbhāvitāḥ stabdhā dhanamānamadānvitāḥ |
yajante nāmayajñais te dambhenāvidhipūrvakam ||', null, null),
  ('gita', 16, 18, null, null, 'अहंकारं बलं दर्पं कामं क्रोधं च संश्रिताः ।
मामात्मपरदेहेषु प्रद्विषन्तोऽभ्यसूयकाः ॥', 'ahaṃkāraṃ balaṃ darpaṃ kāmaṃ krodhaṃ ca saṃśritāḥ |
mām ātmaparadeheṣu pradviṣanto ''bhyasūyakāḥ ||', null, null),
  ('gita', 16, 19, null, null, 'तानहं द्विषतः क्रूरान्संसारेषु नराधमान् ।
क्षिपाम्यजस्रमशुभानासुरीष्वेव योनिषु ॥', 'tān ahaṃ dviṣataḥ krūrān saṃsāreṣu narādhamān |
kṣipāmy ajasram aśubhān āsurīṣv eva yoniṣu ||', null, null),
  ('gita', 16, 20, null, null, 'आसुरीं योनिमापन्ना मूढा जन्मनि जन्मनि ।
मामप्राप्यैव कौन्तेय ततो यान्त्यधमां गतिम् ॥', 'āsurīṃ yonim āpannā mūḍhā janmani janmani |
mām aprāpyaiva kaunteya tato yānty adhamāṃ gatim ||', null, null),
  ('gita', 16, 21, null, null, 'त्रिविधं नरकस्येदं द्वारं नाशनमात्मनः ।
कामः क्रोधस्तथा लोभस्तस्मादेतत्त्रयं त्यजेत् ॥', 'trividhaṃ narakasyedaṃ dvāraṃ nāśanam ātmanaḥ |
kāmaḥ krodhas tathā lobhas tasmād etat trayaṃ tyajet ||', null, null),
  ('gita', 16, 22, null, null, 'एतैर्विमुक्तः कौन्तेय तमोद्वारैस्त्रिभिर्नरः ।
आचरत्यात्मनः श्रेयस्ततो याति परां गतिम् ॥', 'etair vimuktaḥ kaunteya tamodvārais tribhir naraḥ |
ācaraty ātmanaḥ śreyas tato yāti parāṃ gatim ||', null, null),
  ('gita', 16, 23, null, null, 'यः शास्त्रविधिमुत्सृज्य वर्तते कामकारतः ।
न स सिद्धिमवाप्नोति न सुखं न परां गतिम् ॥', 'yaḥ śāstravidhim utsṛjya vartate kāmakārataḥ |
na sa siddhim avāpnoti na sukhaṃ na parāṃ gatim ||', null, null),
  ('gita', 16, 24, null, null, 'तस्माच्छास्त्रं प्रमाणं ते कार्याकार्यव्यवस्थितौ ।
ज्ञात्वा शास्त्रविधानोक्तं कर्म कर्तुमिहार्हसि ॥', 'tasmāc chāstraṃ pramāṇaṃ te kāryākāryavyavasthitau |
jñātvā śāstravidhānoktaṃ karma kartum ihārhasi ||', null, null),
  ('gita', 17, 1, 'अर्जुन उवाच', 'arjuna uvāca', 'ये शास्त्रविधिमुत्सृज्य यजन्ते श्रद्धयान्विताः ।
तेषां निष्ठा तु का कृष्ण सत्त्वमाहो रजस्तमः ॥', 'ye śāstravidhim utsṛjya yajante śraddhayānvitāḥ |
teṣāṃ niṣṭhā tu kā kṛṣṇa sattvam āho rajas tamaḥ ||', null, null),
  ('gita', 17, 2, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'त्रिविधा भवति श्रद्धा देहिनां सा स्वभावजा ।
सात्त्विकी राजसी चैव तामसी चेति तां शृणु ॥', 'trividhā bhavati śraddhā dehināṃ sā svabhāvajā |
sāttvikī rājasī caiva tāmasī ceti tāṃ śṛṇu ||', null, null),
  ('gita', 17, 3, null, null, 'सत्त्वानुरूपा सर्वस्य श्रद्धा भवति भारत ।
श्रद्धामयोऽयं पुरुषो यो यच्छ्रद्धः स एव सः ॥', 'sattvānurūpā sarvasya śraddhā bhavati bhārata |
śraddhāmayo ''yaṃ puruṣo yo yacchraddhaḥ sa eva saḥ ||', null, null),
  ('gita', 17, 4, null, null, 'यजन्ते सात्त्विका देवान्यक्षरक्षांसि राजसाः ।
प्रेतान्भूतगणांश्चान्ये यजन्ते तामसा जनाः ॥', 'yajante sāttvikā devān yakṣarakṣāṃsi rājasāḥ |
pretān bhūtagaṇāṃś cānye yajante tāmasā janāḥ ||', null, null),
  ('gita', 17, 5, null, null, 'अशास्त्रविहितं घोरं तप्यन्ते ये तपो जनाः ।
दम्भाहंकारसंयुक्ताः कामरागबलान्विताः ॥', 'aśāstravihitaṃ ghoraṃ tapyante ye tapo janāḥ |
dambhāhaṃkārasaṃyuktāḥ kāmarāgabalānvitāḥ ||', null, null),
  ('gita', 17, 6, null, null, 'कर्शयन्तः शरीरस्थं भूतग्राममचेतसः ।
मां चैवान्तःशरीरस्थं तान्विद्ध्यासुरनिश्चयान् ॥', 'karśayantaḥ śarīrasthaṃ bhūtagrāmam acetasaḥ |
māṃ caivāntaḥśarīrasthaṃ tān viddhy āsuraniścayān ||', null, null),
  ('gita', 17, 7, null, null, 'आहारस्त्वपि सर्वस्य त्रिविधो भवति प्रियः ।
यज्ञस्तपस्तथा दानं तेषां भेदमिमं शृणु ॥', 'āhāras tv api sarvasya trividho bhavati priyaḥ |
yajñas tapas tathā dānaṃ teṣāṃ bhedam imaṃ śṛṇu ||', null, null),
  ('gita', 17, 8, null, null, 'आयुःसत्त्वबलारोग्यसुखप्रीतिविवर्धनाः ।
रस्याः स्निग्धाः स्थिरा हृद्या आहाराः सात्त्विकप्रियाः ॥', 'āyuḥsattvabalārogyasukhaprītivivardhanāḥ |
rasyāḥ snigdhāḥ sthirā hṛdyā āhārāḥ sāttvikapriyāḥ ||', null, null),
  ('gita', 17, 9, null, null, 'कट्वम्ललवणात्युष्णतीक्ष्णरूक्षविदाहिनः ।
आहारा राजसस्येष्टा दुःखशोकामयप्रदाः ॥', 'kaṭvamlalavaṇātyuṣṇatīkṣṇarūkṣavidāhinaḥ |
āhārā rājasasyeṣṭā duḥkhaśokāmayapradāḥ ||', null, null),
  ('gita', 17, 10, null, null, 'यातयामं गतरसं पूति पर्युषितं च यत् ।
उच्छिष्टमपि चामेध्यं भोजनं तामसप्रियम् ॥', 'yātayāmaṃ gatarasaṃ pūti paryuṣitaṃ ca yat |
ucchiṣṭam api cāmedhyaṃ bhojanaṃ tāmasapriyam ||', null, null),
  ('gita', 17, 11, null, null, 'अफलाकाङ्क्षिभिर्यज्ञो विधिदृष्टो य इज्यते ।
यष्टव्यमेवेति मनः समाधाय स सात्त्विकः ॥', 'aphalākāṅkṣibhir yajño vidhidṛṣṭo ya ijyate |
yaṣṭavyam eveti manaḥ samādhāya sa sāttvikaḥ ||', null, null),
  ('gita', 17, 12, null, null, 'अभिसंधाय तु फलं दम्भार्थमपि चैव यत् ।
इज्यते भरतश्रेष्ठ तं यज्ञं विद्धि राजसम् ॥', 'abhisaṃdhāya tu phalaṃ dambhārtham api caiva yat |
ijyate bharataśreṣṭha taṃ yajñaṃ viddhi rājasam ||', null, null),
  ('gita', 17, 13, null, null, 'विधिहीनमसृष्टान्नं मन्त्रहीनमदक्षिणम् ।
श्रद्धाविरहितं यज्ञं तामसं परिचक्षते ॥', 'vidhihīnam asṛṣṭānnaṃ mantrahīnam adakṣiṇam |
śraddhāvirahitaṃ yajñaṃ tāmasaṃ paricakṣate ||', null, null),
  ('gita', 17, 14, null, null, 'देवद्विजगुरुप्राज्ञपूजनं शौचमार्जवम् ।
ब्रह्मचर्यमहिंसा च शारीरं तप उच्यते ॥', 'devadvijaguruprājñapūjanaṃ śaucam ārjavam |
brahmacaryam ahiṃsā ca śārīraṃ tapa ucyate ||', null, null),
  ('gita', 17, 15, null, null, 'अनुद्वेगकरं वाक्यं सत्यं प्रियहितं च यत् ।
स्वाध्यायाभ्यसनं चैव वाङ्मयं तप उच्यते ॥', 'anudvegakaraṃ vākyaṃ satyaṃ priyahitaṃ ca yat |
svādhyāyābhyasanaṃ caiva vāṅmayaṃ tapa ucyate ||', null, null),
  ('gita', 17, 16, null, null, 'मनःप्रसादः सौम्यत्वं मौनमात्मविनिग्रहः ।
भावसंशुद्धिरित्येतत्तपो मानसमुच्यते ॥', 'manaḥprasādaḥ saumyatvaṃ maunam ātmavinigrahaḥ |
bhāvasaṃśuddhir ity etat tapo mānasam ucyate ||', null, null),
  ('gita', 17, 17, null, null, 'श्रद्धया परया तप्तं तपस्तत्त्रिविधं नरैः ।
अफलाकाङ्क्षिभिर्युक्तैः सात्त्विकं परिचक्षते ॥', 'śraddhayā parayā taptaṃ tapas tat trividhaṃ naraiḥ |
aphalākāṅkṣibhir yuktaiḥ sāttvikaṃ paricakṣate ||', null, null),
  ('gita', 17, 18, null, null, 'सत्कारमानपूजार्थं तपो दम्भेन चैव यत् ।
क्रियते तदिह प्रोक्तं राजसं चलमध्रुवम् ॥', 'satkāramānapūjārthaṃ tapo dambhena caiva yat |
kriyate tad iha proktaṃ rājasaṃ calam adhruvam ||', null, null),
  ('gita', 17, 19, null, null, 'मूढग्राहेणात्मनो यत्पीडया क्रियते तपः ।
परस्योत्सादनार्थं वा तत्तामसमुदाहृतम् ॥', 'mūḍhagrāheṇātmano yat pīḍayā kriyate tapaḥ |
parasyotsādanārthaṃ vā tat tāmasam udāhṛtam ||', null, null),
  ('gita', 17, 20, null, null, 'दातव्यमिति यद्दानं दीयतेऽनुपकारिणे ।
देशे काले च पात्रे च तद्दानं सात्त्विकं स्मृतम् ॥', 'dātavyam iti yad dānaṃ dīyate ''nupakāriṇe |
deśe kāle ca pātre ca tad dānaṃ sāttvikaṃ smṛtam ||', null, null),
  ('gita', 17, 21, null, null, 'यत्तु प्रत्युपकारार्थं फलमुद्दिश्य वा पुनः ।
दीयते च परिक्लिष्टं तद्दानं राजसं स्मृतम् ॥', 'yat tu pratyupakārārthaṃ phalam uddiśya vā punaḥ |
dīyate ca parikliṣṭaṃ tad dānaṃ rājasaṃ smṛtam ||', null, null),
  ('gita', 17, 22, null, null, 'अदेशकाले यद्दानमपात्रेभ्यश्च दीयते ।
असत्कृतमवज्ञातं तत्तामसमुदाहृतम् ॥', 'adeśakāle yad dānam apātrebhyaś ca dīyate |
asatkṛtam avajñātaṃ tat tāmasam udāhṛtam ||', null, null),
  ('gita', 17, 23, null, null, 'ॐ तत्सदिति निर्देशो ब्रह्मणस्त्रिविधः स्मृतः ।
ब्राह्मणास्तेन वेदाश्च यज्ञाश्च विहिताः पुरा ॥', 'oṃ tat sad iti nirdeśo brahmaṇas trividhaḥ smṛtaḥ |
brāhmaṇās tena vedāś ca yajñāś ca vihitāḥ purā ||', null, null),
  ('gita', 17, 24, null, null, 'तस्मादोमित्युदाहृत्य यज्ञदानतपःक्रियाः ।
प्रवर्तन्ते विधानोक्ताः सततं ब्रह्मवादिनाम् ॥', 'tasmād om ity udāhṛtya yajñadānatapaḥkriyāḥ |
pravartante vidhānoktāḥ satataṃ brahmavādinām ||', null, null),
  ('gita', 17, 25, null, null, 'तदित्यनभिसंधाय फलं यज्ञतपःक्रियाः ।
दानक्रियाश्च विविधाः क्रियन्ते मोक्षकाङ्क्षिभिः ॥', 'tad ity anabhisaṃdhāya phalaṃ yajñatapaḥkriyāḥ |
dānakriyāś ca vividhāḥ kriyante mokṣakāṅkṣibhiḥ ||', null, null),
  ('gita', 17, 26, null, null, 'सद्भावे साधुभावे च सदित्येतत्प्रयुज्यते ।
प्रशस्ते कर्मणि तथा सच्छब्दः पार्थ युज्यते ॥', 'sadbhāve sādhubhāve ca sad ity etat prayujyate |
praśaste karmaṇi tathā sacchabdaḥ pārtha yujyate ||', null, null),
  ('gita', 17, 27, null, null, 'यज्ञे तपसि दाने च स्थितिः सदिति चोच्यते ।
कर्म चैव तदर्थीयं सदित्येवाभिधीयते ॥', 'yajñe tapasi dāne ca sthitiḥ sad iti cocyate |
karma caiva tadarthīyaṃ sad ity evābhidhīyate ||', null, null),
  ('gita', 17, 28, null, null, 'अश्रद्धया हुतं दत्तं तपस्तप्तं कृतं च यत् ।
असदित्युच्यते पार्थ न च तत्प्रेत्य नो इह ॥', 'aśraddhayā hutaṃ dattaṃ tapas taptaṃ kṛtaṃ ca yat |
asad ity ucyate pārtha na ca tat pretya no iha ||', null, null),
  ('gita', 18, 1, 'अर्जुन उवाच', 'arjuna uvāca', 'संन्यासस्य महाबाहो तत्त्वमिच्छामि वेदितुम् ।
त्यागस्य च हृषीकेश पृथक्केशिनिषूदन ॥', 'saṃnyāsasya mahābāho tattvam icchāmi veditum |
tyāgasya ca hṛṣīkeśa pṛthak keśiniṣūdana ||', null, null),
  ('gita', 18, 2, 'श्रीभगवानुवाच', 'śrībhagavān uvāca', 'काम्यानां कर्मणां न्यासं संन्यासं कवयो विदुः ।
सर्वकर्मफलत्यागं प्राहुस्त्यागं विचक्षणाः ॥', 'kāmyānāṃ karmaṇāṃ nyāsaṃ saṃnyāsaṃ kavayo viduḥ |
sarvakarmaphalatyāgaṃ prāhus tyāgaṃ vicakṣaṇāḥ ||', null, null),
  ('gita', 18, 3, null, null, 'त्याज्यं दोषवदित्येके कर्म प्राहुर्मनीषिणः ।
यज्ञदानतपःकर्म न त्याज्यमिति चापरे ॥', 'tyājyaṃ doṣavad ity eke karma prāhur manīṣiṇaḥ |
yajñadānatapaḥkarma na tyājyam iti cāpare ||', null, null),
  ('gita', 18, 4, null, null, 'निश्चयं शृणु मे तत्र त्यागे भरतसत्तम ।
त्यागो हि पुरुषव्याघ्र त्रिविधः संप्रकीर्तितः ॥', 'niścayaṃ śṛṇu me tatra tyāge bharatasattama |
tyāgo hi puruṣavyāghra trividhaḥ saṃprakīrtitaḥ ||', null, null),
  ('gita', 18, 5, null, null, 'यज्ञदानतपःकर्म न त्याज्यं कार्यमेव तत् ।
यज्ञो दानं तपश्चैव पावनानि मनीषिणाम् ॥', 'yajñadānatapaḥkarma na tyājyaṃ kāryam eva tat |
yajño dānaṃ tapaś caiva pāvanāni manīṣiṇām ||', null, null),
  ('gita', 18, 6, null, null, 'एतान्यपि तु कर्माणि सङ्गं त्यक्त्वा फलानि च ।
कर्तव्यानीति मे पार्थ निश्चितं मतमुत्तमम् ॥', 'etāny api tu karmāṇi saṅgaṃ tyaktvā phalāni ca |
kartavyānīti me pārtha niścitaṃ matam uttamam ||', null, null),
  ('gita', 18, 7, null, null, 'नियतस्य तु संन्यासः कर्मणो नोपपद्यते ।
मोहात्तस्य परित्यागस्तामसः परिकीर्तितः ॥', 'niyatasya tu saṃnyāsaḥ karmaṇo nopapadyate |
mohāt tasya parityāgas tāmasaḥ parikīrtitaḥ ||', null, null),
  ('gita', 18, 8, null, null, 'दुःखमित्येव यत्कर्म कायक्लेशभयात्त्यजेत् ।
स कृत्वा राजसं त्यागं नैव त्यागफलं लभेत् ॥', 'duḥkham ity eva yat karma kāyakleśabhayāt tyajet |
sa kṛtvā rājasaṃ tyāgaṃ naiva tyāgaphalaṃ labhet ||', null, null),
  ('gita', 18, 9, null, null, 'कार्यमित्येव यत्कर्म नियतं क्रियतेऽर्जुन ।
सङ्गं त्यक्त्वा फलं चैव स त्यागः सात्त्विको मतः ॥', 'kāryam ity eva yat karma niyataṃ kriyate ''rjuna |
saṅgaṃ tyaktvā phalaṃ caiva sa tyāgaḥ sāttviko mataḥ ||', null, null),
  ('gita', 18, 10, null, null, 'न द्वेष्ट्यकुशलं कर्म कुशले नानुषज्जते ।
त्यागी सत्त्वसमाविष्टो मेधावी छिन्नसंशयः ॥', 'na dveṣṭy akuśalaṃ karma kuśale nānuṣajjate |
tyāgī sattvasamāviṣṭo medhāvī chinnasaṃśayaḥ ||', null, null),
  ('gita', 18, 11, null, null, 'न हि देहभृता शक्यं त्यक्तुं कर्माण्यशेषतः ।
यस्तु कर्मफलत्यागी स त्यागीत्यभिधीयते ॥', 'na hi dehabhṛtā śakyaṃ tyaktuṃ karmāṇy aśeṣataḥ |
yas tu karmaphalatyāgī sa tyāgīty abhidhīyate ||', null, null),
  ('gita', 18, 12, null, null, 'अनिष्टमिष्टं मिश्रं च त्रिविधं कर्मणः फलम् ।
भवत्यत्यागिनां प्रेत्य न तु संन्यासिनां क्व चित् ॥', 'aniṣṭam iṣṭaṃ miśraṃ ca trividhaṃ karmaṇaḥ phalam |
bhavaty atyāgināṃ pretya na tu saṃnyāsināṃ kva cit ||', null, null),
  ('gita', 18, 13, null, null, 'पञ्चैतानि महाबाहो कारणानि निबोध मे ।
सांख्ये कृतान्ते प्रोक्तानि सिद्धये सर्वकर्मणाम् ॥', 'pañcaitāni mahābāho kāraṇāni nibodha me |
sāṃkhye kṛtānte proktāni siddhaye sarvakarmaṇām ||', null, null),
  ('gita', 18, 14, null, null, 'अधिष्ठानं तथा कर्ता करणं च पृथग्विधम् ।
विविधाश्च पृथक्चेष्टा दैवं चैवात्र पञ्चमम् ॥', 'adhiṣṭhānaṃ tathā kartā karaṇaṃ ca pṛthagvidham |
vividhāś ca pṛthakceṣṭā daivaṃ caivātra pañcamam ||', null, null),
  ('gita', 18, 15, null, null, 'शरीरवाङ्मनोभिर्यत्कर्म प्रारभते नरः ।
न्याय्यं वा विपरीतं वा पञ्चैते तस्य हेतवः ॥', 'śarīravāṅmanobhir yat karma prārabhate naraḥ |
nyāyyaṃ vā viparītaṃ vā pañcaite tasya hetavaḥ ||', null, null),
  ('gita', 18, 16, null, null, 'तत्रैवं सति कर्तारमात्मानं केवलं तु यः ।
पश्यत्यकृतबुद्धित्वान्न स पश्यति दुर्मतिः ॥', 'tatraivaṃ sati kartāram ātmānaṃ kevalaṃ tu yaḥ |
paśyaty akṛtabuddhitvān na sa paśyati durmatiḥ ||', null, null),
  ('gita', 18, 17, null, null, 'यस्य नाहंकृतो भावो बुद्धिर्यस्य न लिप्यते ।
हत्वापि स इमाँल्लोकान्न हन्ति न निबध्यते ॥', 'yasya nāhaṃkṛto bhāvo buddhir yasya na lipyate |
hatvāpi sa imāṁl lokān na hanti na nibadhyate ||', null, null),
  ('gita', 18, 18, null, null, 'ज्ञानं ज्ञेयं परिज्ञाता त्रिविधा कर्मचोदना ।
करणं कर्म कर्तेति त्रिविधः कर्मसंग्रहः ॥', 'jñānaṃ jñeyaṃ parijñātā trividhā karmacodanā |
karaṇaṃ karma karteti trividhaḥ karmasaṃgrahaḥ ||', null, null),
  ('gita', 18, 19, null, null, 'ज्ञानं कर्म च कर्ता च त्रिधैव गुणभेदतः ।
प्रोच्यते गुणसंख्याने यथावच्छृणु तान्यपि ॥', 'jñānaṃ karma ca kartā ca tridhaiva guṇabhedataḥ |
procyate guṇasaṃkhyāne yathāvac chṛṇu tāny api ||', null, null),
  ('gita', 18, 20, null, null, 'सर्वभूतेषु येनैकं भावमव्ययमीक्षते ।
अविभक्तं विभक्तेषु तज्ज्ञानं विद्धि सात्त्विकम् ॥', 'sarvabhūteṣu yenaikaṃ bhāvam avyayam īkṣate |
avibhaktaṃ vibhakteṣu taj jñānaṃ viddhi sāttvikam ||', null, null),
  ('gita', 18, 21, null, null, 'पृथक्त्वेन तु यज्ज्ञानं नानाभावान्पृथग्विधान् ।
वेत्ति सर्वेषु भूतेषु तज्ज्ञानं विद्धि राजसम् ॥', 'pṛthaktvena tu yaj jñānaṃ nānābhāvān pṛthagvidhān |
vetti sarveṣu bhūteṣu taj jñānaṃ viddhi rājasam ||', null, null),
  ('gita', 18, 22, null, null, 'यत्तु कृत्स्नवदेकस्मिन्कार्ये सक्तमहैतुकम् ।
अतत्त्वार्थवदल्पं च तत्तामसमुदाहृतम् ॥', 'yat tu kṛtsnavad ekasmin kārye saktam ahaitukam |
atattvārthavad alpaṃ ca tat tāmasam udāhṛtam ||', null, null),
  ('gita', 18, 23, null, null, 'नियतं सङ्गरहितमरागद्वेषतः कृतम् ।
अफलप्रेप्सुना कर्म यत्तत्सात्त्विकमुच्यते ॥', 'niyataṃ saṅgarahitam arāgadveṣataḥ kṛtam |
aphalaprepsunā karma yat tat sāttvikam ucyate ||', null, null),
  ('gita', 18, 24, null, null, 'यत्तु कामेप्सुना कर्म साहंकारेण वा पुनः ।
क्रियते बहुलायासं तद्राजसमुदाहृतम् ॥', 'yat tu kāmepsunā karma sāhaṃkāreṇa vā punaḥ |
kriyate bahulāyāsaṃ tad rājasam udāhṛtam ||', null, null),
  ('gita', 18, 25, null, null, 'अनुबन्धं क्षयं हिंसामनपेक्ष्य च पौरुषम् ।
मोहादारभ्यते कर्म यत्तत्तामसमुच्यते ॥', 'anubandhaṃ kṣayaṃ hiṃsām anapekṣya ca pauruṣam |
mohād ārabhyate karma yat tat tāmasam ucyate ||', null, null),
  ('gita', 18, 26, null, null, 'मुक्तसङ्गोऽनहंवादी धृत्युत्साहसमन्वितः ।
सिद्ध्यसिद्ध्योर्निर्विकारः कर्ता सात्त्विक उच्यते ॥', 'muktasaṅgo ''nahaṃvādī dhṛtyutsāhasamanvitaḥ |
siddhyasiddhyor nirvikāraḥ kartā sāttvika ucyate ||', null, null),
  ('gita', 18, 27, null, null, 'रागी कर्मफलप्रेप्सुर्लुब्धो हिंसात्मकोऽशुचिः ।
हर्षशोकान्वितः कर्ता राजसः परिकीर्तितः ॥', 'rāgī karmaphalaprepsur lubdho hiṃsātmako ''śuciḥ |
harṣaśokānvitaḥ kartā rājasaḥ parikīrtitaḥ ||', null, null),
  ('gita', 18, 28, null, null, 'अयुक्तः प्राकृतः स्तब्धः शठो नैकृतिकोऽलसः ।
विषादी दीर्घसूत्री च कर्ता तामस उच्यते ॥', 'ayuktaḥ prākṛtaḥ stabdhaḥ śaṭho naikṛtiko ''lasaḥ |
viṣādī dīrghasūtrī ca kartā tāmasa ucyate ||', null, null),
  ('gita', 18, 29, null, null, 'बुद्धेर्भेदं धृतेश्चैव गुणतस्त्रिविधं शृणु ।
प्रोच्यमानमशेषेण पृथक्त्वेन धनंजय ॥', 'buddher bhedaṃ dhṛteś caiva guṇatas trividhaṃ śṛṇu |
procyamānam aśeṣeṇa pṛthaktvena dhanaṃjaya ||', null, null),
  ('gita', 18, 30, null, null, 'प्रवृत्तिं च निवृत्तिं च कार्याकार्ये भयाभये ।
बन्धं मोक्षं च या वेत्ति बुद्धिः सा पार्थ सात्त्विकी ॥', 'pravṛttiṃ ca nivṛttiṃ ca kāryākārye bhayābhaye |
bandhaṃ mokṣaṃ ca yā vetti buddhiḥ sā pārtha sāttvikī ||', null, null),
  ('gita', 18, 31, null, null, 'यया धर्ममधर्मं च कार्यं चाकार्यमेव च ।
अयथावत्प्रजानाति बुद्धिः सा पार्थ राजसी ॥', 'yayā dharmam adharmaṃ ca kāryaṃ cākāryam eva ca |
ayathāvat prajānāti buddhiḥ sā pārtha rājasī ||', null, null),
  ('gita', 18, 32, null, null, 'अधर्मं धर्ममिति या मन्यते तमसावृता ।
सर्वार्थान्विपरीतांश्च बुद्धिः सा पार्थ तामसी ॥', 'adharmaṃ dharmam iti yā manyate tamasāvṛtā |
sarvārthān viparītāṃś ca buddhiḥ sā pārtha tāmasī ||', null, null),
  ('gita', 18, 33, null, null, 'धृत्या यया धारयते मनःप्राणेन्द्रियक्रियाः ।
योगेनाव्यभिचारिण्या धृतिः सा पार्थ सात्त्विकी ॥', 'dhṛtyā yayā dhārayate manaḥprāṇendriyakriyāḥ |
yogenāvyabhicāriṇyā dhṛtiḥ sā pārtha sāttvikī ||', null, null),
  ('gita', 18, 34, null, null, 'यया तु धर्मकामार्थान्धृत्या धारयतेऽर्जुन ।
प्रसङ्गेन फलाकाङ्क्षी धृतिः सा पार्थ राजसी ॥', 'yayā tu dharmakāmārthān dhṛtyā dhārayate ''rjuna |
prasaṅgena phalākāṅkṣī dhṛtiḥ sā pārtha rājasī ||', null, null),
  ('gita', 18, 35, null, null, 'यया स्वप्नं भयं शोकं विषादं मदमेव च ।
न विमुञ्चति दुर्मेधा धृतिः सा पार्थ तामसी ॥', 'yayā svapnaṃ bhayaṃ śokaṃ viṣādaṃ madam eva ca |
na vimuñcati durmedhā dhṛtiḥ sā pārtha tāmasī ||', null, null),
  ('gita', 18, 36, null, null, 'सुखं त्विदानीं त्रिविधं शृणु मे भरतर्षभ ।
अभ्यासाद्रमते यत्र दुःखान्तं च निगच्छति ॥', 'sukhaṃ tv idānīṃ trividhaṃ śṛṇu me bharatarṣabha |
abhyāsād ramate yatra duḥkhāntaṃ ca nigacchati ||', null, null),
  ('gita', 18, 37, null, null, 'यत्तदग्रे विषमिव परिणामेऽमृतोपमम् ।
तत्सुखं सात्त्विकं प्रोक्तमात्मबुद्धिप्रसादजम् ॥', 'yat tadagre viṣam iva pariṇāme ''mṛtopamam |
tat sukhaṃ sāttvikaṃ proktam ātmabuddhiprasādajam ||', null, null),
  ('gita', 18, 38, null, null, 'विषयेन्द्रियसंयोगाद्यत्तदग्रेऽमृतोपमम् ।
परिणामे विषमिव तत्सुखं राजसं स्मृतम् ॥', 'viṣayendriyasaṃyogād yat tadagre ''mṛtopamam |
pariṇāme viṣam iva tat sukhaṃ rājasaṃ smṛtam ||', null, null),
  ('gita', 18, 39, null, null, 'यदग्रे चानुबन्धे च सुखं मोहनमात्मनः ।
निद्रालस्यप्रमादोत्थं तत्तामसमुदाहृतम् ॥', 'yad agre cānubandhe ca sukhaṃ mohanam ātmanaḥ |
nidrālasyapramādotthaṃ tat tāmasam udāhṛtam ||', null, null),
  ('gita', 18, 40, null, null, 'न तदस्ति पृथिव्यां वा दिवि देवेषु वा पुनः ।
सत्त्वं प्रकृतिजैर्मुक्तं यदेभिः स्यात्त्रिभिर्गुणैः ॥', 'na tad asti pṛthivyāṃ vā divi deveṣu vā punaḥ |
sattvaṃ prakṛtijair muktaṃ yad ebhiḥ syāt tribhir guṇaiḥ ||', null, null),
  ('gita', 18, 41, null, null, 'ब्राह्मणक्षत्रियविशां शूद्राणां च परंतप ।
कर्माणि प्रविभक्तानि स्वभावप्रभवैर्गुणैः ॥', 'brāhmaṇakṣatriyaviśāṃ śūdrāṇāṃ ca paraṃtapa |
karmāṇi pravibhaktāni svabhāvaprabhavair guṇaiḥ ||', null, null),
  ('gita', 18, 42, null, null, 'शमो दमस्तपः शौचं क्षान्तिरार्जवमेव च ।
ज्ञानं विज्ञानमास्तिक्यं ब्रह्मकर्म स्वभावजम् ॥', 'śamo damas tapaḥ śaucaṃ kṣāntir ārjavam eva ca |
jñānaṃ vijñānam āstikyaṃ brahmakarma svabhāvajam ||', null, null),
  ('gita', 18, 43, null, null, 'शौर्यं तेजो धृतिर्दाक्ष्यं युद्धे चाप्यपलायनम् ।
दानमीश्वरभावश्च क्षात्रं कर्म स्वभावजम् ॥', 'śauryaṃ tejo dhṛtir dākṣyaṃ yuddhe cāpy apalāyanam |
dānam īśvarabhāvaś ca kṣātraṃ karma svabhāvajam ||', null, null),
  ('gita', 18, 44, null, null, 'कृषिगोरक्ष्यवाणिज्यं वैश्यकर्म स्वभावजम् ।
परिचर्यात्मकं कर्म शूद्रस्यापि स्वभावजम् ॥', 'kṛṣigorakṣyavāṇijyaṃ vaiśyakarma svabhāvajam |
paricaryātmakaṃ karma śūdrasyāpi svabhāvajam ||', null, null),
  ('gita', 18, 45, null, null, 'स्वे स्वे कर्मण्यभिरतः संसिद्धिं लभते नरः ।
स्वकर्मनिरतः सिद्धिं यथा विन्दति तच्छृणु ॥', 'sve sve karmaṇy abhirataḥ saṃsiddhiṃ labhate naraḥ |
svakarmanirataḥ siddhiṃ yathā vindati tac chṛṇu ||', null, null),
  ('gita', 18, 46, null, null, 'यतः प्रवृत्तिर्भूतानां येन सर्वमिदं ततम् ।
स्वकर्मणा तमभ्यर्च्य सिद्धिं विन्दति मानवः ॥', 'yataḥ pravṛttir bhūtānāṃ yena sarvam idaṃ tatam |
svakarmaṇā tam abhyarcya siddhiṃ vindati mānavaḥ ||', null, null),
  ('gita', 18, 47, null, null, 'श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात् ।
स्वभावनियतं कर्म कुर्वन्नाप्नोति किल्बिषम् ॥', 'śreyān svadharmo viguṇaḥ paradharmāt svanuṣṭhitāt |
svabhāvaniyataṃ karma kurvan nāpnoti kilbiṣam ||', null, null),
  ('gita', 18, 48, null, null, 'सहजं कर्म कौन्तेय सदोषमपि न त्यजेत् ।
सर्वारम्भा हि दोषेण धूमेनाग्निरिवावृताः ॥', 'sahajaṃ karma kaunteya sadoṣam api na tyajet |
sarvārambhā hi doṣeṇa dhūmenāgnir ivāvṛtāḥ ||', null, null),
  ('gita', 18, 49, null, null, 'असक्तबुद्धिः सर्वत्र जितात्मा विगतस्पृहः ।
नैष्कर्म्यसिद्धिं परमां संन्यासेनाधिगच्छति ॥', 'asaktabuddhiḥ sarvatra jitātmā vigataspṛhaḥ |
naiṣkarmyasiddhiṃ paramāṃ saṃnyāsenādhigacchati ||', null, null),
  ('gita', 18, 50, null, null, 'सिद्धिं प्राप्तो यथा ब्रह्म तथाप्नोति निबोध मे ।
समासेनैव कौन्तेय निष्ठा ज्ञानस्य या परा ॥', 'siddhiṃ prāpto yathā brahma tathāpnoti nibodha me |
samāsenaiva kaunteya niṣṭhā jñānasya yā parā ||', null, null),
  ('gita', 18, 51, null, null, 'बुद्ध्या विशुद्धया युक्तो धृत्यात्मानं नियम्य च ।
शब्दादीन्विषयांस्त्यक्त्वा रागद्वेषौ व्युदस्य च ॥', 'buddhyā viśuddhayā yukto dhṛtyātmānaṃ niyamya ca |
śabdādīn viṣayāṃs tyaktvā rāgadveṣau vyudasya ca ||', null, null),
  ('gita', 18, 52, null, null, 'विविक्तसेवी लघ्वाशी यतवाक्कायमानसः ।
ध्यानयोगपरो नित्यं वैराग्यं समुपाश्रितः ॥', 'viviktasevī laghvāśī yatavākkāyamānasaḥ |
dhyānayogaparo nityaṃ vairāgyaṃ samupāśritaḥ ||', null, null),
  ('gita', 18, 53, null, null, 'अहंकारं बलं दर्पं कामं क्रोधं परिग्रहम् ।
विमुच्य निर्ममः शान्तो ब्रह्मभूयाय कल्पते ॥', 'ahaṃkāraṃ balaṃ darpaṃ kāmaṃ krodhaṃ parigraham |
vimucya nirmamaḥ śānto brahmabhūyāya kalpate ||', null, null),
  ('gita', 18, 54, null, null, 'ब्रह्मभूतः प्रसन्नात्मा न शोचति न काङ्क्षति ।
समः सर्वेषु भूतेषु मद्भक्तिं लभते पराम् ॥', 'brahmabhūtaḥ prasannātmā na śocati na kāṅkṣati |
samaḥ sarveṣu bhūteṣu madbhaktiṃ labhate parām ||', null, null),
  ('gita', 18, 55, null, null, 'भक्त्या मामभिजानाति यावान्यश्चास्मि तत्त्वतः ।
ततो मां तत्त्वतो ज्ञात्वा विशते तदनन्तरम् ॥', 'bhaktyā mām abhijānāti yāvān yaś cāsmi tattvataḥ |
tato māṃ tattvato jñātvā viśate tadanantaram ||', null, null),
  ('gita', 18, 56, null, null, 'सर्वकर्माण्यपि सदा कुर्वाणो मद्व्यपाश्रयः ।
मत्प्रसादादवाप्नोति शाश्वतं पदमव्ययम् ॥', 'sarvakarmāṇy api sadā kurvāṇo madvyapāśrayaḥ |
matprasādād avāpnoti śāśvataṃ padam avyayam ||', null, null),
  ('gita', 18, 57, null, null, 'चेतसा सर्वकर्माणि मयि संन्यस्य मत्परः ।
बुद्धियोगमुपाश्रित्य मच्चित्तः सततं भव ॥', 'cetasā sarvakarmāṇi mayi saṃnyasya matparaḥ |
buddhiyogam upāśritya maccittaḥ satataṃ bhava ||', null, null),
  ('gita', 18, 58, null, null, 'मच्चित्तः सर्वदुर्गाणि मत्प्रसादात्तरिष्यसि ।
अथ चेत्त्वमहंकारान्न श्रोष्यसि विनङ्क्ष्यसि ॥', 'maccittaḥ sarvadurgāṇi matprasādāt tariṣyasi |
atha cet tvam ahaṃkārān na śroṣyasi vinaṅkṣyasi ||', null, null),
  ('gita', 18, 59, null, null, 'यदहंकारमाश्रित्य न योत्स्य इति मन्यसे ।
मिथ्यैष व्यवसायस्ते प्रकृतिस्त्वां नियोक्ष्यति ॥', 'yad ahaṃkāram āśritya na yotsya iti manyase |
mithyaiṣa vyavasāyas te prakṛtis tvāṃ niyokṣyati ||', null, null),
  ('gita', 18, 60, null, null, 'स्वभावजेन कौन्तेय निबद्धः स्वेन कर्मणा ।
कर्तुं नेच्छसि यन्मोहात्करिष्यस्यवशोऽपि तत् ॥', 'svabhāvajena kaunteya nibaddhaḥ svena karmaṇā |
kartuṃ necchasi yan mohāt kariṣyasy avaśo ''pi tat ||', null, null),
  ('gita', 18, 61, null, null, 'ईश्वरः सर्वभूतानां हृद्देशेऽर्जुन तिष्ठति ।
भ्रामयन्सर्वभूतानि यन्त्रारूढानि मायया ॥', 'īśvaraḥ sarvabhūtānāṃ hṛddeśe ''rjuna tiṣṭhati |
bhrāmayan sarvabhūtāni yantrārūḍhāni māyayā ||', null, null),
  ('gita', 18, 62, null, null, 'तमेव शरणं गच्छ सर्वभावेन भारत ।
तत्प्रसादात्परां शान्तिं स्थानं प्राप्स्यसि शाश्वतम् ॥', 'tam eva śaraṇaṃ gaccha sarvabhāvena bhārata |
tatprasādāt parāṃ śāntiṃ sthānaṃ prāpsyasi śāśvatam ||', null, null),
  ('gita', 18, 63, null, null, 'इति ते ज्ञानमाख्यातं गुह्याद्गुह्यतरं मया ।
विमृश्यैतदशेषेण यथेच्छसि तथा कुरु ॥', 'iti te jñānam ākhyātaṃ guhyād guhyataraṃ mayā |
vimṛśyaitad aśeṣeṇa yathecchasi tathā kuru ||', null, null),
  ('gita', 18, 64, null, null, 'सर्वगुह्यतमं भूयः शृणु मे परमं वचः ।
इष्टोऽसि मे दृढमिति ततो वक्ष्यामि ते हितम् ॥', 'sarvaguhyatamaṃ bhūyaḥ śṛṇu me paramaṃ vacaḥ |
iṣṭo ''si me dṛḍham iti tato vakṣyāmi te hitam ||', null, null),
  ('gita', 18, 65, null, null, 'मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु ।
मामेवैष्यसि सत्यं ते प्रतिजाने प्रियोऽसि मे ॥', 'manmanā bhava madbhakto madyājī māṃ namaskuru |
mām evaiṣyasi satyaṃ te pratijāne priyo ''si me ||', null, null),
  ('gita', 18, 66, null, null, 'सर्वधर्मान्परित्यज्य मामेकं शरणं व्रज ।
अहं त्वा सर्वपापेभ्यो मोक्षयिष्यामि मा शुचः ॥', 'sarvadharmān parityajya mām ekaṃ śaraṇaṃ vraja |
ahaṃ tvā sarvapāpebhyo mokṣayiṣyāmi mā śucaḥ ||', null, null),
  ('gita', 18, 67, null, null, 'इदं ते नातपस्काय नाभक्ताय कदा चन ।
न चाशुश्रूषवे वाच्यं न च मां योऽभ्यसूयति ॥', 'idaṃ te nātapaskāya nābhaktāya kadā cana |
na cāśuśrūṣave vācyaṃ na ca māṃ yo ''bhyasūyati ||', null, null),
  ('gita', 18, 68, null, null, 'य इदं परमं गुह्यं मद्भक्तेष्वभिधास्यति ।
भक्तिं मयि परां कृत्वा मामेवैष्यत्यसंशयः ॥', 'ya idaṃ paramaṃ guhyaṃ madbhakteṣv abhidhāsyati |
bhaktiṃ mayi parāṃ kṛtvā mām evaiṣyaty asaṃśayaḥ ||', null, null),
  ('gita', 18, 69, null, null, 'न च तस्मान्मनुष्येषु कश्चिन्मे प्रियकृत्तमः ।
भविता न च मे तस्मादन्यः प्रियतरो भुवि ॥', 'na ca tasmān manuṣyeṣu kaś cin me priyakṛttamaḥ |
bhavitā na ca me tasmād anyaḥ priyataro bhuvi ||', null, null),
  ('gita', 18, 70, null, null, 'अध्येष्यते च य इमं धर्म्यं संवादमावयोः ।
ज्ञानयज्ञेन तेनाहमिष्टः स्यामिति मे मतिः ॥', 'adhyeṣyate ca ya imaṃ dharmyaṃ saṃvādam āvayoḥ |
jñānayajñena tenāham iṣṭaḥ syām iti me matiḥ ||', null, null),
  ('gita', 18, 71, null, null, 'श्रद्धावाननसूयश्च शृणुयादपि यो नरः ।
सोऽपि मुक्तः शुभाँल्लोकान्प्राप्नुयात्पुण्यकर्मणाम् ॥', 'śraddhāvān anasūyaś ca śṛṇuyād api yo naraḥ |
so ''pi muktaḥ śubhāṁl lokān prāpnuyāt puṇyakarmaṇām ||', null, null),
  ('gita', 18, 72, null, null, 'कच्चिदेतच्छ्रुतं पार्थ त्वयैकाग्रेण चेतसा ।
कच्चिदज्ञानसंमोहः प्रनष्टस्ते धनंजय ॥', 'kac cid etac chrutaṃ pārtha tvayaikāgreṇa cetasā |
kac cid ajñānasaṃmohaḥ pranaṣṭas te dhanaṃjaya ||', null, null),
  ('gita', 18, 73, 'अर्जुन उवाच', 'arjuna uvāca', 'नष्टो मोहः स्मृतिर्लब्धा त्वत्प्रसादान्मयाच्युत ।
स्थितोऽस्मि गतसंदेहः करिष्ये वचनं तव ॥', 'naṣṭo mohaḥ smṛtir labdhā tvatprasādān mayācyuta |
sthito ''smi gatasaṃdehaḥ kariṣye vacanaṃ tava ||', null, null),
  ('gita', 18, 74, 'संजय उवाच', 'saṃjaya uvāca', 'इत्यहं वासुदेवस्य पार्थस्य च महात्मनः ।
संवादमिममश्रौषमद्भुतं रोमहर्षणम् ॥', 'ity ahaṃ vāsudevasya pārthasya ca mahātmanaḥ |
saṃvādam imam aśrauṣam adbhutaṃ romaharṣaṇam ||', null, null),
  ('gita', 18, 75, null, null, 'व्यासप्रसादाच्छ्रुतवानेतद्गुह्यमहं परम् ।
योगं योगेश्वरात्कृष्णात्साक्षात्कथयतः स्वयम् ॥', 'vyāsaprasādāc chrutavān etad guhyam ahaṃ param |
yogaṃ yogeśvarāt kṛṣṇāt sākṣāt kathayataḥ svayam ||', null, null),
  ('gita', 18, 76, null, null, 'राजन्संस्मृत्य संस्मृत्य संवादमिममद्भुतम् ।
केशवार्जुनयोः पुण्यं हृष्यामि च मुहुर्मुहुः ॥', 'rājan saṃsmṛtya saṃsmṛtya saṃvādam imam adbhutam |
keśavārjunayoḥ puṇyaṃ hṛṣyāmi ca muhur muhuḥ ||', null, null),
  ('gita', 18, 77, null, null, 'तच्च संस्मृत्य संस्मृत्य रूपमत्यद्भुतं हरेः ।
विस्मयो मे महान्राजन्हृष्यामि च पुनः पुनः ॥', 'tac ca saṃsmṛtya saṃsmṛtya rūpam atyadbhutaṃ hareḥ |
vismayo me mahān rājan hṛṣyāmi ca punaḥ punaḥ ||', null, null),
  ('gita', 18, 78, null, null, 'यत्र योगेश्वरः कृष्णो यत्र पार्थो धनुर्धरः ।
तत्र श्रीर्विजयो भूतिर्ध्रुवा नीतिर्मतिर्मम ॥', 'yatra yogeśvaraḥ kṛṣṇo yatra pārtho dhanurdharaḥ |
tatra śrīr vijayo bhūtir dhruvā nītir matir mama ||', null, null)
  on conflict (scripture_id, chapter, verse) do nothing;
